const fn packet_plane_session_role_name(role: PacketPlaneSessionRole) -> &'static str {
    match role {
        PacketPlaneSessionRole::Initiator => "initiator",
        PacketPlaneSessionRole::Responder => "responder",
    }
}

fn extend_runtime_peer_state_lines(
    lines: &mut Vec<String>,
    forwarder: &Forwarder,
    paths: &PathSet,
    peer_capabilities: &PeerCapabilities,
    packet_plane: &PacketPlaneSnapshot,
    packet_plane_quic: &PacketPlaneQuicSnapshot,
    peer: PeerId,
    local_mtu: u16,
) {
    let transport = forwarder
        .transport_peer_for_overlay(peer)
        .map_or_else(|| "none".to_owned(), |peer| peer.to_string());
    let datagram_backend =
        local_packet_datagram_backend_from_snapshot(packet_plane, packet_plane_quic, peer);
    let support = packet_transport_support_for_backend(peer_capabilities, peer, datagram_backend);
    let selected_path = paths.best_supported_for(peer, support);
    let candidates = paths.candidates_for(peer).collect::<Vec<_>>();
    let healthy_paths = candidates
        .iter()
        .filter(|candidate| candidate.healthy)
        .count();
    let direct_paths = candidates
        .iter()
        .filter(|candidate| candidate.healthy && !candidate.relay)
        .count();
    let relay_paths = candidates
        .iter()
        .filter(|candidate| candidate.healthy && candidate.relay)
        .count();

    lines.push(format!(
        "peer state: {peer} transport {transport} validated {} effective_mtu {} quic_datagrams {} native_quic_datagrams {} owned_udp_packet_plane {} owned_quic_packet_plane {} selected_path {} selected_path_score {} selected_path_mtu {} selected_path_rtt_ms {} selected_path_relay_peer {} selected_path_connection_id {} selected_path_origin {} selected_path_connection_role {} selected_path_established_as_relayed {} selected_path_first_seen_unix_seconds {} selected_path_last_established_unix_seconds {} healthy_paths {healthy_paths} direct_paths {direct_paths} relay_paths {relay_paths}",
        peer_capabilities.contains(peer),
        peer_capabilities.effective_mtu_for(peer, local_mtu),
        support.quic_datagrams,
        peer_capabilities.supports_native_quic_datagrams_for(peer),
        peer_capabilities.supports_owned_udp_packet_plane_for(peer),
        peer_capabilities.supports_owned_quic_packet_plane_for(peer),
        selected_path.map_or("none", |path| path.kind.wire_name()),
        selected_path.map_or_else(|| "none".to_owned(), |path| path.score().to_string()),
        selected_path.map_or_else(
            || "none".to_owned(),
            |path| path
                .effective_mtu(peer_capabilities.effective_mtu_for(peer, local_mtu))
                .to_string()
        ),
        selected_path.map_or_else(|| "unknown".to_owned(), path_rtt_value),
        selected_path.map_or_else(|| "none".to_owned(), relay_peer_value),
        selected_path.map_or_else(|| "unknown".to_owned(), path_connection_id_value),
        selected_path.map_or("unknown", |path| path.origin.wire_name()),
        selected_path.map_or("unknown", |path| path.connection_role.wire_name()),
        selected_path.is_some_and(|path| path.established_as_relayed),
        selected_path
            .and_then(|path| path.first_seen_unix_seconds)
            .map_or_else(|| "unknown".to_owned(), |seconds| seconds.to_string()),
        selected_path
            .and_then(|path| path.last_established_unix_seconds)
            .map_or_else(|| "unknown".to_owned(), |seconds| seconds.to_string()),
    ));

    if let Some(capabilities) = peer_capabilities.get(peer) {
        lines.push(format!(
            "peer capability state: {peer} preferred_path {} advertised_routes {}",
            capabilities.preferred_path,
            capabilities.advertised_routes.len()
        ));
    }

    for candidate in candidates {
        let peer_mtu = peer_capabilities.effective_mtu_for(peer, local_mtu);
        lines.push(format!(
            "peer path state: {peer} {} healthy {} relay {} relay_peer {} established_connections {} score {} estimated_mtu {} effective_mtu {} observed_rtt_ms {} connection_id {} origin {} connection_role {} established_as_relayed {} first_seen_unix_seconds {} last_established_unix_seconds {}",
            candidate.kind.wire_name(),
            candidate.healthy,
            candidate.relay,
            relay_peer_value(candidate),
            candidate.established_connections,
            candidate.score(),
            candidate
                .estimated_mtu
                .map_or_else(|| "unknown".to_owned(), |mtu| mtu.to_string()),
            candidate.effective_mtu(peer_mtu),
            path_rtt_value(candidate),
            path_connection_id_value(candidate),
            candidate.origin.wire_name(),
            candidate.connection_role.wire_name(),
            candidate.established_as_relayed,
            candidate
                .first_seen_unix_seconds
                .map_or_else(|| "unknown".to_owned(), |seconds| seconds.to_string()),
            candidate
                .last_established_unix_seconds
                .map_or_else(|| "unknown".to_owned(), |seconds| seconds.to_string())
        ));
    }
}

fn local_packet_datagram_backend_from_snapshot(
    packet_plane: &PacketPlaneSnapshot,
    packet_plane_quic: &PacketPlaneQuicSnapshot,
    peer: PeerId,
) -> Option<PacketDatagramBackend> {
    if packet_plane_quic
        .sessions
        .iter()
        .any(|session| session.peer == peer)
    {
        return Some(PacketDatagramBackend::OwnedQuic);
    }
    if packet_plane
        .sessions
        .iter()
        .any(|session| session.peer == peer)
    {
        return Some(PacketDatagramBackend::OwnedUdp);
    }
    None
}

fn handle_redial_tick(
    node: &mut P2pNode,
    forwarder: &Forwarder,
    discovered_peer_addresses: &mut DiscoveredPeerAddresses,
    paths: &PathSet,
    relay_readiness: &mut RelayReadiness,
    configured_relay_reservation_retries: &mut ConfiguredRelayReservationRetries,
    public_discovery_backoff: &PublicDiscoveryBackoff,
    public_discovery_quiet: bool,
    metrics: &RuntimeMetrics,
) {
    expire_discovered_peer_addresses(discovered_peer_addresses, metrics);
    retry_configured_relay_reservations(
        &mut node.swarm,
        &node.relay_reservation_addresses,
        relay_readiness,
        configured_relay_reservation_retries,
    );
    if !public_discovery_quiet && should_query_configured_peer_recovery_discovery(&node.discovery) {
        query_configured_peer_recovery_discovery(
            &mut node.swarm,
            &node.network_name,
            node.membership_tag.as_deref(),
            forwarder.configured_transport_peers(),
            paths,
            discovered_peer_addresses,
            metrics,
        );
    }
    let discovered_addresses = discovered_peer_addresses.redial_candidates_at(Instant::now());
    let now = Instant::now();
    let bootstrap_addresses = if public_discovery_quiet {
        Vec::new()
    } else {
        node.bootstrap_peer_addresses
            .iter()
            .filter(|(peer, _)| public_discovery_backoff.should_dial_bootstrap_peer(*peer, now))
            .cloned()
            .collect::<Vec<_>>()
    };
    redial_known_addresses(
        &mut node.swarm,
        &bootstrap_addresses,
        &node.relay_peer_addresses,
        &node.configured_peer_addresses,
        &discovered_addresses,
        discovered_peer_addresses,
        paths,
        metrics,
        |relay| relay_readiness.relay_ready(relay),
    );
    for relay in relay_readiness.ready_relays() {
        dial_relay_ready_configured_peers(
            &mut node.swarm,
            forwarder,
            relay_readiness,
            &node.relay_peer_addresses,
            &node.configured_peer_addresses,
            discovered_peer_addresses,
            paths,
            metrics,
            relay,
        );
    }
}

fn query_configured_peer_recovery_discovery(
    swarm: &mut Swarm<Behaviour>,
    network_name: &str,
    membership_tag: Option<&str>,
    configured_peers: impl IntoIterator<Item = Libp2pPeerId>,
    paths: &PathSet,
    recovery_state: &mut DiscoveredPeerAddresses,
    metrics: &RuntimeMetrics,
) {
    for peer in configured_peer_recovery_discovery_targets(
        *swarm.local_peer_id(),
        configured_peers,
        |candidate| redial_connection_state(paths, *candidate, swarm.is_connected(candidate)),
    ) {
        query_configured_peer_recovery_discovery_for_peer(
            swarm,
            network_name,
            membership_tag,
            peer,
            recovery_state,
            metrics,
            "periodic",
        );
    }
}

fn query_configured_peer_recovery_discovery_for_peer(
    swarm: &mut Swarm<Behaviour>,
    network_name: &str,
    membership_tag: Option<&str>,
    peer: Libp2pPeerId,
    recovery_state: &mut DiscoveredPeerAddresses,
    metrics: &RuntimeMetrics,
    reason: &'static str,
) -> bool {
    let now = Instant::now();
    if !recovery_state.should_query_recovery_discovery_at(peer, now) {
        return false;
    }
    let record_query =
        swarm
            .behaviour_mut()
            .kad
            .get_record(crate::runtime::p2p::kademlia_peer_addresses_key(
                network_name,
                membership_tag,
                peer,
            ));
    let closest_query = swarm.behaviour_mut().kad.get_closest_peers(peer);
    recovery_state.record_recovery_discovery_queries(peer, [record_query, closest_query], now);
    metrics.record_kademlia_provider_lookup();
    log_runtime_event(
        LogLevel::Info,
        "peer_recovery_discovery_query",
        &[("peer", &peer.to_string()), ("reason", reason)],
    );
    true
}

fn should_query_configured_peer_recovery_discovery(discovery: &DiscoveryConfig) -> bool {
    discovery.kademlia
}

fn configured_peer_recovery_discovery_targets(
    local_peer: Libp2pPeerId,
    configured_peers: impl IntoIterator<Item = Libp2pPeerId>,
    mut connection_state: impl FnMut(&Libp2pPeerId) -> RedialConnectionState,
) -> Vec<Libp2pPeerId> {
    configured_peers
        .into_iter()
        .filter(|peer| *peer != local_peer)
        .filter(|peer| {
            matches!(
                connection_state(peer),
                RedialConnectionState::Disconnected | RedialConnectionState::ConnectedNoUsablePath
            )
        })
        .collect()
}

fn retry_configured_relay_reservations(
    swarm: &mut Swarm<Behaviour>,
    relay_reservation_addresses: &[Multiaddr],
    relay_readiness: &RelayReadiness,
    retries: &mut ConfiguredRelayReservationRetries,
) {
    let now = Instant::now();
    for address in relay_reservation_addresses {
        let Some(relay) = relayed_address_relay_peer(address) else {
            continue;
        };
        if relay_readiness.relay_ready(relay) || !retries.should_retry(address, now) {
            continue;
        }

        let listen_address = address.clone();
        log_runtime_event(
            LogLevel::Info,
            "configured_relay_reservation_retry",
            &[
                ("relay", &relay.to_string()),
                ("address", &listen_address.to_string()),
            ],
        );
        if let Err(error) = swarm.listen_on(listen_address.clone()) {
            log_runtime_event(
                LogLevel::Warn,
                "configured_relay_reservation_retry_failed",
                &[
                    ("relay", &relay.to_string()),
                    ("address", &listen_address.to_string()),
                    ("error", &error.to_string()),
                ],
            );
        }
    }
}

fn log_startup_status(startup: crate::runtime::p2p::StartupStatus) {
    if startup.mdns_enabled {
        log_runtime_event(LogLevel::Info, "mdns_enabled", &[]);
    }
    if startup.external_addresses_configured > 0 {
        log_runtime_event(
            LogLevel::Info,
            "external_addresses_configured",
            &[("count", &startup.external_addresses_configured.to_string())],
        );
    }
    if startup.dcutr_enabled {
        log_runtime_event(LogLevel::Info, "dcutr_enabled", &[]);
    }
    if startup.autonat_enabled {
        log_runtime_event(LogLevel::Info, "autonat_enabled", &[]);
    }
    if startup.autonat_servers_registered > 0 {
        log_runtime_event(
            LogLevel::Info,
            "autonat_servers_registered",
            &[("count", &startup.autonat_servers_registered.to_string())],
        );
    }
    if startup.kademlia.bootstrap_started {
        log_runtime_event(LogLevel::Info, "kademlia_bootstrap_started", &[]);
    }
    if startup.kademlia.rendezvous_advertise_started {
        log_runtime_event(LogLevel::Info, "kademlia_provider_advertise_started", &[]);
    }
    if startup.kademlia.rendezvous_lookup_started {
        log_runtime_event(LogLevel::Info, "kademlia_provider_lookup_started", &[]);
    }
    if startup.relay_reservations_started > 0 {
        log_runtime_event(
            LogLevel::Info,
            "relay_reservation_listeners_started",
            &[("count", &startup.relay_reservations_started.to_string())],
        );
    }
    if startup.relay_server_enabled {
        log_runtime_event(LogLevel::Info, "relay_server_enabled", &[]);
    }
}

fn log_packet_plane_status(packet_plane: PacketPlaneSnapshot) {
    if packet_plane.listeners.is_empty() {
        return;
    }
    log_runtime_event(
        LogLevel::Info,
        "packet_plane_listening",
        &[("count", &packet_plane.listeners.len().to_string())],
    );
    for listener in packet_plane.listeners {
        log_runtime_event(
            LogLevel::Info,
            "packet_plane_listener",
            &[("address", &listener.to_string())],
        );
    }
}

fn log_packet_plane_quic_status(packet_plane_quic: &PacketPlaneQuicSnapshot) {
    let Some(listener) = packet_plane_quic.listener else {
        return;
    };
    log_runtime_event(
        LogLevel::Info,
        "packet_plane_quic_listening",
        &[
            ("address", &listener.to_string()),
            (
                "certificate_bytes",
                &packet_plane_quic
                    .certificate_der
                    .as_ref()
                    .map_or(0, Vec::len)
                    .to_string(),
            ),
        ],
    );
}

fn current_packet_plane_quic_snapshot(
    packet_plane_quic: Option<&PacketPlaneQuicRuntime>,
) -> PacketPlaneQuicSnapshot {
    packet_plane_quic.map_or_else(
        PacketPlaneQuicRuntime::disabled_snapshot,
        PacketPlaneQuicRuntime::snapshot,
    )
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum LogLevel {
    Info,
    Warn,
    Error,
}

impl LogLevel {
    const fn as_str(self) -> &'static str {
        match self {
            Self::Info => "info",
            Self::Warn => "warn",
            Self::Error => "error",
        }
    }
}

fn log_runtime_event(level: LogLevel, event: &str, fields: &[(&str, &str)]) {
    eprintln!("{}", runtime_log_line(level, event, fields));
}

fn runtime_log_line(level: LogLevel, event: &str, fields: &[(&str, &str)]) -> String {
    let mut line = format!("level={} event={}", level.as_str(), event);
    for (key, value) in fields {
        line.push(' ');
        line.push_str(key);
        line.push('=');
        push_log_value(&mut line, value);
    }
    line
}

fn push_log_value(line: &mut String, value: &str) {
    if value.bytes().all(|byte| {
        byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'-' | b'_' | b':' | b'/')
    }) {
        line.push_str(value);
        return;
    }

    line.push('"');
    for character in value.chars() {
        match character {
            '"' => line.push_str("\\\""),
            '\\' => line.push_str("\\\\"),
            '\n' => line.push_str("\\n"),
            '\r' => line.push_str("\\r"),
            '\t' => line.push_str("\\t"),
            other => line.push(other),
        }
    }
    line.push('"');
}

fn queue_expiry_interval(max_packet_age: Duration) -> Duration {
    max_packet_age.clamp(MIN_QUEUE_EXPIRY_INTERVAL, REDIAL_INTERVAL)
}

fn expire_outbound_queue(queues: &mut PeerQueues, metrics: &RuntimeMetrics) {
    let expired_before = queues.total_stats().expired_packets;
    queues.drop_expired(std::time::Instant::now());
    let expired_after = queues.total_stats().expired_packets;
    metrics.record_outbound_queue_expired(expired_after.saturating_sub(expired_before));
}

fn expire_discovered_peer_addresses(
    discovered_peer_addresses: &mut DiscoveredPeerAddresses,
    metrics: &RuntimeMetrics,
) {
    let expired = discovered_peer_addresses.drop_expired(Instant::now(), DISCOVERED_ADDRESS_TTL);
    metrics.record_discovered_address_expired(expired);
}

struct KademliaRefreshContext<'a> {
    advertise_key: &'a kad::RecordKey,
    lookup_keys: &'a [kad::RecordKey],
    membership_record_advertise_key: Option<&'a kad::RecordKey>,
    membership_record_lookup_keys: &'a [kad::RecordKey],
    network_name: &'a str,
    membership_tag: Option<&'a str>,
    forwarder: &'a Forwarder,
    identity: &'a NodeIdentity,
    advertise_provider: bool,
    auto_relay: &'a AutoRelayState,
    public_discovery_backoff: &'a PublicDiscoveryBackoff,
    public_discovery_quiet: bool,
    metrics: &'a RuntimeMetrics,
}

fn refresh_kademlia_rendezvous(swarm: &mut Swarm<Behaviour>, context: &KademliaRefreshContext<'_>) {
    if context.public_discovery_quiet {
        return;
    }

    if context.auto_relay.should_discover_candidates() {
        query_auto_relay_infrastructure(swarm, context.metrics, "kademlia_refresh");
    }

    publish_kademlia_peer_address_record(
        swarm,
        context.network_name,
        context.membership_tag,
        context.identity,
    );

    for peer in context.forwarder.configured_transport_peers() {
        if peer != *swarm.local_peer_id() {
            swarm
                .behaviour_mut()
                .kad
                .get_record(crate::runtime::p2p::kademlia_peer_addresses_key(
                    context.network_name,
                    context.membership_tag,
                    peer,
                ));
            swarm.behaviour_mut().kad.get_closest_peers(peer);
        }
    }

    if context.advertise_provider {
        match swarm
            .behaviour_mut()
            .kad
            .start_providing(context.advertise_key.clone())
        {
            Ok(_) => context.metrics.record_kademlia_provider_advertisement(),
            Err(error) => {
                context
                    .metrics
                    .record_kademlia_provider_advertisement_failure();
                log_runtime_event(
                    LogLevel::Warn,
                    "kademlia_provider_advertisement_failed",
                    &[("error", &format!("{error:?}"))],
                );
            }
        }
    }

    for lookup_key in context.lookup_keys {
        swarm.behaviour_mut().kad.get_providers(lookup_key.clone());
        context.metrics.record_kademlia_provider_lookup();
    }

    if context.advertise_provider
        && let Some(record_key) = context.membership_record_advertise_key
    {
        publish_kademlia_membership_records(
            swarm,
            record_key,
            context.network_name,
            context.membership_tag,
            context.forwarder,
            context.metrics,
        );
    }

    for lookup_key in context.membership_record_lookup_keys {
        swarm.behaviour_mut().kad.get_record(lookup_key.clone());
        context.metrics.record_kademlia_membership_record_lookup();
    }

    if !context.public_discovery_backoff.suppresses(Instant::now()) {
        match swarm.behaviour_mut().kad.bootstrap() {
            Ok(_) => context.metrics.record_kademlia_bootstrap_refresh(),
            Err(error) => {
                context.metrics.record_kademlia_bootstrap_failure();
                log_runtime_event(
                    LogLevel::Warn,
                    "kademlia_bootstrap_failed",
                    &[("error", &format!("{error:?}"))],
                );
            }
        }
    }
}

fn publish_kademlia_membership_records(
    swarm: &mut Swarm<Behaviour>,
    record_key: &kad::RecordKey,
    network_name: &str,
    membership_tag: Option<&str>,
    forwarder: &Forwarder,
    metrics: &RuntimeMetrics,
) {
    let records = advertised_member_records(forwarder);
    if records.is_empty() {
        return;
    }

    let Ok(value) = encode_kademlia_membership_records(network_name, membership_tag, records)
    else {
        metrics.record_kademlia_membership_record_publication_failure();
        log_runtime_event(
            LogLevel::Warn,
            "kademlia_membership_record_publication_failed",
            &[("reason", "encode_failed")],
        );
        return;
    };
    let record = kad::Record {
        key: record_key.clone(),
        value,
        publisher: Some(*swarm.local_peer_id()),
        expires: None,
    };

    match swarm
        .behaviour_mut()
        .kad
        .put_record(record, kad::Quorum::One)
    {
        Ok(_) => metrics.record_kademlia_membership_record_publication(),
        Err(error) => {
            metrics.record_kademlia_membership_record_publication_failure();
            log_runtime_event(
                LogLevel::Warn,
                "kademlia_membership_record_publication_failed",
                &[("error", &format!("{error:?}"))],
            );
        }
    }
}

#[derive(Debug, Deserialize, Serialize)]
struct KademliaPeerAddressRecordPayload {
    version: u8,
    network_name: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    membership_tag: Option<String>,
    peer_id: String,
    public_key_protobuf: Vec<u8>,
    sequence: u64,
    expires_at_unix_seconds: u64,
    addresses: Vec<String>,
}

#[derive(Debug, Deserialize, Serialize)]
struct KademliaPeerAddressRecord {
    payload: KademliaPeerAddressRecordPayload,
    signature: Vec<u8>,
}

#[derive(Debug)]
enum KademliaPeerAddressRecordError {
    NoAddresses,
    TooLarge,
    Decode,
    Encode,
    UnsupportedVersion,
    WrongNetwork,
    WrongMembershipScope,
    WrongPeer,
    InvalidPeerId,
    InvalidPublicKey,
    InvalidSignature,
    Expired,
    TooManyAddresses,
}

impl std::fmt::Display for KademliaPeerAddressRecordError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NoAddresses => formatter.write_str("no_addresses"),
            Self::TooLarge => formatter.write_str("too_large"),
            Self::Decode => formatter.write_str("decode_failed"),
            Self::Encode => formatter.write_str("encode_failed"),
            Self::UnsupportedVersion => formatter.write_str("unsupported_version"),
            Self::WrongNetwork => formatter.write_str("wrong_network"),
            Self::WrongMembershipScope => formatter.write_str("wrong_membership_scope"),
            Self::WrongPeer => formatter.write_str("wrong_peer"),
            Self::InvalidPeerId => formatter.write_str("invalid_peer_id"),
            Self::InvalidPublicKey => formatter.write_str("invalid_public_key"),
            Self::InvalidSignature => formatter.write_str("invalid_signature"),
            Self::Expired => formatter.write_str("expired"),
            Self::TooManyAddresses => formatter.write_str("too_many_addresses"),
        }
    }
}

fn publish_kademlia_peer_address_record(
    swarm: &mut Swarm<Behaviour>,
    network_name: &str,
    membership_tag: Option<&str>,
    identity: &NodeIdentity,
) {
    let addresses = local_advertisable_addresses(swarm);
    let key = crate::runtime::p2p::kademlia_peer_addresses_key(
        network_name,
        membership_tag,
        *swarm.local_peer_id(),
    );
    let value = match encode_kademlia_peer_address_record(
        network_name,
        membership_tag,
        identity,
        addresses,
        current_unix_seconds_lossy(),
    ) {
        Ok(value) => value,
        Err(error) => {
            if !matches!(error, KademliaPeerAddressRecordError::NoAddresses) {
                log_runtime_event(
                    LogLevel::Warn,
                    "kademlia_peer_address_record_publication_failed",
                    &[("reason", &error.to_string())],
                );
            }
            return;
        }
    };
    let record = kad::Record {
        key,
        value,
        publisher: Some(*swarm.local_peer_id()),
        expires: None,
    };

    if let Err(error) = swarm
        .behaviour_mut()
        .kad
        .put_record(record, kad::Quorum::One)
    {
        log_runtime_event(
            LogLevel::Warn,
            "kademlia_peer_address_record_publication_failed",
            &[("error", &format!("{error:?}"))],
        );
    }
}

fn publish_kademlia_peer_address_record_for_capabilities(
    swarm: &mut Swarm<Behaviour>,
    discovery: &DiscoveryConfig,
    local_capabilities: &ControlCapabilities,
    identity: &NodeIdentity,
) {
    if !discovery.kademlia {
        return;
    }

    publish_kademlia_peer_address_record(
        swarm,
        &local_capabilities.network_name,
        local_capabilities.membership_tag.as_deref(),
        identity,
    );
}

fn local_advertisable_addresses(swarm: &Swarm<Behaviour>) -> Vec<Multiaddr> {
    let mut addresses = Vec::new();
    let confirmed_external_addresses = swarm
        .external_addresses()
        .cloned()
        .collect::<HashSet<Multiaddr>>();
    for address in swarm.listeners().chain(swarm.external_addresses()) {
        if addresses.len() >= MAX_KADEMLIA_PEER_ADDRESS_RECORD_ADDRESSES {
            break;
        }
        if !kademlia_peer_address_is_confirmed_for_publication(
            address,
            &confirmed_external_addresses,
        ) {
            continue;
        }
        if kademlia_peer_address_is_advertisable(address) && !addresses.contains(address) {
            addresses.push(address.clone());
        }
    }
    addresses
}

fn kademlia_peer_address_is_confirmed_for_publication(
    address: &Multiaddr,
    confirmed_external_addresses: &HashSet<Multiaddr>,
) -> bool {
    relayed_address_relay_peer(address).is_some()
        || confirmed_external_addresses.contains(address)
        || kademlia_peer_address_is_private_direct_listener(address)
}

fn kademlia_peer_address_is_private_direct_listener(address: &Multiaddr) -> bool {
    if address
        .iter()
        .any(|protocol| matches!(protocol, Protocol::P2pCircuit))
    {
        return false;
    }

    address.iter().any(|protocol| match protocol {
        Protocol::Ip4(address) => ipv4_address_is_private_lan(address),
        Protocol::Ip6(address) => ipv6_address_is_private_lan(address),
        _ => false,
    })
}

fn kademlia_peer_address_is_advertisable(address: &Multiaddr) -> bool {
    if address
        .iter()
        .any(|protocol| matches!(protocol, Protocol::P2pCircuit))
    {
        return supports_relayed_peer_dial_transport(address)
            && relayed_address_uses_public_relay_transport(address);
    }

    address.iter().any(|protocol| match protocol {
        Protocol::Dns(_) | Protocol::Dns4(_) | Protocol::Dns6(_) | Protocol::Dnsaddr(_) => true,
        Protocol::Ip4(address) => ipv4_address_is_advertisable(address),
        Protocol::Ip6(address) => ipv6_address_is_advertisable(address),
        _ => false,
    })
}

fn ipv4_address_is_advertisable(address: Ipv4Addr) -> bool {
    let [first, second, _, _] = address.octets();
    !(address.is_unspecified()
        || address.is_loopback()
        || address.is_link_local()
        || address.is_broadcast()
        || address.is_documentation()
        || address.is_multicast()
        || (first == 10 && second == 42)
        || (first == 100 && (64..=127).contains(&second)))
}

fn ipv4_address_is_private_lan(address: Ipv4Addr) -> bool {
    let [first, second, _, _] = address.octets();
    (first == 10)
        || (first == 172 && (16..=31).contains(&second))
        || (first == 192 && second == 168)
}

fn ipv6_address_is_advertisable(address: Ipv6Addr) -> bool {
    let segments = address.segments();
    let first = segments[0];
    !(address.is_unspecified()
        || address.is_loopback()
        || address.is_multicast()
        || (first & 0xfe00) == 0xfc00
        || (first & 0xffc0) == 0xfe80
        || (first == 0x2001 && segments[1] == 0x0db8))
}

fn ipv6_address_is_private_lan(address: Ipv6Addr) -> bool {
    (address.segments()[0] & 0xfe00) == 0xfc00
}

fn encode_kademlia_peer_address_record(
    network_name: &str,
    membership_tag: Option<&str>,
    identity: &NodeIdentity,
    addresses: Vec<Multiaddr>,
    now_unix_seconds: u64,
) -> Result<Vec<u8>, KademliaPeerAddressRecordError> {
    if addresses.is_empty() {
        return Err(KademliaPeerAddressRecordError::NoAddresses);
    }
    let payload = KademliaPeerAddressRecordPayload {
        version: 1,
        network_name: network_name.to_owned(),
        membership_tag: membership_tag.map(str::to_owned),
        peer_id: identity.peer_id.clone(),
        public_key_protobuf: identity
            .public_key_protobuf()
            .map_err(|_| KademliaPeerAddressRecordError::InvalidPublicKey)?,
        sequence: now_unix_seconds,
        expires_at_unix_seconds: now_unix_seconds + KADEMLIA_PEER_ADDRESS_RECORD_TTL,
        addresses: addresses
            .into_iter()
            .map(|address| address.to_string())
            .collect(),
    };
    let payload_bytes =
        serde_json::to_vec(&payload).map_err(|_| KademliaPeerAddressRecordError::Encode)?;
    let signature = identity
        .sign(&payload_bytes)
        .map_err(|_| KademliaPeerAddressRecordError::InvalidSignature)?;
    serde_json::to_vec(&KademliaPeerAddressRecord { payload, signature })
        .map_err(|_| KademliaPeerAddressRecordError::Encode)
}

fn learn_peer_addresses_from_kademlia_value(
    forwarder: &Forwarder,
    expected_network_name: &str,
    current_membership_tag: Option<&str>,
    previous_membership_tags: &[String],
    value: &[u8],
) -> Result<(Libp2pPeerId, Vec<Multiaddr>), KademliaPeerAddressRecordError> {
    if value.len() > MAX_KADEMLIA_PEER_ADDRESS_RECORD_BYTES {
        return Err(KademliaPeerAddressRecordError::TooLarge);
    }
    let record: KademliaPeerAddressRecord =
        serde_json::from_slice(value).map_err(|_| KademliaPeerAddressRecordError::Decode)?;
    let payload_bytes =
        serde_json::to_vec(&record.payload).map_err(|_| KademliaPeerAddressRecordError::Encode)?;
    if record.payload.version != 1 {
        return Err(KademliaPeerAddressRecordError::UnsupportedVersion);
    }
    if record.payload.network_name != expected_network_name {
        return Err(KademliaPeerAddressRecordError::WrongNetwork);
    }
    if !membership_tag_allowed(
        record.payload.membership_tag.as_deref(),
        current_membership_tag,
        previous_membership_tags,
    ) {
        return Err(KademliaPeerAddressRecordError::WrongMembershipScope);
    }
    if record
        .payload
        .expires_at_unix_seconds
        .saturating_add(KADEMLIA_PEER_ADDRESS_RECORD_STALE_GRACE)
        < current_unix_seconds_lossy()
    {
        return Err(KademliaPeerAddressRecordError::Expired);
    }
    if record.payload.addresses.len() > MAX_KADEMLIA_PEER_ADDRESS_RECORD_ADDRESSES {
        return Err(KademliaPeerAddressRecordError::TooManyAddresses);
    }
    let peer = record
        .payload
        .peer_id
        .parse::<Libp2pPeerId>()
        .map_err(|_| KademliaPeerAddressRecordError::InvalidPeerId)?;
    if !forwarder.is_configured_transport_peer(peer) {
        return Err(KademliaPeerAddressRecordError::WrongPeer);
    }
    let public_key =
        libp2p::identity::PublicKey::try_decode_protobuf(&record.payload.public_key_protobuf)
            .map_err(|_| KademliaPeerAddressRecordError::InvalidPublicKey)?;
    if Libp2pPeerId::from_public_key(&public_key) != peer {
        return Err(KademliaPeerAddressRecordError::InvalidPublicKey);
    }
    if !public_key.verify(&payload_bytes, &record.signature) {
        return Err(KademliaPeerAddressRecordError::InvalidSignature);
    }
    let addresses = record
        .payload
        .addresses
        .iter()
        .filter_map(|address| address.parse::<Multiaddr>().ok())
        .filter(|address| address_targets_peer(peer, address))
        .collect::<Vec<_>>();
    if addresses.is_empty() {
        return Err(KademliaPeerAddressRecordError::NoAddresses);
    }
    Ok((peer, addresses))
}

fn kademlia_query_result_key(result: &kad::QueryResult) -> Option<&kad::RecordKey> {
    match result {
        kad::QueryResult::GetRecord(Ok(kad::GetRecordOk::FoundRecord(peer_record))) => {
            Some(&peer_record.record.key)
        }
        kad::QueryResult::GetRecord(Err(kad::GetRecordError::NotFound { key, .. }))
        | kad::QueryResult::GetRecord(Err(kad::GetRecordError::QuorumFailed { key, .. }))
        | kad::QueryResult::GetRecord(Err(kad::GetRecordError::Timeout { key, .. })) => Some(key),
        kad::QueryResult::PutRecord(Ok(kad::PutRecordOk { key }))
        | kad::QueryResult::PutRecord(Err(kad::PutRecordError::QuorumFailed { key, .. }))
        | kad::QueryResult::PutRecord(Err(kad::PutRecordError::Timeout { key, .. })) => Some(key),
        _ => None,
    }
}

fn kademlia_key_is_peer_address_record(key: &kad::RecordKey) -> bool {
    std::str::from_utf8(key.as_ref()).is_ok_and(|key| key.contains("/peer-addresses/"))
}

fn kademlia_lookup_keys(
    network_name: &str,
    current_key: Option<&kad::RecordKey>,
    previous_membership_tags: &[String],
) -> Vec<kad::RecordKey> {
    let Some(current_key) = current_key else {
        return Vec::new();
    };
    let mut keys = vec![current_key.clone()];
    for tag in previous_membership_tags {
        let key = crate::runtime::p2p::kademlia_rendezvous_key(network_name, Some(tag));
        if !keys.contains(&key) {
            keys.push(key);
        }
    }
    keys
}

fn kademlia_membership_record_lookup_keys(
    network_name: &str,
    current_membership_tag: Option<&str>,
    current_key: Option<&kad::RecordKey>,
    previous_membership_tags: &[String],
) -> Vec<kad::RecordKey> {
    let Some(current_key) = current_key else {
        return Vec::new();
    };
    let mut keys = vec![current_key.clone()];
    for tag in previous_membership_tags {
        let key = crate::runtime::p2p::kademlia_membership_records_key(network_name, Some(tag));
        if !keys.contains(&key) {
            keys.push(key);
        }
    }
    if current_membership_tag.is_none() {
        return keys;
    }
    let untagged_key = crate::runtime::p2p::kademlia_membership_records_key(network_name, None);
    if !keys.contains(&untagged_key) {
        keys.push(untagged_key);
    }
    keys
}

#[allow(clippy::too_many_arguments)]
fn reconcile_runtime_kademlia_scope(
    node: &mut P2pNode,
    local_capabilities: &ControlCapabilities,
    previous_membership_tags: &[String],
    rendezvous_key: &mut Option<kad::RecordKey>,
    lookup_keys: &mut Vec<kad::RecordKey>,
    membership_records_key: &mut Option<kad::RecordKey>,
    membership_record_lookup_keys: &mut Vec<kad::RecordKey>,
) {
    if node.membership_tag == local_capabilities.membership_tag {
        return;
    }
    if let Some(key) = rendezvous_key.as_ref() {
        node.swarm.behaviour_mut().kad.stop_providing(key);
    }
    if let Some(key) = membership_records_key.as_ref() {
        node.swarm.behaviour_mut().kad.stop_providing(key);
    }

    node.membership_tag = local_capabilities.membership_tag.clone();
    *rendezvous_key = node.discovery.kademlia.then(|| {
        crate::runtime::p2p::kademlia_rendezvous_key(
            &node.network_name,
            node.membership_tag.as_deref(),
        )
    });
    *membership_records_key = node.discovery.kademlia.then(|| {
        crate::runtime::p2p::kademlia_membership_records_key(
            &node.network_name,
            node.membership_tag.as_deref(),
        )
    });
    *lookup_keys = kademlia_lookup_keys(
        &node.network_name,
        rendezvous_key.as_ref(),
        previous_membership_tags,
    );
    *membership_record_lookup_keys = kademlia_membership_record_lookup_keys(
        &node.network_name,
        node.membership_tag.as_deref(),
        membership_records_key.as_ref(),
        previous_membership_tags,
    );
    node.kademlia_rendezvous_key.clone_from(rendezvous_key);
    node.kademlia_membership_records_key
        .clone_from(membership_records_key);
    log_runtime_event(
        LogLevel::Info,
        "runtime_membership_scope_reconfigured",
        &[(
            "membership_scoped",
            &node.membership_tag.is_some().to_string(),
        )],
    );
}

fn redial_known_addresses(
    swarm: &mut Swarm<Behaviour>,
    bootstrap_addresses: &[(Libp2pPeerId, Multiaddr)],
    relay_addresses: &[(Libp2pPeerId, Multiaddr)],
    configured_peer_addresses: &[(Libp2pPeerId, Multiaddr)],
    discovered_peer_addresses: &[(Libp2pPeerId, Multiaddr)],
    discovered_address_state: &mut DiscoveredPeerAddresses,
    paths: &PathSet,
    metrics: &RuntimeMetrics,
    relay_ready: impl FnMut(Libp2pPeerId) -> bool,
) {
    let local_peer = *swarm.local_peer_id();
    let targets = pending_redial_targets(
        local_peer,
        bootstrap_addresses,
        relay_addresses,
        configured_peer_addresses,
        discovered_peer_addresses,
        |peer| redial_connection_state(paths, *peer, swarm.is_connected(peer)),
        relay_ready,
    );

    for _ in 0..targets.skipped_connected {
        metrics.record_redial_skipped_connected();
    }

    for (peer, address) in targets.addresses {
        let now = Instant::now();
        if !discovered_address_state.should_attempt_recovery_dial_at(peer, &address, now) {
            continue;
        }
        metrics.record_redial_attempt();
        let dial_address = peer_dial_address(peer, address.clone());
        if let Err(error) = swarm.dial(dial_address.clone()) {
            discovered_address_state.record_recovery_dial_failure_at(peer, &address, now);
            let discovered = discovered_address_state.record_failure_at(peer, &address, now);
            metrics.record_redial_failure();
            log_runtime_event(
                LogLevel::Warn,
                "redial_failed",
                &[
                    ("peer", &peer.to_string()),
                    ("address", &dial_address.to_string()),
                    ("error", &error.to_string()),
                    ("discovered", &discovered.to_string()),
                ],
            );
        }
    }
}

#[derive(Debug, Default)]
struct RelayReadiness {
    accepted_reservations: HashSet<Libp2pPeerId>,
    relayed_listen_addresses: HashMap<Libp2pPeerId, Vec<Multiaddr>>,
}

#[derive(Debug, Default)]
struct ConfiguredRelayReservationRetries {
    last_attempts: HashMap<Multiaddr, Instant>,
}

impl ConfiguredRelayReservationRetries {
    fn from_startup_attempts(addresses: &[Multiaddr], now: Instant) -> Self {
        Self {
            last_attempts: addresses
                .iter()
                .cloned()
                .map(|address| (address, now))
                .collect(),
        }
    }

    fn should_retry(&mut self, address: &Multiaddr, now: Instant) -> bool {
        if self.last_attempts.get(address).is_some_and(|last_attempt| {
            now.saturating_duration_since(*last_attempt) < REDIAL_INTERVAL
        }) {
            return false;
        }
        self.last_attempts.insert(address.clone(), now);
        true
    }
}

#[derive(Debug, Default)]
struct PublicDiscoveryBackoff {
    bootstrap_peers: HashSet<Libp2pPeerId>,
    consecutive_no_route_failures: u32,
    suppressed_until: Option<Instant>,
}

impl PublicDiscoveryBackoff {
    fn from_bootstrap_defaults(enabled: bool) -> Self {
        if !enabled {
            return Self::default();
        }

        let bootstrap_peers = public_ipfs_bootstrap_peer_configs()
            .into_iter()
            .filter_map(|peer| peer.peer_address().ok().map(|(peer, _)| peer))
            .collect();
        Self {
            bootstrap_peers,
            consecutive_no_route_failures: 0,
            suppressed_until: None,
        }
    }

    fn suppresses(&self, now: Instant) -> bool {
        self.suppressed_until.is_some_and(|until| now < until)
    }

    fn should_dial_bootstrap_peer(&self, peer: Libp2pPeerId, now: Instant) -> bool {
        !self.bootstrap_peers.contains(&peer) || !self.suppresses(now)
    }

    fn record_connection_established(&mut self, peer: Libp2pPeerId) {
        if self.bootstrap_peers.contains(&peer) {
            self.consecutive_no_route_failures = 0;
            self.suppressed_until = None;
        }
    }

    fn record_outgoing_error(
        &mut self,
        peer: Option<Libp2pPeerId>,
        error: &DialError,
        now: Instant,
    ) -> Option<Duration> {
        let Some(peer) = peer else {
            return None;
        };
        if !self.bootstrap_peers.contains(&peer)
            || !dial_error_reports_public_bootstrap_failure(error)
        {
            return None;
        }
        if self.suppresses(now) {
            return None;
        }

        self.consecutive_no_route_failures = self.consecutive_no_route_failures.saturating_add(1);
        let shift = self.consecutive_no_route_failures.saturating_sub(1).min(8);
        let multiplier = 1_u32 << shift;
        let delay = PUBLIC_DISCOVERY_BACKOFF_BASE
            .saturating_mul(multiplier)
            .min(PUBLIC_DISCOVERY_BACKOFF_MAX);
        self.suppressed_until = Some(now + delay);
        Some(delay)
    }
}

#[derive(Debug)]
struct AutoRelayState {
    policy: AutoRelayConfig,
    reachability: AutoNatReachability,
    candidates: Vec<(Libp2pPeerId, Multiaddr)>,
    attempted_reservations: HashSet<(Libp2pPeerId, Multiaddr)>,
    pending_reservations: HashMap<Libp2pPeerId, PendingAutoRelayReservation>,
    accepted_reservation_peers: HashSet<Libp2pPeerId>,
    reservation_listeners: HashMap<Libp2pPeerId, ListenerId>,
    retry_after: HashMap<Libp2pPeerId, Instant>,
    reservation_failures: HashMap<Libp2pPeerId, u8>,
}

#[derive(Clone, Debug)]
struct PendingAutoRelayReservation {
    address: Multiaddr,
    expires_at: Instant,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ReleasedAutoRelayListener {
    relay: Libp2pPeerId,
    pending_address: Option<Multiaddr>,
    was_accepted: bool,
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct AutoRelaySnapshot {
    max_candidates: usize,
    max_reservations: usize,
    retry_interval_seconds: u64,
    private_reachability: bool,
    candidates: usize,
    reservations: usize,
    pending_retries: usize,
}

impl Default for AutoRelayState {
    fn default() -> Self {
        Self::new(AutoRelayConfig::default())
    }
}

impl AutoRelayState {
    fn new(policy: AutoRelayConfig) -> Self {
        Self {
            policy,
            reachability: AutoNatReachability::Unknown,
            candidates: Vec::new(),
            attempted_reservations: HashSet::new(),
            pending_reservations: HashMap::new(),
            accepted_reservation_peers: HashSet::new(),
            reservation_listeners: HashMap::new(),
            retry_after: HashMap::new(),
            reservation_failures: HashMap::new(),
        }
    }

    fn record_reachability(&mut self, reachability: AutoNatReachability) {
        self.reachability = reachability;
    }

    const fn private_reachability(&self) -> bool {
        matches!(self.reachability, AutoNatReachability::Private)
    }

    fn should_discover_candidates(&self) -> bool {
        self.policy.max_candidates > self.candidates.len()
            && self.policy.max_reservations > 0
            && self.accepted_reservation_peers.len() < self.policy.max_reservations
    }

    fn snapshot(&self, now: Instant) -> AutoRelaySnapshot {
        AutoRelaySnapshot {
            max_candidates: self.policy.max_candidates,
            max_reservations: self.policy.max_reservations,
            retry_interval_seconds: self.policy.retry_interval_seconds,
            private_reachability: self.private_reachability(),
            candidates: self.candidates.len(),
            reservations: self.accepted_reservation_peers.len(),
            pending_retries: self
                .retry_after
                .values()
                .filter(|retry_after| now < **retry_after)
                .count(),
        }
    }

    fn record_candidate(&mut self, peer: Libp2pPeerId, address: Multiaddr) -> bool {
        if self.policy.max_candidates == 0 {
            return false;
        }
        if let Some((_, existing_address)) = self
            .candidates
            .iter_mut()
            .find(|(candidate_peer, _)| *candidate_peer == peer)
        {
            if *existing_address == address {
                return false;
            }

            *existing_address = address;
            if !self.accepted_reservation_peers.contains(&peer) {
                if !self.pending_reservations.contains_key(&peer) {
                    self.attempted_reservations
                        .retain(|(attempted_peer, _)| *attempted_peer != peer);
                }
                self.retry_after.remove(&peer);
            }
            return true;
        }
        if self.candidates.len() >= self.policy.max_candidates {
            return false;
        }

        self.candidates.push((peer, address));
        true
    }

    fn remove_candidate(&mut self, peer: Libp2pPeerId) -> bool {
        let original_len = self.candidates.len();
        self.candidates
            .retain(|(candidate_peer, _)| *candidate_peer != peer);
        self.attempted_reservations
            .retain(|(attempted_peer, _)| *attempted_peer != peer);
        self.pending_reservations.remove(&peer);
        self.accepted_reservation_peers.remove(&peer);
        self.reservation_listeners.remove(&peer);
        self.retry_after.remove(&peer);
        self.reservation_failures.remove(&peer);
        self.candidates.len() != original_len
    }

    fn record_reservation_failure(&mut self, peer: Libp2pPeerId) -> bool {
        let failures = self.reservation_failures.entry(peer).or_default();
        *failures = failures.saturating_add(1);
        if *failures < AUTO_RELAY_CANDIDATE_FAILURE_EVICTION_THRESHOLD {
            return false;
        }
        self.remove_candidate(peer)
    }

    fn next_reservation_targets(&mut self, now: Instant) -> Vec<(Libp2pPeerId, Multiaddr)> {
        if self.policy.max_reservations == 0
            || self.reservation_slots() >= self.policy.max_reservations
        {
            return Vec::new();
        }

        let mut targets = Vec::new();
        for (peer, address) in &self.candidates {
            if self.accepted_reservation_peers.contains(peer)
                || self.pending_reservations.contains_key(peer)
            {
                continue;
            }
            if self
                .retry_after
                .get(peer)
                .is_some_and(|retry_after| now < *retry_after)
            {
                continue;
            }
            if !self.attempted_reservations.insert((*peer, address.clone())) {
                continue;
            }
            self.pending_reservations.insert(
                *peer,
                PendingAutoRelayReservation {
                    address: address.clone(),
                    expires_at: now + AUTO_RELAY_RESERVATION_PENDING_TIMEOUT,
                },
            );
            targets.push((*peer, address.clone()));
            if self.reservation_slots() >= self.policy.max_reservations {
                break;
            }
        }

        targets
    }

    fn reservation_slots(&self) -> usize {
        self.accepted_reservation_peers.len() + self.pending_reservations.len()
    }

    fn record_reservation_accepted(&mut self, peer: Libp2pPeerId) {
        self.pending_reservations.remove(&peer);
        self.accepted_reservation_peers.insert(peer);
        self.retry_after.remove(&peer);
        self.reservation_failures.remove(&peer);
    }

    fn record_reservation_listener(&mut self, peer: Libp2pPeerId, listener_id: ListenerId) -> bool {
        if !self.pending_reservations.contains_key(&peer)
            || self.reservation_listeners.contains_key(&peer)
        {
            return false;
        }
        self.reservation_listeners.insert(peer, listener_id);
        true
    }

    #[cfg(test)]
    fn has_active_reservation(&self, peer: Libp2pPeerId) -> bool {
        self.accepted_reservation_peers.contains(&peer)
    }

    fn release_reservation_peer(&mut self, peer: Libp2pPeerId) -> bool {
        let listener_removed = self.reservation_listeners.remove(&peer).is_some();
        self.pending_reservations.remove(&peer).is_some()
            | self.accepted_reservation_peers.remove(&peer)
            | listener_removed
    }

    fn release_reservation_for_retry(&mut self, peer: Libp2pPeerId) -> bool {
        let released = self.release_reservation_peer(peer);
        self.attempted_reservations
            .retain(|(attempted_peer, _)| *attempted_peer != peer);
        released
    }

    fn release_reservation_for_retry_after(&mut self, peer: Libp2pPeerId, now: Instant) -> bool {
        let released = self.release_reservation_for_retry(peer);
        self.retry_after
            .insert(peer, now + self.policy.retry_interval());
        released
    }

    fn release_listener_for_retry_after(
        &mut self,
        listener_id: ListenerId,
        now: Instant,
    ) -> Option<ReleasedAutoRelayListener> {
        let relay = self
            .reservation_listeners
            .iter()
            .find_map(|(relay, tracked)| (*tracked == listener_id).then_some(*relay))?;
        let pending_address = self
            .pending_reservations
            .get(&relay)
            .map(|pending| pending.address.clone());
        let was_accepted = self.accepted_reservation_peers.contains(&relay);
        self.release_reservation_for_retry_after(relay, now);
        Some(ReleasedAutoRelayListener {
            relay,
            pending_address,
            was_accepted,
        })
    }

    fn expire_pending_reservations(
        &mut self,
        now: Instant,
    ) -> Vec<(Libp2pPeerId, Multiaddr, Option<ListenerId>)> {
        let expired_peers = self
            .pending_reservations
            .iter()
            .filter_map(|(peer, pending)| (now >= pending.expires_at).then_some(*peer))
            .collect::<Vec<_>>();
        let mut expired = Vec::with_capacity(expired_peers.len());
        for peer in expired_peers {
            if let Some(pending) = self.pending_reservations.remove(&peer) {
                let listener_id = self.reservation_listeners.remove(&peer);
                self.attempted_reservations
                    .remove(&(peer, pending.address.clone()));
                self.retry_after
                    .insert(peer, now + self.policy.retry_interval());
                expired.push((peer, pending.address, listener_id));
            }
        }
        expired
    }
}

#[derive(Debug, Default)]
struct InfrastructurePeers {
    peers: HashMap<Libp2pPeerId, Multiaddr>,
}

#[derive(Clone, Debug, Default, Eq, PartialEq)]
struct RelayInfrastructureSnapshot {
    peers: Vec<RelayInfrastructurePeerSnapshot>,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct RelayInfrastructurePeerSnapshot {
    peer: Libp2pPeerId,
    address: Multiaddr,
    connected: bool,
}

impl InfrastructurePeers {
    fn can_admit(&self, peer: Libp2pPeerId) -> bool {
        self.peers.contains_key(&peer) || self.peers.len() < AUTO_RELAY_MAX_INFRASTRUCTURE_PEERS
    }

    fn insert(&mut self, peer: Libp2pPeerId, address: Multiaddr) -> bool {
        if let Some(existing_address) = self.peers.get_mut(&peer) {
            if *existing_address == address {
                return false;
            }
            *existing_address = address;
            return true;
        }
        if self.peers.len() >= AUTO_RELAY_MAX_INFRASTRUCTURE_PEERS {
            return false;
        }

        self.peers.insert(peer, address);
        true
    }

    fn contains(&self, peer: Libp2pPeerId) -> bool {
        self.peers.contains_key(&peer)
    }

    fn remove(&mut self, peer: Libp2pPeerId) -> bool {
        self.peers.remove(&peer).is_some()
    }

    fn snapshot(&self, swarm: &Swarm<Behaviour>) -> RelayInfrastructureSnapshot {
        let mut peers = self
            .peers
            .iter()
            .map(|(peer, address)| RelayInfrastructurePeerSnapshot {
                peer: *peer,
                address: address.clone(),
                connected: swarm.is_connected(peer),
            })
            .collect::<Vec<_>>();
        peers.sort_by_key(|peer| peer.peer.to_string());
        RelayInfrastructureSnapshot { peers }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RoutingInfrastructureAdmission {
    Admitted,
    Existing,
    AtCapacity,
}

#[derive(Debug, Default)]
struct RoutingInfrastructurePeers {
    peers: HashSet<Libp2pPeerId>,
}

impl RoutingInfrastructurePeers {
    fn admit(&mut self, peer: Libp2pPeerId) -> RoutingInfrastructureAdmission {
        if self.peers.contains(&peer) {
            return RoutingInfrastructureAdmission::Existing;
        }
        if self.peers.len() >= KADEMLIA_ROUTING_PEER_CAPACITY {
            return RoutingInfrastructureAdmission::AtCapacity;
        }
        self.peers.insert(peer);
        RoutingInfrastructureAdmission::Admitted
    }

    fn contains(&self, peer: Libp2pPeerId) -> bool {
        self.peers.contains(&peer)
    }

    fn remove(&mut self, peer: Libp2pPeerId) -> bool {
        self.peers.remove(&peer)
    }

    fn len(&self) -> usize {
        self.peers.len()
    }
}

fn admit_discovered_relay_infrastructure_peer<'a>(
    swarm: &mut Swarm<Behaviour>,
    forwarder: &Forwarder,
    infrastructure_peers: &mut InfrastructurePeers,
    auto_relay: &mut AutoRelayState,
    metrics: &RuntimeMetrics,
    peer: Libp2pPeerId,
    source: DiscoveredPeerAddressSource,
    addresses: impl IntoIterator<Item = &'a Multiaddr>,
) {
    if peer == *swarm.local_peer_id() || forwarder.is_configured_transport_peer(peer) {
        return;
    }

    let local_networks = local_interface_networks("");
    let Some(address) = best_auto_relay_candidate_address(peer, addresses, &local_networks, source)
    else {
        return;
    };

    if !infrastructure_peers.can_admit(peer) || !auto_relay.record_candidate(peer, address.clone())
    {
        return;
    }

    if !infrastructure_peers.insert(peer, address.clone()) {
        return;
    }

    metrics.record_auto_relay_candidate();
    log_runtime_event(
        LogLevel::Info,
        "auto_relay_candidate",
        &[
            ("peer", &peer.to_string()),
            ("address", &address.to_string()),
            ("source", source.as_str()),
        ],
    );
    metrics.record_auto_relay_infrastructure_candidate();
    log_runtime_event(
        LogLevel::Info,
        "auto_relay_infrastructure_candidate",
        &[
            ("peer", &peer.to_string()),
            ("address", &address.to_string()),
            ("source", source.as_str()),
        ],
    );

    if swarm.is_connected(&peer) {
        return;
    }

    metrics.record_auto_relay_infrastructure_dial_attempt();
    if let Err(error) = swarm.dial(address.clone()) {
        metrics.record_auto_relay_infrastructure_dial_failure();
        infrastructure_peers.remove(peer);
        auto_relay.remove_candidate(peer);
        log_runtime_event(
            LogLevel::Warn,
            "auto_relay_infrastructure_dial_failed",
            &[
                ("peer", &peer.to_string()),
                ("address", &address.to_string()),
                ("error", &error.to_string()),
            ],
        );
    }
}

fn admit_connected_auto_relay_infrastructure_probe(
    swarm: &mut Swarm<Behaviour>,
    forwarder: &Forwarder,
    infrastructure_peers: &mut InfrastructurePeers,
    auto_relay: &mut AutoRelayState,
    metrics: &RuntimeMetrics,
    peer: Libp2pPeerId,
    endpoint: &ConnectedPoint,
    relay_server_enabled: bool,
) {
    if relay_server_enabled
        || peer == *swarm.local_peer_id()
        || forwarder.is_configured_transport_peer(peer)
    {
        return;
    }
    let Some(address) = connected_auto_relay_candidate_address(peer, endpoint) else {
        return;
    };
    if !infrastructure_peers.can_admit(peer) || !auto_relay.record_candidate(peer, address.clone())
    {
        return;
    }
    if !infrastructure_peers.insert(peer, address.clone()) {
        return;
    }

    metrics.record_auto_relay_candidate();
    metrics.record_auto_relay_infrastructure_candidate();
    log_runtime_event(
        LogLevel::Info,
        "auto_relay_candidate",
        &[
            ("peer", &peer.to_string()),
            ("address", &address.to_string()),
        ],
    );
    log_runtime_event(
        LogLevel::Info,
        "auto_relay_infrastructure_candidate",
        &[
            ("peer", &peer.to_string()),
            ("address", &address.to_string()),
        ],
    );
    attempt_auto_relay_reservations(swarm, auto_relay, metrics);
}

fn remove_overlay_peer_from_infrastructure(
    infrastructure_peers: &mut InfrastructurePeers,
    auto_relay: &mut AutoRelayState,
    peer: Libp2pPeerId,
    reason: &str,
) {
    let removed_infrastructure = infrastructure_peers.remove(peer);
    let removed_candidate = auto_relay.remove_candidate(peer);
    if removed_infrastructure || removed_candidate {
        log_runtime_event(
            LogLevel::Info,
            "overlay_peer_infrastructure_state_removed",
            &[("peer", &peer.to_string()), ("reason", reason)],
        );
    }
}

fn connected_auto_relay_candidate_address(
    peer: Libp2pPeerId,
    endpoint: &ConnectedPoint,
) -> Option<Multiaddr> {
    let address = match endpoint {
        ConnectedPoint::Dialer { address, .. } => address,
        ConnectedPoint::Listener { send_back_addr, .. } => send_back_addr,
    };
    auto_relay_candidate_address(peer, address)
}

fn reject_unconfirmed_infrastructure_peer(
    swarm: &mut Swarm<Behaviour>,
    infrastructure_peers: &mut InfrastructurePeers,
    auto_relay: &mut AutoRelayState,
    peer: Libp2pPeerId,
    reason: &str,
) {
    if !infrastructure_peers.remove(peer) {
        return;
    }
    auto_relay.remove_candidate(peer);

    log_runtime_event(
        LogLevel::Warn,
        "auto_relay_infrastructure_rejected",
        &[("peer", &peer.to_string()), ("reason", reason)],
    );
    if swarm.disconnect_peer_id(peer).is_err() {
        log_runtime_event(
            LogLevel::Warn,
            "auto_relay_infrastructure_already_disconnected",
            &[("peer", &peer.to_string())],
        );
    }
}

fn remove_unconfirmed_infrastructure_peer(
    infrastructure_peers: &mut InfrastructurePeers,
    auto_relay: &mut AutoRelayState,
    peer: Libp2pPeerId,
    reason: &str,
) -> bool {
    if !infrastructure_peers.remove(peer) {
        return false;
    }
    auto_relay.remove_candidate(peer);

    log_runtime_event(
        LogLevel::Warn,
        "auto_relay_infrastructure_rejected",
        &[("peer", &peer.to_string()), ("reason", reason)],
    );
    true
}

fn record_auto_relay_candidates(
    auto_relay: &mut AutoRelayState,
    metrics: &RuntimeMetrics,
    peer: Libp2pPeerId,
    addresses: impl IntoIterator<Item = Multiaddr>,
) {
    for address in addresses {
        if auto_relay.record_candidate(peer, address.clone()) {
            metrics.record_auto_relay_candidate();
            log_runtime_event(
                LogLevel::Info,
                "auto_relay_candidate",
                &[
                    ("peer", &peer.to_string()),
                    ("address", &address.to_string()),
                ],
            );
        }
    }
}

fn attempt_auto_relay_reservations(
    swarm: &mut Swarm<Behaviour>,
    auto_relay: &mut AutoRelayState,
    metrics: &RuntimeMetrics,
) {
    let now = Instant::now();
    for (relay_peer, relay_address) in auto_relay.next_reservation_targets(now) {
        let reservation_address = relay_address.clone().with(Protocol::P2pCircuit);
        metrics.record_auto_relay_reservation_attempt();
        log_runtime_event(
            LogLevel::Info,
            "auto_relay_reservation_attempt",
            &[
                ("relay", &relay_peer.to_string()),
                ("address", &reservation_address.to_string()),
            ],
        );
        match swarm.listen_on(reservation_address.clone()) {
            Ok(listener_id) => {
                if !auto_relay.record_reservation_listener(relay_peer, listener_id) {
                    swarm.remove_listener(listener_id);
                    auto_relay.release_reservation_for_retry_after(relay_peer, now);
                    metrics.record_auto_relay_reservation_failure();
                    log_runtime_event(
                        LogLevel::Warn,
                        "auto_relay_reservation_state_conflict",
                        &[
                            ("relay", &relay_peer.to_string()),
                            ("address", &reservation_address.to_string()),
                            ("listener", &listener_id.to_string()),
                        ],
                    );
                }
            }
            Err(error) => {
                auto_relay.release_reservation_for_retry_after(relay_peer, now);
                metrics.record_auto_relay_reservation_failure();
                log_runtime_event(
                    LogLevel::Warn,
                    "auto_relay_reservation_failed",
                    &[
                        ("relay", &relay_peer.to_string()),
                        ("address", &reservation_address.to_string()),
                        ("error", &error.to_string()),
                    ],
                );
            }
        }
    }
}

fn record_auto_relay_listener_termination(
    auto_relay: &mut AutoRelayState,
    relay_readiness: &mut RelayReadiness,
    metrics: &RuntimeMetrics,
    listener_id: ListenerId,
    now: Instant,
    event: &str,
) -> Option<ReleasedAutoRelayListener> {
    let released = auto_relay.release_listener_for_retry_after(listener_id, now)?;
    let status = if released.was_accepted {
        relay_readiness.record_relay_reservation_lost(released.relay);
        metrics.record_relay_reservation_lost();
        "accepted"
    } else {
        metrics.record_auto_relay_reservation_failure();
        "pending"
    };
    let evicted = released
        .pending_address
        .is_some()
        .then(|| auto_relay.record_reservation_failure(released.relay))
        .unwrap_or(false);
    let address = released
        .pending_address
        .as_ref()
        .map_or_else(|| "none".to_owned(), ToString::to_string);
    log_runtime_event(
        LogLevel::Warn,
        event,
        &[
            ("relay", &released.relay.to_string()),
            ("address", &address),
            ("listener", &listener_id.to_string()),
            ("status", status),
            ("evicted", &evicted.to_string()),
        ],
    );
    Some(released)
}

fn auto_relay_candidate_addresses(
    peer: Libp2pPeerId,
    info: &identify::Info,
    source: DiscoveredPeerAddressSource,
) -> Vec<Multiaddr> {
    if !identify_protocols_include_relay_hop(&info.protocols) {
        return Vec::new();
    }

    ranked_auto_relay_candidate_addresses(
        peer,
        &info.listen_addrs,
        &local_interface_networks(""),
        source,
    )
    .into_iter()
    .take(1)
    .collect()
}

fn identify_protocols_include_relay_hop(protocols: &[libp2p::StreamProtocol]) -> bool {
    identify_protocols_include(protocols, relay::HOP_PROTOCOL_NAME.as_ref())
}

fn identify_protocols_include(protocols: &[libp2p::StreamProtocol], expected: &str) -> bool {
    protocols
        .iter()
        .any(|protocol| protocol.as_ref() == expected)
}

fn auto_relay_candidate_address(peer: Libp2pPeerId, address: &Multiaddr) -> Option<Multiaddr> {
    if relayed_address_relay_peer(address).is_some() {
        return None;
    }
    if !supports_auto_relay_candidate_transport(address) {
        return None;
    }
    if discovered_address_target(address).is_some_and(|target| target != peer) {
        return None;
    }

    Some(peer_dial_address(peer, address.clone()))
}

fn best_auto_relay_candidate_address<'a>(
    peer: Libp2pPeerId,
    addresses: impl IntoIterator<Item = &'a Multiaddr>,
    local_networks: &[LocalInterfaceNetwork],
    source: DiscoveredPeerAddressSource,
) -> Option<Multiaddr> {
    ranked_auto_relay_candidate_addresses(peer, addresses, local_networks, source)
        .into_iter()
        .next()
}

fn ranked_auto_relay_candidate_addresses<'a>(
    peer: Libp2pPeerId,
    addresses: impl IntoIterator<Item = &'a Multiaddr>,
    local_networks: &[LocalInterfaceNetwork],
    source: DiscoveredPeerAddressSource,
) -> Vec<Multiaddr> {
    let mut candidates = addresses
        .into_iter()
        .filter_map(|address| auto_relay_candidate_address(peer, address))
        .filter(|address| {
            !source.requires_public_transport() || discovered_address_uses_public_transport(address)
        })
        .fold(Vec::new(), |mut addresses, address| {
            if !addresses.contains(&address) {
                addresses.push(address);
            }
            addresses
        });
    candidates.sort_by_key(|address| auto_relay_candidate_address_rank(address, local_networks));
    candidates
}

fn auto_relay_candidate_address_rank(
    address: &Multiaddr,
    local_networks: &[LocalInterfaceNetwork],
) -> u8 {
    let Some(ip) = first_ip_in_multiaddr(address) else {
        return 3;
    };
    if local_networks.iter().any(|network| network.contains(ip)) {
        return 0;
    }
    if !private_ip_address(ip) && direct_libp2p_address_ip_is_advertisable(ip) {
        return 1;
    }
    2
}

fn supports_auto_relay_candidate_transport(address: &Multiaddr) -> bool {
    let mut supported = false;
    for protocol in address {
        match protocol {
            Protocol::Tcp(_) | Protocol::Quic | Protocol::QuicV1 => supported = true,
            Protocol::Http
            | Protocol::Https
            | Protocol::P2pWebRtcDirect
            | Protocol::P2pWebRtcStar
            | Protocol::P2pWebSocketStar
            | Protocol::Tls
            | Protocol::WebRTC
            | Protocol::WebRTCDirect
            | Protocol::WebTransport
            | Protocol::Ws(_)
            | Protocol::Wss(_) => return false,
            _ => {}
        }
    }

    supported
}

fn supports_relayed_peer_dial_transport(address: &Multiaddr) -> bool {
    let mut relay_transport = Multiaddr::empty();
    for protocol in address {
        if matches!(protocol, Protocol::P2pCircuit) {
            return supports_auto_relay_candidate_transport(&relay_transport);
        }
        relay_transport.push(protocol);
    }

    false
}

fn relayed_address_uses_public_relay_transport(address: &Multiaddr) -> bool {
    let mut relay_transport = Multiaddr::empty();
    for protocol in address {
        if matches!(protocol, Protocol::P2pCircuit) {
            return relay_transport_is_publicly_dialable(&relay_transport);
        }
        relay_transport.push(protocol);
    }

    false
}

fn relay_transport_is_publicly_dialable(address: &Multiaddr) -> bool {
    transport_host_is_publicly_dialable(address, true)
}

fn public_discovery_transport_is_publicly_dialable(address: &Multiaddr) -> bool {
    transport_host_is_publicly_dialable(address, false)
}

fn transport_host_is_publicly_dialable(address: &Multiaddr, allow_dns: bool) -> bool {
    for protocol in address {
        match protocol {
            Protocol::Dns(_) | Protocol::Dns4(_) | Protocol::Dns6(_) | Protocol::Dnsaddr(_) => {
                return allow_dns;
            }
            Protocol::Ip4(address) => {
                return ipv4_relay_address_is_publicly_dialable(address);
            }
            Protocol::Ip6(address) => {
                return ipv6_relay_address_is_publicly_dialable(address);
            }
            _ => {}
        }
    }
    false
}

fn ipv4_relay_address_is_publicly_dialable(address: Ipv4Addr) -> bool {
    let [first, second, third, _] = address.octets();
    !(address.is_unspecified()
        || address.is_loopback()
        || address.is_link_local()
        || address.is_private()
        || address.is_broadcast()
        || address.is_documentation()
        || address.is_multicast()
        || first == 0
        || (first == 100 && (64..=127).contains(&second))
        || (first == 192 && second == 0 && third == 0)
        || (first == 192 && second == 88 && third == 99)
        || (first == 198 && (18..=19).contains(&second))
        || first >= 240)
}

fn ipv6_relay_address_is_publicly_dialable(address: Ipv6Addr) -> bool {
    if let Some(address) = address.to_ipv4_mapped() {
        return ipv4_relay_address_is_publicly_dialable(address);
    }
    let segments = address.segments();
    let first = segments[0];
    !(address.is_unspecified()
        || address.is_loopback()
        || address.is_multicast()
        || (first & 0xfe00) == 0xfc00
        || (first & 0xffc0) == 0xfec0
        || (first & 0xffc0) == 0xfe80
        || (first == 0x2001 && segments[1] == 0x0db8))
}

impl RelayReadiness {
    fn record_reservation_accepted(&mut self, relay: Libp2pPeerId) {
        self.accepted_reservations.insert(relay);
    }

    fn record_relay_listen_address(&mut self, relay: Libp2pPeerId, address: Multiaddr) {
        let addresses = self.relayed_listen_addresses.entry(relay).or_default();
        if !addresses.contains(&address) {
            addresses.push(address);
        }
    }

    fn record_relay_listen_address_lost(
        &mut self,
        relay: Libp2pPeerId,
        address: &Multiaddr,
    ) -> bool {
        let Some(addresses) = self.relayed_listen_addresses.get_mut(&relay) else {
            return false;
        };
        let original_len = addresses.len();
        addresses.retain(|candidate| candidate != address);
        let removed = addresses.len() != original_len;
        if !removed || !addresses.is_empty() {
            return false;
        }

        self.relayed_listen_addresses.remove(&relay);
        true
    }

    fn record_relay_reservation_lost(&mut self, relay: Libp2pPeerId) -> bool {
        let removed_reservation = self.accepted_reservations.remove(&relay);
        let removed_listen_address = self.relayed_listen_addresses.remove(&relay).is_some();
        if removed_reservation || removed_listen_address {
            true
        } else {
            false
        }
    }

    fn relay_ready(&self, relay: Libp2pPeerId) -> bool {
        self.accepted_reservations.contains(&relay)
            && self.relayed_listen_addresses.contains_key(&relay)
    }

    fn ready_relays(&self) -> Vec<Libp2pPeerId> {
        self.accepted_reservations
            .iter()
            .filter(|relay| self.relayed_listen_addresses.contains_key(relay))
            .copied()
            .collect()
    }

    fn ready_relay_addresses(&self, relay: Libp2pPeerId) -> Vec<(Libp2pPeerId, Multiaddr)> {
        self.relayed_listen_addresses
            .get(&relay)
            .into_iter()
            .flatten()
            .cloned()
            .map(|address| (relay, address))
            .collect()
    }
}

fn dial_relay_ready_configured_peers(
    swarm: &mut Swarm<Behaviour>,
    forwarder: &Forwarder,
    relay_readiness: &mut RelayReadiness,
    relay_addresses: &[(Libp2pPeerId, Multiaddr)],
    configured_peer_addresses: &[(Libp2pPeerId, Multiaddr)],
    discovered_peer_addresses: &mut DiscoveredPeerAddresses,
    paths: &PathSet,
    metrics: &RuntimeMetrics,
    relay: Libp2pPeerId,
) {
    if !relay_readiness.relay_ready(relay) {
        return;
    }
    let mut available_relay_addresses = relay_addresses.to_vec();
    for address in relay_readiness.ready_relay_addresses(relay) {
        if !available_relay_addresses.contains(&address) {
            available_relay_addresses.push(address);
        }
    }
    sort_relay_addresses_by_local_reachability(
        &mut available_relay_addresses,
        &local_interface_networks(""),
    );

    for (peer, address) in relay_ready_configured_peer_targets(
        *swarm.local_peer_id(),
        relay,
        forwarder.configured_transport_peers(),
        &available_relay_addresses,
        configured_peer_addresses,
        discovered_peer_addresses,
        |peer| redial_connection_state(paths, *peer, swarm.is_connected(peer)),
    ) {
        let now = Instant::now();
        if !discovered_peer_addresses.should_attempt_recovery_dial_at(peer, &address, now) {
            continue;
        }
        metrics.record_redial_attempt();
        let dial_address = peer_dial_address(peer, address.clone());
        log_runtime_event(
            LogLevel::Info,
            "relay_ready_peer_dial",
            &[
                ("relay", &relay.to_string()),
                ("peer", &peer.to_string()),
                ("address", &dial_address.to_string()),
            ],
        );
        if let Err(error) = swarm.dial(dial_address.clone()) {
            discovered_peer_addresses.record_recovery_dial_failure_at(peer, &address, now);
            metrics.record_redial_failure();
            log_runtime_event(
                LogLevel::Warn,
                "relay_ready_peer_dial_failed",
                &[
                    ("relay", &relay.to_string()),
                    ("peer", &peer.to_string()),
                    ("error", &error.to_string()),
                ],
            );
        }
    }
}

fn relay_ready_configured_peer_targets(
    local_peer: Libp2pPeerId,
    relay: Libp2pPeerId,
    configured_peers: impl IntoIterator<Item = Libp2pPeerId>,
    relay_addresses: &[(Libp2pPeerId, Multiaddr)],
    configured_peer_addresses: &[(Libp2pPeerId, Multiaddr)],
    discovered_peer_addresses: &DiscoveredPeerAddresses,
    mut connection_state: impl FnMut(&Libp2pPeerId) -> RedialConnectionState,
) -> Vec<(Libp2pPeerId, Multiaddr)> {
    let mut seen = HashSet::new();
    let mut addresses = Vec::new();
    let configured_peers = configured_peers.into_iter().collect::<Vec<_>>();
    let configured_peer_set = configured_peers.iter().copied().collect::<HashSet<_>>();
    let discovered = discovered_peer_addresses
        .addresses
        .iter()
        .map(|entry| (&entry.peer, &entry.address));
    for (peer, address) in configured_peer_addresses
        .iter()
        .map(|(peer, address)| (peer, address))
        .chain(discovered)
    {
        if *peer == local_peer || !connection_state(peer).needs_relay_path() {
            continue;
        }
        if !configured_peer_set.contains(peer) {
            continue;
        }
        if relayed_address_relay_peer(address) != Some(relay) {
            continue;
        }
        if !seen.insert((*peer, peer_dial_address(*peer, address.clone()))) {
            continue;
        }
        addresses.push((*peer, address.clone()));
    }

    let relay_reservation_addresses = relay_addresses
        .iter()
        .filter(|(peer, _)| *peer == relay)
        .map(|(_, address)| address.clone().with(Protocol::P2pCircuit))
        .collect::<Vec<_>>();
    for peer in configured_peers {
        if peer == local_peer || !connection_state(&peer).needs_relay_path() {
            continue;
        }
        for address in &relay_reservation_addresses {
            if !seen.insert((peer, peer_dial_address(peer, address.clone()))) {
                continue;
            }
            addresses.push((peer, address.clone()));
        }
    }
    addresses
}

fn sort_relay_addresses_by_local_reachability(
    addresses: &mut [(Libp2pPeerId, Multiaddr)],
    local_networks: &[LocalInterfaceNetwork],
) {
    addresses
        .sort_by_key(|(_, address)| auto_relay_candidate_address_rank(address, local_networks));
}

#[allow(clippy::too_many_arguments)]
fn redial_selected_addresses(
    swarm: &mut Swarm<Behaviour>,
    selected_peers: &HashSet<Libp2pPeerId>,
    bootstrap_addresses: &[(Libp2pPeerId, Multiaddr)],
    relay_addresses: &[(Libp2pPeerId, Multiaddr)],
    configured_peer_addresses: &[(Libp2pPeerId, Multiaddr)],
    discovered_peer_addresses: &[(Libp2pPeerId, Multiaddr)],
    discovered_address_state: &mut DiscoveredPeerAddresses,
    paths: &PathSet,
    metrics: &RuntimeMetrics,
) {
    let local_peer = *swarm.local_peer_id();
    let targets = pending_redial_targets(
        local_peer,
        bootstrap_addresses,
        relay_addresses,
        configured_peer_addresses,
        discovered_peer_addresses,
        |peer| redial_connection_state(paths, *peer, swarm.is_connected(peer)),
        |_| true,
    );

    for (peer, address) in targets.addresses {
        if !selected_peers.contains(&peer) {
            continue;
        }
        let now = Instant::now();
        if !discovered_address_state.should_attempt_recovery_dial_at(peer, &address, now) {
            continue;
        }
        metrics.record_redial_attempt();
        let dial_address = peer_dial_address(peer, address.clone());
        if let Err(error) = swarm.dial(dial_address.clone()) {
            discovered_address_state.record_recovery_dial_failure_at(peer, &address, now);
            let discovered = discovered_address_state.record_failure_at(peer, &address, now);
            metrics.record_redial_failure();
            log_runtime_event(
                LogLevel::Warn,
                "redial_failed",
                &[
                    ("peer", &peer.to_string()),
                    ("address", &dial_address.to_string()),
                    ("error", &error.to_string()),
                    ("discovered", &discovered.to_string()),
                ],
            );
        }
    }
}

fn redial_packet_plane_recovery_addresses(
    swarm: &mut Swarm<Behaviour>,
    peer: Libp2pPeerId,
    configured_peer_addresses: &[(Libp2pPeerId, Multiaddr)],
    relay_addresses: &[(Libp2pPeerId, Multiaddr)],
    discovered_peer_addresses: &mut DiscoveredPeerAddresses,
    metrics: &RuntimeMetrics,
) {
    let local_peer = *swarm.local_peer_id();
    let now = Instant::now();
    let ready_discovered_addresses = discovered_peer_addresses.redial_candidates_at(now);
    for (peer, address) in packet_plane_recovery_targets(
        local_peer,
        peer,
        configured_peer_addresses,
        relay_addresses,
        &ready_discovered_addresses,
    ) {
        if !discovered_peer_addresses.should_attempt_recovery_dial_at(peer, &address, now) {
            continue;
        }
        metrics.record_packet_plane_path_recovery_dial_attempt();
        let dial_address = peer_dial_address(peer, address.clone());
        if let Err(error) = swarm.dial(dial_address.clone()) {
            discovered_peer_addresses.record_recovery_dial_failure_at(peer, &address, now);
            discovered_peer_addresses.record_failure_at(peer, &address, now);
            metrics.record_packet_plane_path_recovery_dial_failure();
            log_runtime_event(
                LogLevel::Warn,
                "packet_plane_path_recovery_dial_failed",
                &[
                    ("peer", &peer.to_string()),
                    ("address", &dial_address.to_string()),
                    ("error", &error.to_string()),
                ],
            );
        }
    }
}

fn packet_plane_recovery_targets(
    local_peer: Libp2pPeerId,
    peer: Libp2pPeerId,
    configured_peer_addresses: &[(Libp2pPeerId, Multiaddr)],
    relay_addresses: &[(Libp2pPeerId, Multiaddr)],
    discovered_peer_addresses: &[(Libp2pPeerId, Multiaddr)],
) -> Vec<(Libp2pPeerId, Multiaddr)> {
    if peer == local_peer {
        return Vec::new();
    }

    let mut seen = HashSet::new();
    let mut addresses = Vec::new();
    for (candidate_peer, address) in configured_peer_addresses
        .iter()
        .chain(discovered_peer_addresses.iter())
        .filter(|(_, address)| relayed_address_relay_peer(address).is_none())
    {
        if *candidate_peer != peer {
            continue;
        }
        if !seen.insert((*candidate_peer, address.clone())) {
            continue;
        }
        addresses.push((*candidate_peer, address.clone()));
    }
    for (candidate_peer, address) in configured_peer_addresses
        .iter()
        .chain(discovered_peer_addresses.iter())
        .filter(|(_, address)| relayed_address_relay_peer(address).is_some())
    {
        if *candidate_peer != peer {
            continue;
        }
        if !seen.insert((*candidate_peer, address.clone())) {
            continue;
        }
        addresses.push((*candidate_peer, address.clone()));
    }
    for (_, address) in relay_addresses {
        let relayed_address = address.clone().with(Protocol::P2pCircuit);
        if !seen.insert((peer, relayed_address.clone())) {
            continue;
        }
        addresses.push((peer, relayed_address));
    }
    addresses
}

fn pending_redial_targets(
    local_peer: Libp2pPeerId,
    bootstrap_addresses: &[(Libp2pPeerId, Multiaddr)],
    relay_addresses: &[(Libp2pPeerId, Multiaddr)],
    configured_peer_addresses: &[(Libp2pPeerId, Multiaddr)],
    discovered_peer_addresses: &[(Libp2pPeerId, Multiaddr)],
    mut connection_state: impl FnMut(&Libp2pPeerId) -> RedialConnectionState,
    mut relay_ready: impl FnMut(Libp2pPeerId) -> bool,
) -> RedialTargets {
    let mut addresses = Vec::new();
    let mut skipped_connected = 0;
    let mut seen = HashSet::new();
    let configured_relay_reservations = relay_addresses
        .iter()
        .map(|(peer, _)| *peer)
        .collect::<HashSet<_>>();
    for (peer, address) in configured_peer_addresses
        .iter()
        .chain(discovered_peer_addresses.iter())
        .filter(|(_, address)| relayed_address_relay_peer(address).is_none())
    {
        if *peer == local_peer {
            continue;
        }
        match connection_state(peer) {
            RedialConnectionState::Disconnected | RedialConnectionState::ConnectedNoUsablePath => {}
            RedialConnectionState::RelayOnly => {}
            RedialConnectionState::DirectOnly | RedialConnectionState::DirectAndRelay => {
                skipped_connected += 1;
                continue;
            }
        }
        if !seen.insert((*peer, address.clone())) {
            continue;
        }
        addresses.push((*peer, address.clone()));
    }
    for (peer, address) in bootstrap_addresses.iter().chain(relay_addresses.iter()) {
        if *peer == local_peer {
            continue;
        }
        if connection_state(peer).is_connected() {
            skipped_connected += 1;
            continue;
        }
        if !seen.insert((*peer, address.clone())) {
            continue;
        }
        addresses.push((*peer, address.clone()));
    }
    for (peer, address) in configured_peer_addresses
        .iter()
        .chain(discovered_peer_addresses.iter())
        .filter(|(_, address)| relayed_address_relay_peer(address).is_some())
    {
        if *peer == local_peer {
            continue;
        }
        match connection_state(peer) {
            RedialConnectionState::Disconnected | RedialConnectionState::ConnectedNoUsablePath => {}
            RedialConnectionState::RelayOnly
            | RedialConnectionState::DirectOnly
            | RedialConnectionState::DirectAndRelay => {
                skipped_connected += 1;
                continue;
            }
        }
        if let Some(relay) = relayed_address_relay_peer(address)
            && configured_relay_reservations.contains(&relay)
            && !relay_ready(relay)
        {
            continue;
        }
        if !seen.insert((*peer, address.clone())) {
            continue;
        }
        addresses.push((*peer, address.clone()));
    }
    RedialTargets {
        addresses,
        skipped_connected,
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RedialConnectionState {
    Disconnected,
    ConnectedNoUsablePath,
    RelayOnly,
    DirectOnly,
    DirectAndRelay,
}

impl RedialConnectionState {
    const fn is_connected(self) -> bool {
        !matches!(self, Self::Disconnected | Self::ConnectedNoUsablePath)
    }

    const fn needs_relay_path(self) -> bool {
        matches!(self, Self::Disconnected | Self::ConnectedNoUsablePath)
    }
}

fn redial_connection_state(
    paths: &PathSet,
    peer: Libp2pPeerId,
    connected: bool,
) -> RedialConnectionState {
    if !connected {
        return RedialConnectionState::Disconnected;
    }

    let overlay_peer = PeerId::from_libp2p(peer);
    let mut has_direct = false;
    let mut has_relay = false;
    let mut has_candidate = false;
    for candidate in paths.candidates_for(overlay_peer) {
        has_candidate = true;
        if !candidate.healthy || candidate.established_connections == 0 {
            continue;
        }
        if candidate.is_relay() {
            has_relay = true;
        } else if !candidate.kind.requires_quic_datagrams() {
            has_direct = true;
        }
    }

    if has_direct && has_relay {
        RedialConnectionState::DirectAndRelay
    } else if has_direct {
        RedialConnectionState::DirectOnly
    } else if has_relay {
        RedialConnectionState::RelayOnly
    } else if has_candidate {
        RedialConnectionState::ConnectedNoUsablePath
    } else {
        RedialConnectionState::ConnectedNoUsablePath
    }
}

fn has_established_relay_path(paths: &PathSet, peer: Libp2pPeerId) -> bool {
    let overlay_peer = PeerId::from_libp2p(peer);
    paths.candidates_for(overlay_peer).any(|candidate| {
        candidate.healthy && candidate.is_relay() && candidate.established_connections > 0
    })
}

fn should_dial_discovered_address(
    paths: &PathSet,
    peer: Libp2pPeerId,
    connected: bool,
    address: &Multiaddr,
) -> bool {
    match redial_connection_state(paths, peer, connected) {
        RedialConnectionState::DirectOnly | RedialConnectionState::DirectAndRelay => false,
        RedialConnectionState::RelayOnly
            if relayed_address_relay_peer(address).is_some()
                && has_established_relay_path(paths, peer) =>
        {
            false
        }
        RedialConnectionState::Disconnected
        | RedialConnectionState::ConnectedNoUsablePath
        | RedialConnectionState::RelayOnly => true,
    }
}

fn record_discovered_outgoing_connection_failure(
    discovered_peer_addresses: &mut DiscoveredPeerAddresses,
    metrics: &RuntimeMetrics,
    peer: Option<Libp2pPeerId>,
    error: &DialError,
) {
    let Some(peer) = peer else {
        return;
    };
    let now = Instant::now();
    let failed_addresses = dial_error_failed_addresses(error);
    let mut recorded_recovery_failures = HashSet::new();
    for address in failed_addresses {
        if recorded_recovery_failures.insert(recovery_dial_target(peer, &address)) {
            discovered_peer_addresses.record_recovery_dial_failure_at(peer, &address, now);
        }
        if dial_error_reports_relay_no_reservation(error)
            && relayed_address_relay_peer(&address).is_some()
        {
            if discovered_peer_addresses.remove(peer, &address) {
                metrics.record_discovered_address_dial_failure();
                log_runtime_event(
                    LogLevel::Warn,
                    "discovered_relayed_address_removed",
                    &[
                        ("peer", &peer.to_string()),
                        ("address", &address.to_string()),
                        ("reason", "relay_no_destination_reservation"),
                    ],
                );
            }
            continue;
        }
        if !discovered_peer_addresses.record_dial_failure_at(peer, &address, now) {
            continue;
        }
        metrics.record_discovered_address_dial_failure();
        log_runtime_event(
            LogLevel::Warn,
            "discovered_address_async_dial_failed",
            &[
                ("peer", &peer.to_string()),
                ("address", &address.to_string()),
                ("error", &error.to_string()),
            ],
        );
    }
}

fn dial_error_reports_relay_no_reservation(error: &DialError) -> bool {
    let error = error.to_string();
    error.contains("Relay has no reservation for destination")
        || error.contains("NoReservation")
        || error.contains("NO_RESERVATION")
}

fn dial_error_reports_public_no_route(error: &DialError) -> bool {
    match error {
        DialError::Transport(errors) => {
            !errors.is_empty()
                && errors.iter().all(|(_, error)| match error {
                    TransportError::Other(error) => matches!(error.raw_os_error(), Some(101 | 113)),
                    TransportError::MultiaddrNotSupported(_) => false,
                })
        }
        DialError::LocalPeerId { .. }
        | DialError::NoAddresses
        | DialError::DialPeerConditionFalse(_)
        | DialError::Aborted
        | DialError::WrongPeerId { .. }
        | DialError::Denied { .. } => false,
    }
}

fn dial_error_reports_public_bootstrap_failure(error: &DialError) -> bool {
    dial_error_reports_public_no_route(error)
        || matches!(
            error,
            DialError::Transport(errors)
                if !errors.is_empty()
                    && errors
                        .iter()
                        .all(|(_, error)| matches!(error, TransportError::Other(_)))
        )
}

fn dial_error_failed_addresses(error: &DialError) -> Vec<Multiaddr> {
    match error {
        DialError::LocalPeerId { address } | DialError::WrongPeerId { address, .. } => {
            vec![address.clone()]
        }
        DialError::Transport(errors) => errors.iter().map(|(address, _)| address.clone()).collect(),
        DialError::NoAddresses
        | DialError::DialPeerConditionFalse(_)
        | DialError::Aborted
        | DialError::Denied { .. } => Vec::new(),
    }
}

#[derive(Debug, Eq, PartialEq)]
struct RedialTargets {
    addresses: Vec<(Libp2pPeerId, Multiaddr)>,
    skipped_connected: usize,
}

#[derive(Debug, Default, Eq, PartialEq)]
struct DiscoveredPeerAddresses {
    addresses: Vec<DiscoveredPeerAddress>,
    recovery_dial_attempts: HashMap<(Libp2pPeerId, RecoveryDialTarget), RecoveryDialAttempt>,
    last_recovery_dial_prune: Option<Instant>,
    recovery_discovery_queries: HashMap<Libp2pPeerId, RecoveryDiscoveryQuery>,
    recovery_discovery_query_peers: HashMap<kad::QueryId, Libp2pPeerId>,
}

#[derive(Debug, Eq, PartialEq)]
struct DiscoveredPeerAddress {
    peer: Libp2pPeerId,
    address: Multiaddr,
    last_seen: Instant,
    failure_count: u8,
    quarantined_until: Option<Instant>,
}

#[derive(Debug, Eq, PartialEq)]
struct RecoveryDialAttempt {
    last_attempt: Instant,
    retry_after: Instant,
    failure_count: u8,
}

#[derive(Debug, Eq, PartialEq)]
struct RecoveryDiscoveryQuery {
    last_query: Instant,
    pending_queries: usize,
}

#[derive(Clone, Debug, Eq, Hash, PartialEq)]
enum RecoveryDialTarget {
    Direct(Multiaddr),
    Relay(Libp2pPeerId),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DiscoveredPeerAddressSource {
    AuthenticatedPeerRecord,
    AuthenticatedControlHint,
    AuthenticatedPeerIdentify,
    LocalDiscovery,
    PublicDiscovery,
}

impl DiscoveredPeerAddressSource {
    const fn as_str(self) -> &'static str {
        match self {
            Self::AuthenticatedPeerRecord => "authenticated_peer_record",
            Self::AuthenticatedControlHint => "authenticated_control_hint",
            Self::AuthenticatedPeerIdentify => "authenticated_peer_identify",
            Self::LocalDiscovery => "local_discovery",
            Self::PublicDiscovery => "public_discovery",
        }
    }

    const fn requires_public_transport(self) -> bool {
        matches!(self, Self::PublicDiscovery)
    }
}

fn accepted_discovery_addresses<'a>(
    metrics: &RuntimeMetrics,
    peer: Libp2pPeerId,
    addresses: impl IntoIterator<Item = &'a Multiaddr>,
    source: DiscoveredPeerAddressSource,
    surface: &str,
) -> Vec<&'a Multiaddr> {
    addresses
        .into_iter()
        .filter(|address| {
            if !source.requires_public_transport()
                || discovered_address_uses_public_transport(address)
            {
                return true;
            }

            record_public_discovery_address_rejected(metrics, peer, address, surface);
            false
        })
        .collect()
}

fn discovered_address_uses_public_transport(address: &Multiaddr) -> bool {
    public_discovery_transport_is_publicly_dialable(address)
}

fn record_public_discovery_address_rejected(
    metrics: &RuntimeMetrics,
    peer: Libp2pPeerId,
    address: &Multiaddr,
    surface: &str,
) {
    metrics.record_discovered_address_rejected();
    let total = metrics.record_public_discovery_unverified_address_rejected();
    if total.is_power_of_two() {
        log_runtime_event(
            LogLevel::Info,
            "public_discovery_address_rejected",
            &[
                ("peer", &peer.to_string()),
                ("address", &address.to_string()),
                ("surface", surface),
                ("reason", "unverified_transport_scope"),
                ("total", &total.to_string()),
            ],
        );
    }
}

impl DiscoveredPeerAddresses {
    fn insert(&mut self, peer: Libp2pPeerId, address: Multiaddr) {
        self.insert_at(peer, address, Instant::now());
    }

    fn insert_at(&mut self, peer: Libp2pPeerId, address: Multiaddr, now: Instant) {
        if let Some(entry) = self
            .addresses
            .iter_mut()
            .find(|entry| entry.peer == peer && entry.address == address)
        {
            entry.last_seen = now;
            return;
        }

        self.addresses.push(DiscoveredPeerAddress {
            peer,
            address,
            last_seen: now,
            failure_count: 0,
            quarantined_until: None,
        });
    }

    fn remove(&mut self, peer: Libp2pPeerId, address: &Multiaddr) -> bool {
        let original_len = self.addresses.len();
        self.addresses
            .retain(|entry| entry.peer != peer || &entry.address != address);
        self.addresses.len() != original_len
    }

    fn drop_expired(&mut self, now: Instant, max_age: Duration) -> u64 {
        let mut expired = 0_u64;
        self.addresses.retain(|entry| {
            let keep = now.saturating_duration_since(entry.last_seen) <= max_age;
            if !keep {
                expired = expired.saturating_add(1);
            }
            keep
        });
        expired
    }

    fn record_failure_at(&mut self, peer: Libp2pPeerId, address: &Multiaddr, now: Instant) -> bool {
        let Some(entry) = self
            .addresses
            .iter_mut()
            .find(|entry| entry.peer == peer && &entry.address == address)
        else {
            return false;
        };
        entry.failure_count = entry.failure_count.saturating_add(1);
        entry.quarantined_until =
            Some(now + discovered_address_failure_backoff(entry.failure_count));
        true
    }

    fn is_ready_at(&self, peer: Libp2pPeerId, address: &Multiaddr, now: Instant) -> bool {
        self.addresses
            .iter()
            .find(|entry| entry.peer == peer && &entry.address == address)
            .is_none_or(|entry| entry.quarantined_until.is_none_or(|until| until <= now))
    }

    fn record_dial_failure_at(
        &mut self,
        peer: Libp2pPeerId,
        dialed_address: &Multiaddr,
        now: Instant,
    ) -> bool {
        let Some(entry) = self.addresses.iter_mut().find(|entry| {
            entry.peer == peer
                && (&entry.address == dialed_address
                    || peer_dial_address(peer, entry.address.clone()) == *dialed_address)
        }) else {
            return false;
        };

        entry.failure_count = entry.failure_count.saturating_add(1);
        entry.quarantined_until =
            Some(now + discovered_address_failure_backoff(entry.failure_count));
        true
    }

    #[cfg(test)]
    fn as_vec(&self) -> Vec<(Libp2pPeerId, Multiaddr)> {
        self.addresses
            .iter()
            .map(|entry| (entry.peer, entry.address.clone()))
            .collect()
    }

    fn redial_candidates_at(&self, now: Instant) -> Vec<(Libp2pPeerId, Multiaddr)> {
        let mut entries = self
            .addresses
            .iter()
            .filter(|entry| entry.quarantined_until.is_none_or(|until| until <= now))
            .collect::<Vec<_>>();
        entries.sort_by_key(|entry| (entry.failure_count, std::cmp::Reverse(entry.last_seen)));
        entries
            .into_iter()
            .map(|entry| (entry.peer, entry.address.clone()))
            .collect()
    }

    fn should_attempt_recovery_dial_at(
        &mut self,
        peer: Libp2pPeerId,
        address: &Multiaddr,
        now: Instant,
    ) -> bool {
        let key = (peer, recovery_dial_target(peer, address));
        if self
            .recovery_dial_attempts
            .get(&key)
            .is_some_and(|attempt| attempt.retry_after > now)
        {
            return false;
        }

        if !self.make_recovery_dial_room(&key, now) {
            return false;
        }
        let failure_count = self
            .recovery_dial_attempts
            .get(&key)
            .map_or(0, |attempt| attempt.failure_count);
        self.recovery_dial_attempts.insert(
            key,
            RecoveryDialAttempt {
                last_attempt: now,
                retry_after: now + REDIAL_INTERVAL,
                failure_count,
            },
        );
        true
    }

    fn record_recovery_dial_failure_at(
        &mut self,
        peer: Libp2pPeerId,
        address: &Multiaddr,
        now: Instant,
    ) {
        let key = (peer, recovery_dial_target(peer, address));
        if !self.make_recovery_dial_room(&key, now) {
            return;
        }
        let attempt = self
            .recovery_dial_attempts
            .entry(key)
            .or_insert(RecoveryDialAttempt {
                last_attempt: now,
                retry_after: now,
                failure_count: 0,
            });
        attempt.last_attempt = now;
        attempt.failure_count = attempt.failure_count.saturating_add(1);
        attempt.retry_after = now + discovered_address_failure_backoff(attempt.failure_count);
    }

    fn record_recovery_connection_at(&mut self, peer: Libp2pPeerId, now: Instant) {
        for ((attempted_peer, _), attempt) in &mut self.recovery_dial_attempts {
            if *attempted_peer != peer {
                continue;
            }
            attempt.failure_count = 0;
            attempt.retry_after = now + REDIAL_INTERVAL;
        }
    }

    fn should_query_recovery_discovery_at(&mut self, peer: Libp2pPeerId, now: Instant) -> bool {
        let expired_peers = self
            .recovery_discovery_queries
            .iter()
            .filter_map(|(candidate, query)| {
                let age = now.saturating_duration_since(query.last_query);
                (age >= RECOVERY_DISCOVERY_QUERY_TIMEOUT
                    || (query.pending_queries == 0 && age >= REDIAL_INTERVAL))
                    .then_some(*candidate)
            })
            .collect::<HashSet<_>>();
        if !expired_peers.is_empty() {
            self.recovery_discovery_queries
                .retain(|candidate, _| !expired_peers.contains(candidate));
            self.recovery_discovery_query_peers
                .retain(|_, candidate| !expired_peers.contains(candidate));
        }
        if self.recovery_discovery_queries.contains_key(&peer) {
            return false;
        }
        if self.recovery_discovery_queries.len() >= MAX_RECOVERY_DISCOVERY_QUERIES {
            return false;
        }
        self.recovery_discovery_queries.insert(
            peer,
            RecoveryDiscoveryQuery {
                last_query: now,
                pending_queries: 0,
            },
        );
        true
    }

    fn record_recovery_discovery_queries(
        &mut self,
        peer: Libp2pPeerId,
        queries: impl IntoIterator<Item = kad::QueryId>,
        now: Instant,
    ) {
        let Some(state) = self.recovery_discovery_queries.get_mut(&peer) else {
            return;
        };
        state.last_query = now;
        for query in queries {
            if self
                .recovery_discovery_query_peers
                .insert(query, peer)
                .is_none()
            {
                state.pending_queries += 1;
            }
        }
    }

    fn finish_recovery_discovery_query(&mut self, query: kad::QueryId) {
        let Some(peer) = self.recovery_discovery_query_peers.remove(&query) else {
            return;
        };
        if let Some(state) = self.recovery_discovery_queries.get_mut(&peer) {
            state.pending_queries = state.pending_queries.saturating_sub(1);
        }
    }

    fn make_recovery_dial_room(
        &mut self,
        key: &(Libp2pPeerId, RecoveryDialTarget),
        now: Instant,
    ) -> bool {
        if self.recovery_dial_attempts.contains_key(key)
            || self.recovery_dial_attempts.len() < MAX_RECOVERY_DIAL_ATTEMPTS
        {
            return true;
        }
        if self
            .last_recovery_dial_prune
            .is_none_or(|last_prune| now.saturating_duration_since(last_prune) >= REDIAL_INTERVAL)
        {
            self.recovery_dial_attempts.retain(|_, attempt| {
                now.saturating_duration_since(attempt.last_attempt) < RECOVERY_DIAL_STATE_TTL
            });
            self.last_recovery_dial_prune = Some(now);
        }
        self.recovery_dial_attempts.len() < MAX_RECOVERY_DIAL_ATTEMPTS
    }
}

fn recovery_dial_target(peer: Libp2pPeerId, address: &Multiaddr) -> RecoveryDialTarget {
    relayed_address_relay_peer(address).map_or_else(
        || RecoveryDialTarget::Direct(peer_dial_address(peer, address.clone())),
        RecoveryDialTarget::Relay,
    )
}

fn discovered_address_failure_backoff(failure_count: u8) -> Duration {
    let exponent = u32::from(failure_count.saturating_sub(1)).min(8);
    DISCOVERED_ADDRESS_FAILURE_BACKOFF_BASE
        .saturating_mul(1_u32 << exponent)
        .min(DISCOVERED_ADDRESS_FAILURE_BACKOFF_MAX)
}

#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct OverlayMembership {
    peers: HashSet<Libp2pPeerId>,
    configured_infrastructure_peers: HashSet<Libp2pPeerId>,
}

impl OverlayMembership {
    pub fn from_config(config: &Config) -> Result<Self, ConfigError> {
        Self::from_config_with_member_records(
            config,
            &config.network.member_records,
            current_unix_seconds_lossy(),
        )
    }

    fn from_config_with_member_records(
        config: &Config,
        member_records: &[SignedMembershipRecord],
        now_unix_seconds: u64,
    ) -> Result<Self, ConfigError> {
        let mut peers = HashSet::new();
        let mut configured_infrastructure_peers = HashSet::new();
        peers.insert(
            config
                .local_peer()?
                .parse()
                .map_err(ConfigError::Libp2pPeerId)?,
        );

        for peer in &config.peers {
            peers.insert(peer.id.parse().map_err(ConfigError::Libp2pPeerId)?);
        }

        for member in
            effective_membership_at(member_records, &config.network.name, now_unix_seconds)?
                .overlay_members()
        {
            peers.insert(member.transport_peer);
        }

        for peer in &config.network.bootstrap_peers {
            configured_infrastructure_peers
                .insert(peer.id.parse().map_err(ConfigError::Libp2pPeerId)?);
        }

        for (_, address) in config.peer_multiaddrs()? {
            if let Some(peer) = relay_peer_from_relayed_address(&address) {
                configured_infrastructure_peers.insert(peer);
            }
        }

        for address in config.relay_reservation_multiaddrs()? {
            if let Some(peer) = relay_peer_from_relayed_address(&address) {
                configured_infrastructure_peers.insert(peer);
            }
        }

        Ok(Self {
            peers,
            configured_infrastructure_peers,
        })
    }

    #[must_use]
    pub fn allows(&self, peer: Libp2pPeerId) -> bool {
        self.peers.contains(&peer)
    }

    pub fn replace_record_members(
        &mut self,
        config: &Config,
        member_records: &[SignedMembershipRecord],
        now_unix_seconds: u64,
    ) -> Result<(), ConfigError> {
        let next = Self::from_config_with_member_records(config, member_records, now_unix_seconds)?;
        self.peers = next.peers;
        self.configured_infrastructure_peers = next.configured_infrastructure_peers;
        Ok(())
    }

    #[must_use]
    fn allows_configured_infrastructure(&self, peer: Libp2pPeerId) -> bool {
        self.configured_infrastructure_peers.contains(&peer)
    }

    #[must_use]
    pub fn len(&self) -> usize {
        self.peers.len()
    }

    #[must_use]
    #[cfg(test)]
    fn configured_infrastructure_len(&self) -> usize {
        self.configured_infrastructure_peers.len()
    }

    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.peers.is_empty()
    }
}

fn relay_peer_from_relayed_address(address: &Multiaddr) -> Option<Libp2pPeerId> {
    let mut relay_peer = None;
    for protocol in address {
        match protocol {
            Protocol::P2p(peer) => relay_peer = Some(peer),
            Protocol::P2pCircuit => return relay_peer,
            _ => {}
        }
    }

    None
}

fn spawn_tun_reader(
    mut reader: TunReader,
    metrics: Arc<RuntimeMetrics>,
    mtu: u16,
) -> mpsc::Receiver<Vec<u8>> {
    let (tx, rx) = mpsc::channel(TUN_READ_CHANNEL);
    std::thread::spawn(move || {
        let mut buffer = vec![0; usize::from(mtu)];
        loop {
            match reader.read_packet(&mut buffer) {
                Ok(length) => {
                    metrics.record_tun_read(length);
                    if tx.blocking_send(buffer[..length].to_vec()).is_err() {
                        return;
                    }
                }
                Err(error) => {
                    log_runtime_event(
                        LogLevel::Error,
                        "tun_read_failed",
                        &[("error", &format!("{error:?}"))],
                    );
                    return;
                }
            }
        }
    });
    rx
}

struct RuntimeOutboundDrain<'a> {
    node: &'a mut P2pNode,
    forwarder: &'a Forwarder,
    queues: &'a mut PeerQueues,
    paths: &'a mut PathSet,
    peer_capabilities: &'a PeerCapabilities,
    queue_runtime: &'a mut QueueRuntimeState,
    writer: &'a mut TunWriter,
    packet_plane: &'a PacketPlaneRuntime,
    packet_plane_quic: Option<&'a PacketPlaneQuicRuntime>,
    metrics: &'a RuntimeMetrics,
}

async fn drain_runtime_outbound_queue(drain: RuntimeOutboundDrain<'_>) {
    let RuntimeOutboundDrain {
        node,
        forwarder,
        queues,
        paths,
        peer_capabilities,
        queue_runtime,
        writer,
        packet_plane,
        packet_plane_quic,
        metrics,
    } = drain;
    let mut context = QueueDrainContext {
        paths,
        peer_capabilities,
        bootstrap_addresses: &node.bootstrap_peer_addresses,
        relay_addresses: &node.relay_peer_addresses,
        configured_peer_addresses: &node.configured_peer_addresses,
        discovered_peer_addresses: &mut queue_runtime.discovered_peer_addresses,
        packet_in_flight: &mut queue_runtime.packet_in_flight,
        last_blocked_queue_redial: &mut queue_runtime.last_blocked_queue_redial,
        writer: Some(writer),
        packet_plane: Some(packet_plane),
        packet_plane_quic,
        metrics,
    };
    drain_outbound_queue(&mut node.swarm, forwarder, queues, &mut context).await;
}

async fn drain_outbound_queue(
    swarm: &mut Swarm<Behaviour>,
    forwarder: &Forwarder,
    queues: &mut PeerQueues,
    context: &mut QueueDrainContext<'_>,
) {
    expire_outbound_queue(queues, context.metrics);
    while let Some(packet) = queues.dequeue_ready_packet(|peer, packet| {
        let decision = packet_transport_decision(
            context.paths,
            context.peer_capabilities,
            context.packet_plane,
            context.packet_plane_quic,
            peer,
        );
        packet_in_flight_allows(context.packet_in_flight, packet, decision) && decision.can_send()
    }) {
        let peer_mtu = selected_path_mtu(
            context.paths,
            context.peer_capabilities,
            context.packet_plane,
            context.packet_plane_quic,
            packet.peer(),
            u16::try_from(forwarder.mtu()).unwrap_or(u16::MAX),
        );
        match packet_transport_decision(
            context.paths,
            context.peer_capabilities,
            context.packet_plane,
            context.packet_plane_quic,
            packet.peer(),
        ) {
            PacketTransportDecision::PacketPlaneDatagram { path, backend } => {
                send_dequeued_packet_plane_datagram(
                    swarm, forwarder, &packet, peer_mtu, path, backend, context,
                )
                .await;
            }
            PacketTransportDecision::StreamFallback { path } => {
                send_dequeued_stream_fallback(swarm, forwarder, &packet, peer_mtu, path, context);
            }
            PacketTransportDecision::Blocked { reason, .. } => {
                if reason == PacketTransportBlockReason::LocalQuicDatagramsUnavailable {
                    context.metrics.record_outbound_quic_datagram_unavailable();
                }
            }
        }
    }
    if queues.total_stats().queued_packets > 0 {
        let mut blocked_by_window = false;
        let mut blocked_by_path = false;
        for peer in queues.queued_peers() {
            let decision = packet_transport_decision(
                context.paths,
                context.peer_capabilities,
                context.packet_plane,
                context.packet_plane_quic,
                peer,
            );
            if decision.can_send()
                && !queues.peer_has_ready_packet(peer, |packet| {
                    packet_in_flight_allows(context.packet_in_flight, packet, decision)
                })
            {
                blocked_by_window = true;
                continue;
            }
            blocked_by_path = true;
            if let PacketTransportDecision::Blocked {
                reason: PacketTransportBlockReason::LocalQuicDatagramsUnavailable,
                ..
            } = decision
            {
                context.metrics.record_outbound_quic_datagram_unavailable();
            }
        }
        if blocked_by_window {
            context
                .metrics
                .record_outbound_queue_blocked_packet_window();
        }
        if blocked_by_path {
            context
                .metrics
                .record_outbound_queue_blocked_no_supported_path();
            if should_redial_blocked_queue(context.last_blocked_queue_redial, Instant::now()) {
                dial_blocked_queue_peers(swarm, forwarder, queues, context);
            }
        }
    }
}

fn packet_in_flight_allows(
    packet_in_flight: &PacketInFlight,
    packet: &crate::queue::Packet,
    decision: PacketTransportDecision,
) -> bool {
    if matches!(decision, PacketTransportDecision::StreamFallback { .. }) {
        return packet_in_flight
            .can_send_packet_with_shard_window(packet, stream_fallback_shard_window(packet));
    }

    packet_in_flight.can_send_packet(packet)
}

fn stream_fallback_shard_window(packet: &crate::queue::Packet) -> usize {
    if packet.requires_ordered_delivery() {
        STREAM_FALLBACK_ORDERED_FLOW_WINDOW
    } else {
        usize::MAX
    }
}

async fn send_dequeued_packet_plane_datagram(
    swarm: &mut Swarm<Behaviour>,
    forwarder: &Forwarder,
    packet: &crate::queue::Packet,
    peer_mtu: u16,
    path: PathKind,
    backend: PacketDatagramBackend,
    context: &mut QueueDrainContext<'_>,
) {
    match forwarder.queued_packet_frame_with_mtu(packet, peer_mtu) {
        Ok(frame) => match send_packet_plane_frame(
            context.packet_plane,
            context.packet_plane_quic,
            backend,
            packet.peer(),
            &frame,
        )
        .await
        {
            Ok(_) => {
                context.metrics.record_outbound_sent();
                context.metrics.record_outbound_quic_datagram();
            }
            Err(error) => {
                let demoted = maybe_demote_packet_plane_send_path(
                    context.paths,
                    context.metrics,
                    packet.peer(),
                    path,
                    &error,
                );
                if demoted && let Some(peer) = forwarder.transport_peer_for_overlay(packet.peer()) {
                    redial_packet_plane_recovery_addresses(
                        swarm,
                        peer,
                        context.configured_peer_addresses,
                        context.relay_addresses,
                        context.discovered_peer_addresses,
                        context.metrics,
                    );
                }
                if send_dequeued_packet_plane_fallback(
                    swarm,
                    forwarder,
                    PacketPlaneFallbackAttempt {
                        packet,
                        peer_mtu,
                        path,
                        failed_backend: backend,
                        frame: &frame,
                    },
                    context,
                )
                .await
                {
                    return;
                }
                context
                    .metrics
                    .record_outbound_drop(packet_plane_send_drop_reason(&error));
                eprintln!("dropping queued packet-plane outbound packet: {error:?}");
            }
        },
        Err(error) => {
            maybe_learn_path_mtu(context, packet.peer(), path, None, &error);
            maybe_write_packet_too_big(context, packet.payload(), &error);
            context
                .metrics
                .record_outbound_drop(outbound_drop_reason(&error));
            eprintln!("dropping queued packet-plane outbound packet: {error:?}");
        }
    }
}

struct PacketPlaneFallbackAttempt<'a> {
    packet: &'a crate::queue::Packet,
    peer_mtu: u16,
    path: PathKind,
    failed_backend: PacketDatagramBackend,
    frame: &'a Frame,
}

async fn send_dequeued_packet_plane_fallback(
    swarm: &mut Swarm<Behaviour>,
    forwarder: &Forwarder,
    attempt: PacketPlaneFallbackAttempt<'_>,
    context: &mut QueueDrainContext<'_>,
) -> bool {
    if let Some(backend) = packet_plane_send_fallback_backend(
        attempt.failed_backend,
        context.peer_capabilities,
        context.packet_plane,
        attempt.packet.peer(),
    ) {
        match send_packet_plane_frame(
            context.packet_plane,
            context.packet_plane_quic,
            backend,
            attempt.packet.peer(),
            attempt.frame,
        )
        .await
        {
            Ok(_) => {
                record_packet_plane_path_established(
                    context.paths,
                    context.metrics,
                    attempt.packet.peer(),
                    backend,
                    attempt.peer_mtu,
                );
                context.metrics.record_outbound_sent();
                context.metrics.record_outbound_quic_datagram();
                log_runtime_event(
                    LogLevel::Warn,
                    "packet_plane_backend_fallback",
                    &[
                        ("peer", &attempt.packet.peer().to_string()),
                        ("from", packet_datagram_backend_name(attempt.failed_backend)),
                        ("to", packet_datagram_backend_name(backend)),
                    ],
                );
                return true;
            }
            Err(error) => {
                if maybe_demote_packet_plane_send_path(
                    context.paths,
                    context.metrics,
                    attempt.packet.peer(),
                    attempt.path,
                    &error,
                ) && let Some(peer) = forwarder.transport_peer_for_overlay(attempt.packet.peer())
                {
                    redial_packet_plane_recovery_addresses(
                        swarm,
                        peer,
                        context.configured_peer_addresses,
                        context.relay_addresses,
                        context.discovered_peer_addresses,
                        context.metrics,
                    );
                }
                context
                    .metrics
                    .record_outbound_drop(packet_plane_send_drop_reason(&error));
                eprintln!("dropping queued packet-plane fallback outbound packet: {error:?}");
                return true;
            }
        }
    }

    if let Some(path) = packet_plane_send_stream_fallback_path(
        context.paths,
        context.peer_capabilities,
        attempt.packet.peer(),
    ) {
        log_runtime_event(
            LogLevel::Warn,
            "packet_plane_backend_fallback",
            &[
                ("peer", &attempt.packet.peer().to_string()),
                ("from", packet_datagram_backend_name(attempt.failed_backend)),
                ("to", path.kind.wire_name()),
            ],
        );
        send_dequeued_stream_fallback(
            swarm,
            forwarder,
            attempt.packet,
            attempt.peer_mtu,
            path,
            context,
        );
        return true;
    }

    false
}

async fn send_packet_plane_frame(
    packet_plane: Option<&PacketPlaneRuntime>,
    packet_plane_quic: Option<&PacketPlaneQuicRuntime>,
    backend: PacketDatagramBackend,
    peer: PeerId,
    frame: &Frame,
) -> Result<usize, PacketPlaneSendError> {
    match backend {
        PacketDatagramBackend::OwnedUdp => packet_plane
            .ok_or(PacketPlaneSendError::MissingUdpRuntime)?
            .send_frame_to_peer(peer, frame)
            .await
            .map_err(PacketPlaneSendError::Udp),
        PacketDatagramBackend::OwnedQuic => packet_plane_quic
            .ok_or(PacketPlaneSendError::MissingQuicRuntime)?
            .send_frame_to_peer(peer, frame)
            .map_err(PacketPlaneSendError::Quic),
    }
}

fn send_dequeued_stream_fallback(
    swarm: &mut Swarm<Behaviour>,
    forwarder: &Forwarder,
    packet: &crate::queue::Packet,
    peer_mtu: u16,
    path: crate::path::PathCandidate,
    context: &mut QueueDrainContext<'_>,
) {
    if matches!(
        path.kind,
        PathKind::DirectQuicStream | PathKind::CircuitRelay
    ) {
        send_dequeued_pinned_stream(swarm, forwarder, packet, peer_mtu, path, context);
        return;
    }

    match forwarder.send_queued_packet_with_mtu(swarm, packet, peer_mtu) {
        Ok(request_id) => {
            context.packet_in_flight.record(
                packet,
                PacketInFlightId::RequestResponse(request_id),
                path,
            );
            context.metrics.record_outbound_sent();
            context.metrics.record_outbound_stream_fallback(path.kind);
        }
        Err(error) => {
            maybe_learn_path_mtu(context, packet.peer(), path.kind, path.relay_peer, &error);
            maybe_write_packet_too_big(context, packet.payload(), &error);
            context
                .metrics
                .record_outbound_drop(outbound_drop_reason(&error));
            eprintln!("dropping queued outbound packet: {error:?}");
        }
    }
}

fn send_dequeued_pinned_stream(
    swarm: &mut Swarm<Behaviour>,
    forwarder: &Forwarder,
    packet: &crate::queue::Packet,
    peer_mtu: u16,
    path: crate::path::PathCandidate,
    context: &mut QueueDrainContext<'_>,
) {
    let Some(connection_id) = path.latest_connection_id else {
        context
            .metrics
            .record_outbound_drop(PacketDropReason::NoRoute);
        eprintln!(
            "dropping queued outbound pinned stream packet: selected path has no connection id"
        );
        return;
    };
    let Some(transport_peer) = forwarder.transport_peer_for_overlay(packet.peer()) else {
        context
            .metrics
            .record_outbound_drop(PacketDropReason::NoRoute);
        eprintln!("dropping queued outbound pinned stream packet: missing transport peer");
        return;
    };

    match forwarder.queued_packet_frame_with_mtu(packet, peer_mtu) {
        Ok(frame) => {
            let request_id = swarm
                .behaviour_mut()
                .pinned_packet_stream
                .send_request_on_connection(transport_peer, connection_id, frame);
            context.packet_in_flight.record(
                packet,
                PacketInFlightId::PinnedPacketStream(request_id),
                path,
            );
            context.metrics.record_outbound_sent();
            context.metrics.record_outbound_stream_fallback(path.kind);
        }
        Err(error) => {
            maybe_learn_path_mtu(context, packet.peer(), path.kind, path.relay_peer, &error);
            maybe_write_packet_too_big(context, packet.payload(), &error);
            context
                .metrics
                .record_outbound_drop(outbound_drop_reason(&error));
            eprintln!("dropping queued outbound pinned stream packet: {error:?}");
        }
    }
}

struct QueueDrainContext<'a> {
    paths: &'a mut PathSet,
    peer_capabilities: &'a PeerCapabilities,
    bootstrap_addresses: &'a [(Libp2pPeerId, Multiaddr)],
    relay_addresses: &'a [(Libp2pPeerId, Multiaddr)],
    configured_peer_addresses: &'a [(Libp2pPeerId, Multiaddr)],
    discovered_peer_addresses: &'a mut DiscoveredPeerAddresses,
    packet_in_flight: &'a mut PacketInFlight,
    last_blocked_queue_redial: &'a mut Option<Instant>,
    writer: Option<&'a mut TunWriter>,
    packet_plane: Option<&'a PacketPlaneRuntime>,
    packet_plane_quic: Option<&'a PacketPlaneQuicRuntime>,
    metrics: &'a RuntimeMetrics,
}

fn maybe_learn_path_mtu(
    context: &mut QueueDrainContext<'_>,
    peer: PeerId,
    path: PathKind,
    relay_peer: Option<PeerId>,
    error: &ForwardError,
) {
    let ForwardError::PacketTooLarge { max, .. } = error else {
        return;
    };
    let mtu = u16::try_from(*max).unwrap_or(u16::MAX);
    if context
        .paths
        .lower_path_mtu_for_relay(peer, path, relay_peer, mtu)
    {
        context.metrics.record_outbound_path_mtu_update();
        log_runtime_event(
            LogLevel::Info,
            "path_mtu_updated",
            &[
                ("peer", &peer.to_string()),
                ("path", path.wire_name()),
                ("mtu", &mtu.to_string()),
            ],
        );
    }
}

fn maybe_write_packet_too_big(
    context: &mut QueueDrainContext<'_>,
    original: &[u8],
    error: &ForwardError,
) {
    let ForwardError::PacketTooLarge { max, .. } = error else {
        return;
    };
    let mtu = u16::try_from(*max).unwrap_or(u16::MAX);
    let Some(notification) = packet_too_big(original, mtu) else {
        context.metrics.record_outbound_packet_too_big_unparseable();
        return;
    };
    let Some(writer) = context.writer.as_deref_mut() else {
        context.metrics.record_outbound_packet_too_big_no_writer();
        return;
    };
    match writer.write_packet(&notification) {
        Ok(length) => {
            context.metrics.record_tun_write(length);
            context
                .metrics
                .record_outbound_packet_too_big_notification();
        }
        Err(error) => {
            context
                .metrics
                .record_outbound_packet_too_big_write_failure();
            log_runtime_event(
                LogLevel::Warn,
                "packet_too_big_write_failed",
                &[("error", &format!("{error:?}"))],
            );
        }
    }
}

#[derive(Debug)]
struct QueueRuntimeState {
    discovered_peer_addresses: DiscoveredPeerAddresses,
    packet_in_flight: PacketInFlight,
    last_blocked_queue_redial: Option<Instant>,
}

impl QueueRuntimeState {
    fn new(packet_in_flight_limit_per_peer: usize) -> Self {
        Self {
            discovered_peer_addresses: DiscoveredPeerAddresses::default(),
            packet_in_flight: PacketInFlight::new(packet_in_flight_limit_per_peer),
            last_blocked_queue_redial: None,
        }
    }
}

#[derive(Debug)]
struct PacketInFlight {
    limit_per_peer: usize,
    requests: HashMap<PacketInFlightId, PacketInFlightRequest>,
    peers: HashMap<PeerId, PeerInFlight>,
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
enum PacketInFlightId {
    RequestResponse(request_response::OutboundRequestId),
    PinnedPacketStream(pinned_packet_stream::RequestId),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct PacketInFlightRequest {
    peer: PeerId,
    shard: FlowShard,
    path: PathKind,
    relay_peer: Option<PeerId>,
    sent_at: Instant,
}

impl PacketInFlight {
    fn new(limit_per_peer: usize) -> Self {
        Self {
            limit_per_peer: limit_per_peer.max(1),
            requests: HashMap::new(),
            peers: HashMap::new(),
        }
    }

    fn can_send(&self, peer: PeerId) -> bool {
        self.peers.get(&peer).map_or(0, |state| state.total) < self.limit_per_peer
    }

    fn can_send_packet(&self, packet: &crate::queue::Packet) -> bool {
        self.can_send_packet_with_shard_window(packet, 1)
    }

    fn can_send_packet_with_shard_window(
        &self,
        packet: &crate::queue::Packet,
        shard_window: usize,
    ) -> bool {
        self.can_send(packet.peer())
            && self.peers.get(&packet.peer()).is_none_or(|state| {
                state.in_flight_for_shard(packet.flow_shard()) < shard_window.max(1)
            })
    }

    fn record(
        &mut self,
        packet: &crate::queue::Packet,
        request_id: PacketInFlightId,
        path: crate::path::PathCandidate,
    ) {
        self.requests.insert(
            request_id,
            PacketInFlightRequest {
                peer: packet.peer(),
                shard: packet.flow_shard(),
                path: path.kind,
                relay_peer: path.relay_peer,
                sent_at: Instant::now(),
            },
        );
        self.peers
            .entry(packet.peer())
            .or_default()
            .record(packet.flow_shard());
    }

    fn record_path_probe(
        &mut self,
        peer: PeerId,
        request_id: request_response::OutboundRequestId,
        path: PathKind,
        relay_peer: Option<PeerId>,
    ) {
        self.requests.insert(
            PacketInFlightId::RequestResponse(request_id),
            PacketInFlightRequest {
                peer,
                shard: 0,
                path,
                relay_peer,
                sent_at: Instant::now(),
            },
        );
        self.peers.entry(peer).or_default().record(0);
    }

    fn complete(&mut self, request_id: PacketInFlightId) -> Option<PacketInFlightRequest> {
        let request = self.requests.remove(&request_id)?;
        if let Some(state) = self.peers.get_mut(&request.peer) {
            state.complete(request.shard);
            if state.total == 0 {
                self.peers.remove(&request.peer);
            }
        }
        Some(request)
    }

    fn stats(&self) -> PacketInFlightStats {
        PacketInFlightStats {
            packets: self.requests.len(),
            peers: self.peers.len(),
            shards: self.peers.values().map(PeerInFlight::active_shards).sum(),
            limit_per_peer: self.limit_per_peer,
        }
    }

    #[cfg(test)]
    fn in_flight_for(&self, peer: PeerId) -> usize {
        self.peers.get(&peer).map_or(0, |state| state.total)
    }
}

#[derive(Clone, Debug, Default)]
struct PeerInFlight {
    total: usize,
    shards: HashMap<FlowShard, usize>,
}

impl PeerInFlight {
    fn record(&mut self, shard: FlowShard) {
        self.total += 1;
        *self.shards.entry(shard).or_default() += 1;
    }

    fn complete(&mut self, shard: FlowShard) {
        self.total = self.total.saturating_sub(1);
        if let Some(count) = self.shards.get_mut(&shard) {
            *count = count.saturating_sub(1);
            if *count == 0 {
                self.shards.remove(&shard);
            }
        }
    }

    fn in_flight_for_shard(&self, shard: FlowShard) -> usize {
        self.shards.get(&shard).copied().unwrap_or(0)
    }

    fn active_shards(&self) -> usize {
        self.shards.len()
    }
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct PacketInFlightStats {
    packets: usize,
    peers: usize,
    shards: usize,
    limit_per_peer: usize,
}

fn dial_blocked_queue_peers(
    swarm: &mut Swarm<Behaviour>,
    forwarder: &Forwarder,
    queues: &PeerQueues,
    context: &mut QueueDrainContext<'_>,
) {
    let blocked_transport_peers = queues
        .queued_peers()
        .filter_map(|peer| forwarder.transport_peer_for_overlay(peer))
        .collect::<HashSet<_>>();
    if blocked_transport_peers.is_empty() {
        return;
    }

    let discovered_addresses = context
        .discovered_peer_addresses
        .redial_candidates_at(Instant::now());
    redial_selected_addresses(
        swarm,
        &blocked_transport_peers,
        context.bootstrap_addresses,
        context.relay_addresses,
        context.configured_peer_addresses,
        &discovered_addresses,
        context.discovered_peer_addresses,
        context.paths,
        context.metrics,
    );
}

fn should_redial_blocked_queue(last_redial: &mut Option<Instant>, now: Instant) -> bool {
    if last_redial.is_some_and(|last| now.duration_since(last) < BLOCKED_QUEUE_REDIAL_INTERVAL) {
        return false;
    }

    *last_redial = Some(now);
    true
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum PacketTransportDecision {
    PacketPlaneDatagram {
        path: PathKind,
        backend: PacketDatagramBackend,
    },
    StreamFallback {
        path: crate::path::PathCandidate,
    },
    Blocked {
        reason: PacketTransportBlockReason,
        best_path: Option<PathKind>,
    },
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum PacketDatagramBackend {
    OwnedQuic,
    OwnedUdp,
}

const fn packet_datagram_backend_name(backend: PacketDatagramBackend) -> &'static str {
    match backend {
        PacketDatagramBackend::OwnedQuic => "owned_quic",
        PacketDatagramBackend::OwnedUdp => "owned_udp",
    }
}

const fn packet_datagram_backend_path_kind(backend: PacketDatagramBackend) -> PathKind {
    match backend {
        PacketDatagramBackend::OwnedQuic => PathKind::DirectQuicDatagram,
        PacketDatagramBackend::OwnedUdp => PathKind::DirectUdpDatagram,
    }
}

#[derive(Debug)]
enum PacketPlaneSendError {
    MissingUdpRuntime,
    MissingQuicRuntime,
    Udp(PacketPlaneIoError),
    Quic(PacketPlaneQuicError),
}

impl PacketTransportDecision {
    const fn can_send(self) -> bool {
        matches!(
            self,
            Self::PacketPlaneDatagram { .. } | Self::StreamFallback { .. }
        )
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum PacketTransportBlockReason {
    MissingCapabilities,
    NoHealthyPath,
    LocalQuicDatagramsUnavailable,
}

fn packet_transport_decision(
    paths: &PathSet,
    peer_capabilities: &PeerCapabilities,
    packet_plane: Option<&PacketPlaneRuntime>,
    packet_plane_quic: Option<&PacketPlaneQuicRuntime>,
    peer: PeerId,
) -> PacketTransportDecision {
    if !peer_capabilities.contains(peer) {
        return PacketTransportDecision::Blocked {
            reason: PacketTransportBlockReason::MissingCapabilities,
            best_path: paths.best_for(peer).map(|path| path.kind),
        };
    }

    let datagram_backend =
        local_packet_datagram_backend(peer_capabilities, packet_plane, packet_plane_quic, peer);
    let local_datagrams = datagram_backend.is_some();
    let support = packet_transport_support_for_backend(peer_capabilities, peer, datagram_backend);
    if let Some(path) = best_packet_transport_path(paths, peer, support) {
        return if path.kind.requires_quic_datagrams() {
            PacketTransportDecision::PacketPlaneDatagram {
                path: path.kind,
                backend: datagram_backend.expect("supported datagram path requires backend"),
            }
        } else {
            PacketTransportDecision::StreamFallback { path }
        };
    }

    let best_path = paths.best_for(peer).map(|path| path.kind);
    let reason = if best_path.is_some_and(PathKind::requires_quic_datagrams)
        && peer_capabilities.supports_datagram_packet_path_for(peer)
        && !local_datagrams
    {
        PacketTransportBlockReason::LocalQuicDatagramsUnavailable
    } else {
        PacketTransportBlockReason::NoHealthyPath
    };
    PacketTransportDecision::Blocked { reason, best_path }
}

fn best_packet_transport_path(
    paths: &PathSet,
    peer: PeerId,
    support: PathTransportSupport,
) -> Option<crate::path::PathCandidate> {
    paths.best_supported_for(peer, support)
}

fn local_packet_datagram_backend(
    peer_capabilities: &PeerCapabilities,
    packet_plane: Option<&PacketPlaneRuntime>,
    packet_plane_quic: Option<&PacketPlaneQuicRuntime>,
    peer: PeerId,
) -> Option<PacketDatagramBackend> {
    if packet_plane_quic.is_some_and(|packet_plane| packet_plane.has_session(peer))
        && peer_capabilities.supports_owned_quic_packet_plane_for(peer)
    {
        return Some(PacketDatagramBackend::OwnedQuic);
    }
    if packet_plane.is_some_and(|packet_plane| packet_plane.has_session(peer))
        && peer_capabilities.supports_owned_udp_packet_plane_for(peer)
    {
        return Some(PacketDatagramBackend::OwnedUdp);
    }
    None
}

fn packet_plane_send_fallback_backend(
    failed_backend: PacketDatagramBackend,
    peer_capabilities: &PeerCapabilities,
    packet_plane: Option<&PacketPlaneRuntime>,
    peer: PeerId,
) -> Option<PacketDatagramBackend> {
    if failed_backend == PacketDatagramBackend::OwnedQuic
        && packet_plane.is_some_and(|packet_plane| packet_plane.has_session(peer))
        && peer_capabilities.supports_owned_udp_packet_plane_for(peer)
    {
        return Some(PacketDatagramBackend::OwnedUdp);
    }
    None
}

fn has_active_packet_plane_session(
    packet_plane: Option<&PacketPlaneRuntime>,
    packet_plane_quic: Option<&PacketPlaneQuicRuntime>,
    peer: PeerId,
) -> bool {
    packet_plane.is_some_and(|packet_plane| packet_plane.has_session(peer))
        || packet_plane_quic.is_some_and(|packet_plane| packet_plane.has_session(peer))
}

fn packet_plane_send_stream_fallback_path(
    paths: &PathSet,
    peer_capabilities: &PeerCapabilities,
    peer: PeerId,
) -> Option<crate::path::PathCandidate> {
    paths
        .best_supported_for(
            peer,
            packet_transport_support_for_backend(peer_capabilities, peer, None),
        )
        .filter(|path| !path.kind.requires_quic_datagrams())
}

fn packet_transport_support(
    peer_capabilities: &PeerCapabilities,
    peer: PeerId,
) -> PathTransportSupport {
    PathTransportSupport {
        udp_datagrams: false,
        quic_datagrams: local_packet_data_plane().native_quic_datagrams
            && peer_capabilities.supports_datagram_packet_path_for(peer),
    }
}

fn packet_transport_support_for_backend(
    peer_capabilities: &PeerCapabilities,
    peer: PeerId,
    backend: Option<PacketDatagramBackend>,
) -> PathTransportSupport {
    PathTransportSupport {
        udp_datagrams: backend == Some(PacketDatagramBackend::OwnedUdp)
            && peer_capabilities.supports_owned_udp_packet_plane_for(peer),
        quic_datagrams: backend == Some(PacketDatagramBackend::OwnedQuic)
            && peer_capabilities.supports_owned_quic_packet_plane_for(peer),
    }
}

fn public_discovery_suppressed(
    holdoff_until: Option<Instant>,
    forwarder: &Forwarder,
    paths: &PathSet,
    peer_capabilities: &PeerCapabilities,
    packet_plane: Option<&PacketPlaneRuntime>,
    packet_plane_quic: Option<&PacketPlaneQuicRuntime>,
) -> bool {
    holdoff_until.is_some_and(|until| Instant::now() < until)
        || public_discovery_quiet_mode(
            forwarder,
            paths,
            peer_capabilities,
            packet_plane,
            packet_plane_quic,
        )
}

fn reconcile_public_kademlia_mode(
    swarm: &mut Swarm<Behaviour>,
    discovery: &DiscoveryConfig,
    public_discovery_suppressed: bool,
) {
    if !discovery.kademlia || discovery.kademlia_protocol != PUBLIC_IPFS_KADEMLIA_PROTOCOL {
        return;
    }

    let mode = if public_discovery_suppressed {
        kad::Mode::Client
    } else {
        kad::Mode::Server
    };
    swarm.behaviour_mut().kad.set_mode(Some(mode));
}

fn public_discovery_quiet_mode(
    forwarder: &Forwarder,
    paths: &PathSet,
    peer_capabilities: &PeerCapabilities,
    packet_plane: Option<&PacketPlaneRuntime>,
    packet_plane_quic: Option<&PacketPlaneQuicRuntime>,
) -> bool {
    let peers = forwarder.configured_overlay_peers().collect::<Vec<_>>();
    !peers.is_empty()
        && peers.into_iter().all(|peer| {
            peer_has_healthy_supported_path(
                paths,
                peer_capabilities,
                packet_plane,
                packet_plane_quic,
                peer,
            )
        })
}

fn peer_has_healthy_supported_path(
    paths: &PathSet,
    peer_capabilities: &PeerCapabilities,
    packet_plane: Option<&PacketPlaneRuntime>,
    packet_plane_quic: Option<&PacketPlaneQuicRuntime>,
    peer: PeerId,
) -> bool {
    let datagram_backend =
        local_packet_datagram_backend(peer_capabilities, packet_plane, packet_plane_quic, peer);
    let support = packet_transport_support_for_backend(peer_capabilities, peer, datagram_backend);
    paths
        .candidates_for(peer)
        .any(|path| path.healthy && support.supports(path.kind))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct MembershipProbeConnection {
    connection_id: ConnectionId,
    relayed: bool,
    expires_at: Instant,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct MembershipProbeQuarantine {
    consecutive_failures: u32,
    retry_at: Instant,
    last_failure: Instant,
    blocked: bool,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct MembershipProbeQuarantineUpdate {
    active_connection_id: Option<ConnectionId>,
    consecutive_failures: u32,
    delay: Duration,
    evicted_blocked_peer: Option<Libp2pPeerId>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum MembershipProbeAdmission {
    Admitted,
    Replaced(ConnectionId),
    Duplicate,
    Quarantined,
}

#[derive(Debug, Default)]
struct MembershipProbeConnections {
    by_peer: HashMap<Libp2pPeerId, MembershipProbeConnection>,
    quarantines: HashMap<Libp2pPeerId, MembershipProbeQuarantine>,
}

impl MembershipProbeConnections {
    fn admit(
        &mut self,
        peer: Libp2pPeerId,
        connection_id: ConnectionId,
        relayed: bool,
        now: Instant,
    ) -> MembershipProbeAdmission {
        if self.is_quarantined(peer, now) {
            return MembershipProbeAdmission::Quarantined;
        }
        let next = MembershipProbeConnection {
            connection_id,
            relayed,
            expires_at: now + MEMBERSHIP_PROBE_CONNECTION_TTL,
        };
        let Some(existing) = self.by_peer.get(&peer).copied() else {
            self.by_peer.insert(peer, next);
            return MembershipProbeAdmission::Admitted;
        };
        if existing.connection_id == connection_id {
            self.by_peer.insert(peer, next);
            return MembershipProbeAdmission::Admitted;
        }
        if existing.relayed && !relayed {
            self.by_peer.insert(peer, next);
            return MembershipProbeAdmission::Replaced(existing.connection_id);
        }

        MembershipProbeAdmission::Duplicate
    }

    fn is_quarantined(&self, peer: Libp2pPeerId, now: Instant) -> bool {
        self.quarantines
            .get(&peer)
            .is_some_and(|quarantine| quarantine.blocked && now < quarantine.retry_at)
    }

    fn remove(&mut self, peer: Libp2pPeerId, connection_id: ConnectionId) -> bool {
        if self
            .by_peer
            .get(&peer)
            .is_some_and(|probe| probe.connection_id == connection_id)
        {
            self.by_peer.remove(&peer);
            return true;
        }
        false
    }

    fn release_probe(&mut self, peer: Libp2pPeerId) -> bool {
        self.by_peer.remove(&peer).is_some()
    }

    fn authorize(&mut self, peer: Libp2pPeerId) -> bool {
        self.by_peer.remove(&peer);
        self.clear_quarantine(peer)
    }

    fn clear_quarantine(&mut self, peer: Libp2pPeerId) -> bool {
        self.quarantines
            .remove(&peer)
            .is_some_and(|quarantine| quarantine.blocked)
    }

    fn quarantine(&mut self, peer: Libp2pPeerId, now: Instant) -> MembershipProbeQuarantineUpdate {
        let active_connection_id = self.by_peer.remove(&peer).map(|probe| probe.connection_id);
        let consecutive_failures = self.quarantines.get(&peer).map_or(1, |quarantine| {
            if now.saturating_duration_since(quarantine.last_failure)
                >= MEMBERSHIP_PROBE_QUARANTINE_RESET
            {
                1
            } else {
                quarantine.consecutive_failures.saturating_add(1)
            }
        });
        let shift = consecutive_failures.saturating_sub(1).min(8);
        let delay = MEMBERSHIP_PROBE_QUARANTINE_BASE
            .saturating_mul(1_u32 << shift)
            .min(MEMBERSHIP_PROBE_QUARANTINE_MAX);
        let evicted_blocked_peer = if !self.quarantines.contains_key(&peer)
            && self.quarantines.len() >= MEMBERSHIP_PROBE_QUARANTINE_CAPACITY
        {
            self.quarantines
                .iter()
                .min_by_key(|(_, quarantine)| quarantine.last_failure)
                .map(|(peer, _)| *peer)
                .and_then(|evicted| {
                    self.quarantines
                        .remove(&evicted)
                        .is_some_and(|quarantine| quarantine.blocked)
                        .then_some(evicted)
                })
        } else {
            None
        };
        self.quarantines.insert(
            peer,
            MembershipProbeQuarantine {
                consecutive_failures,
                retry_at: now + delay,
                last_failure: now,
                blocked: true,
            },
        );

        MembershipProbeQuarantineUpdate {
            active_connection_id,
            consecutive_failures,
            delay,
            evicted_blocked_peer,
        }
    }

    fn release_ready_quarantines(&mut self, now: Instant) -> Vec<Libp2pPeerId> {
        let mut released = Vec::new();
        self.quarantines.retain(|peer, quarantine| {
            if quarantine.blocked && now >= quarantine.retry_at {
                quarantine.blocked = false;
                released.push(*peer);
            }
            quarantine.blocked
                || now.saturating_duration_since(quarantine.last_failure)
                    < MEMBERSHIP_PROBE_QUARANTINE_RESET
        });
        released
    }

    fn quarantined_peers(&self) -> Vec<Libp2pPeerId> {
        self.quarantines
            .iter()
            .filter_map(|(peer, quarantine)| quarantine.blocked.then_some(*peer))
            .collect()
    }

    fn expired(&self, now: Instant) -> Vec<(Libp2pPeerId, ConnectionId)> {
        self.by_peer
            .iter()
            .filter_map(|(peer, probe)| {
                (now >= probe.expires_at).then_some((*peer, probe.connection_id))
            })
            .collect()
    }

    fn defer(&mut self, peer: Libp2pPeerId, connection_id: ConnectionId, now: Instant) {
        if let Some(probe) = self.by_peer.get_mut(&peer)
            && probe.connection_id == connection_id
        {
            probe.expires_at = now + MEMBERSHIP_PROBE_CONNECTION_TTL;
        }
    }
}

fn authorize_membership_probe_peer(
    swarm: &mut Swarm<Behaviour>,
    probes: &mut MembershipProbeConnections,
    peer: Libp2pPeerId,
    reason: &str,
) {
    let tracked_block = probes.authorize(peer);
    let unblocked = swarm.behaviour_mut().blocked_peers.unblock_peer(peer);
    if tracked_block || unblocked {
        log_runtime_event(
            LogLevel::Info,
            "membership_probe_peer_authorized",
            &[("peer", &peer.to_string()), ("reason", reason)],
        );
    }
}

fn classify_membership_probe_as_routing(
    probes: &mut MembershipProbeConnections,
    peer: Libp2pPeerId,
) {
    if probes.release_probe(peer) {
        log_runtime_event(
            LogLevel::Info,
            "membership_probe_peer_classified",
            &[("peer", &peer.to_string()), ("role", "public_routing")],
        );
    }
}

fn clear_membership_probe_quarantine(
    swarm: &mut Swarm<Behaviour>,
    probes: &mut MembershipProbeConnections,
    peer: Libp2pPeerId,
    reason: &str,
) {
    let tracked_block = probes.clear_quarantine(peer);
    let unblocked = swarm.behaviour_mut().blocked_peers.unblock_peer(peer);
    if tracked_block || unblocked {
        log_runtime_event(
            LogLevel::Info,
            "membership_probe_peer_unblocked",
            &[("peer", &peer.to_string()), ("reason", reason)],
        );
    }
}

fn quarantine_membership_probe_peer(
    swarm: &mut Swarm<Behaviour>,
    probes: &mut MembershipProbeConnections,
    peer: Libp2pPeerId,
    now: Instant,
    reason: &str,
) -> MembershipProbeQuarantineUpdate {
    let update = probes.quarantine(peer, now);
    if let Some(evicted) = update.evicted_blocked_peer {
        swarm.behaviour_mut().blocked_peers.unblock_peer(evicted);
        log_runtime_event(
            LogLevel::Warn,
            "membership_probe_quarantine_evicted",
            &[("peer", &evicted.to_string())],
        );
    }
    let newly_blocked = swarm.behaviour_mut().blocked_peers.block_peer(peer);
    if let Some(connection_id) = update.active_connection_id {
        swarm.close_connection(connection_id);
    }
    log_runtime_event(
        LogLevel::Warn,
        "membership_probe_peer_quarantined",
        &[
            ("peer", &peer.to_string()),
            ("reason", reason),
            ("delay_seconds", &update.delay.as_secs().to_string()),
            (
                "consecutive_failures",
                &update.consecutive_failures.to_string(),
            ),
            ("newly_blocked", &newly_blocked.to_string()),
        ],
    );
    update
}

fn quarantine_rejected_control_probe(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    peer: Libp2pPeerId,
    connection_id: ConnectionId,
    reason: ControlRejectionReason,
) {
    if context.membership.allows(peer) {
        return;
    }
    context.routing_infrastructure_peers.remove(peer);
    context.metrics.record_unauthorized_connection_dropped();
    quarantine_membership_probe_peer(
        swarm,
        context.membership_probe_connections,
        peer,
        Instant::now(),
        "control_capabilities_rejected",
    );
    let close_requested = swarm.close_connection(connection_id);
    log_runtime_event(
        LogLevel::Warn,
        "rejected_control_probe_disconnected",
        &[
            ("peer", &peer.to_string()),
            ("reason", control_rejection_name(reason)),
            ("close_requested", &close_requested.to_string()),
        ],
    );
}

fn rejected_control_probe_reason(
    response: &ControlResponse,
    membership: &OverlayMembership,
    peer: Libp2pPeerId,
) -> Option<ControlRejectionReason> {
    match response {
        ControlResponse::CapabilitiesRejected(reason) if !membership.allows(peer) => Some(*reason),
        _ => None,
    }
}

fn expire_membership_probe_connections(
    swarm: &mut Swarm<Behaviour>,
    probes: &mut MembershipProbeConnections,
    membership: &OverlayMembership,
    infrastructure_peers: &InfrastructurePeers,
    routing_infrastructure_peers: &RoutingInfrastructurePeers,
    code_pairing_sessions: &CodePairingSessions,
    metrics: &RuntimeMetrics,
    now: Instant,
) {
    for peer in probes.quarantined_peers() {
        if routing_infrastructure_peers.contains(peer) {
            continue;
        }
        if membership.allows(peer)
            || membership.allows_configured_infrastructure(peer)
            || infrastructure_peers.contains(peer)
        {
            authorize_membership_probe_peer(swarm, probes, peer, "membership_available");
        } else if code_pairing_sessions.allows_pairing_probe(peer) {
            clear_membership_probe_quarantine(swarm, probes, peer, "pairing_session_active");
        }
    }

    for (peer, connection_id) in probes.expired(now) {
        if routing_infrastructure_peers.contains(peer) {
            classify_membership_probe_as_routing(probes, peer);
            continue;
        }
        if membership.allows(peer)
            || membership.allows_configured_infrastructure(peer)
            || infrastructure_peers.contains(peer)
        {
            authorize_membership_probe_peer(swarm, probes, peer, "membership_available");
            continue;
        }
        if code_pairing_sessions.allows_pairing_probe(peer) {
            probes.defer(peer, connection_id, now);
            continue;
        }

        metrics.record_unauthorized_connection_dropped();
        let close_requested = swarm.close_connection(connection_id);
        quarantine_membership_probe_peer(swarm, probes, peer, now, "authorization_timeout");
        log_runtime_event(
            LogLevel::Warn,
            "membership_probe_connection_expired",
            &[
                ("peer", &peer.to_string()),
                ("connection_id", &connection_id.to_string()),
                ("close_requested", &close_requested.to_string()),
            ],
        );
    }

    for peer in probes.release_ready_quarantines(now) {
        let unblocked = swarm.behaviour_mut().blocked_peers.unblock_peer(peer);
        log_runtime_event(
            LogLevel::Info,
            "membership_probe_peer_unblocked",
            &[
                ("peer", &peer.to_string()),
                ("reason", "quarantine_expired"),
                ("unblocked", &unblocked.to_string()),
            ],
        );
    }
}

struct SwarmEventContext<'a> {
    forwarder: &'a mut Forwarder,
    membership: &'a mut OverlayMembership,
    tun_runtime: &'a mut TunRuntimeConfig,
    infrastructure_peers: &'a mut InfrastructurePeers,
    routing_infrastructure_peers: &'a mut RoutingInfrastructurePeers,
    writer: &'a mut TunWriter,
    paths: &'a mut PathSet,
    peer_capabilities: &'a mut PeerCapabilities,
    relay_readiness: &'a mut RelayReadiness,
    auto_relay: &'a mut AutoRelayState,
    public_discovery_backoff: &'a mut PublicDiscoveryBackoff,
    relay_addresses: &'a [(Libp2pPeerId, Multiaddr)],
    configured_peer_addresses: &'a [(Libp2pPeerId, Multiaddr)],
    relay_server_enabled: bool,
    discovered_peer_addresses: &'a mut DiscoveredPeerAddresses,
    packet_in_flight: &'a mut PacketInFlight,
    inbound_packet_rate_limiters: &'a mut PeerRateLimiters,
    pairing_request_rate_limiters: &'a mut PeerRateLimiters,
    membership_page_rate_limiters: &'a mut PeerRateLimiters,
    membership_record_syncs: &'a mut MembershipRecordSyncs,
    pairing_handshake_rate_limiter: &'a mut GlobalRateLimiter,
    metrics: &'a RuntimeMetrics,
    local_capabilities: &'a mut ControlCapabilities,
    previous_membership_tags: &'a [String],
    discovery: &'a DiscoveryConfig,
    identity: &'a NodeIdentity,
    packet_plane: &'a mut PacketPlaneRuntime,
    packet_plane_quic: Option<&'a mut PacketPlaneQuicRuntime>,
    packet_plane_negotiator: &'a mut PacketPlaneNegotiator,
    path_probe_tracker: &'a mut PathProbeTracker,
    packet_plane_session_ttl: Duration,
    packet_plane_replay_windows_per_session: usize,
    pairing_replay_tokens: &'a mut PairingReplayTokens,
    code_pairing_sessions: &'a mut CodePairingSessions,
    pairing_state_store: Option<&'a PairingStateStore>,
    active_connections: &'a mut HashMap<(Libp2pPeerId, ConnectionId), ConnectedPoint>,
    membership_probe_connections: &'a mut MembershipProbeConnections,
}

#[derive(Debug, Default)]
struct PairingReplayTokens {
    file_bearer: HashSet<String>,
    code_approval: HashSet<String>,
}

impl PairingReplayTokens {
    fn replace_code_approval(&mut self, tokens: impl IntoIterator<Item = String>) {
        self.code_approval.clear();
        self.code_approval.extend(tokens);
    }
}

#[derive(Clone, Copy)]
struct MembershipValidationScope<'a> {
    network: &'a str,
    current_tag: Option<&'a str>,
    previous_tags: &'a [String],
}

impl<'a> MembershipValidationScope<'a> {
    fn from_capabilities(
        capabilities: &'a ControlCapabilities,
        previous_tags: &'a [String],
    ) -> Self {
        Self {
            network: &capabilities.network_name,
            current_tag: capabilities.membership_tag.as_deref(),
            previous_tags,
        }
    }
}

#[allow(clippy::too_many_lines)]
async fn handle_swarm_event(
    swarm: &mut Swarm<Behaviour>,
    mut context: SwarmEventContext<'_>,
    event: SwarmEvent<BehaviourEvent>,
) -> Result<(), RunnerError> {
    match event {
        SwarmEvent::Behaviour(BehaviourEvent::Control(event)) => {
            handle_control_event(swarm, &mut context, event).await?;
        }
        SwarmEvent::Behaviour(BehaviourEvent::Packet(event)) => {
            handle_packet_event(swarm, &mut context, event)?;
        }
        SwarmEvent::Behaviour(BehaviourEvent::Pairing(event)) => {
            handle_pairing_event(swarm, &mut context, event)?;
        }
        SwarmEvent::Behaviour(BehaviourEvent::PairingCode(event)) => {
            handle_pairing_code_event(swarm, &mut context, event)?;
        }
        SwarmEvent::Behaviour(BehaviourEvent::PinnedPacketStream(event)) => {
            handle_pinned_packet_stream_event(swarm, &mut context, event)?;
        }
        SwarmEvent::Behaviour(BehaviourEvent::Service(event)) => {
            handle_service_event(swarm, &mut context, event)?;
        }
        SwarmEvent::Behaviour(event) => {
            let public_discovery_quiet = public_discovery_quiet_mode(
                context.forwarder,
                context.paths,
                context.peer_capabilities,
                Some(context.packet_plane),
                context.packet_plane_quic.as_deref(),
            );
            let mut behaviour_context = BehaviourEventContext {
                forwarder: context.forwarder,
                membership: context.membership,
                tun_runtime: context.tun_runtime,
                infrastructure_peers: context.infrastructure_peers,
                routing_infrastructure_peers: context.routing_infrastructure_peers,
                relay_readiness: context.relay_readiness,
                auto_relay: context.auto_relay,
                paths: context.paths,
                relay_addresses: context.relay_addresses,
                configured_peer_addresses: context.configured_peer_addresses,
                relay_server_enabled: context.relay_server_enabled,
                discovered_peer_addresses: context.discovered_peer_addresses,
                metrics: context.metrics,
                discovery: context.discovery,
                local_capabilities: context.local_capabilities,
                previous_membership_tags: context.previous_membership_tags,
                identity: context.identity,
                code_pairing_sessions: context.code_pairing_sessions,
                membership_probe_connections: context.membership_probe_connections,
                public_discovery_quiet,
            };
            handle_behaviour_event(swarm, &mut behaviour_context, event);
        }
        SwarmEvent::ConnectionEstablished {
            peer_id,
            connection_id,
            endpoint,
            num_established,
            ..
        } => {
            context
                .active_connections
                .insert((peer_id, connection_id), endpoint.clone());
            if context.membership.allows(peer_id) {
                context.routing_infrastructure_peers.remove(peer_id);
                remove_overlay_peer_from_infrastructure(
                    context.infrastructure_peers,
                    context.auto_relay,
                    peer_id,
                    "overlay_connection_established",
                );
            }
            match authorize_established_connection(
                context.membership,
                context.infrastructure_peers,
                context.routing_infrastructure_peers,
                context.metrics,
                peer_id,
                matches!(endpoint, ConnectedPoint::Listener { .. })
                    || context.code_pairing_sessions.allows_pairing_probe(peer_id),
                context.auto_relay.should_discover_candidates(),
                context.discovery.kademlia,
                context.relay_server_enabled,
            ) {
                EstablishedConnectionAuthorization::OverlayPeer => {
                    authorize_membership_probe_peer(
                        swarm,
                        context.membership_probe_connections,
                        peer_id,
                        "overlay_connection_established",
                    );
                    context
                        .public_discovery_backoff
                        .record_connection_established(peer_id);
                    context
                        .discovered_peer_addresses
                        .record_recovery_connection_at(peer_id, Instant::now());
                }
                EstablishedConnectionAuthorization::InfrastructurePeer => {
                    authorize_membership_probe_peer(
                        swarm,
                        context.membership_probe_connections,
                        peer_id,
                        "infrastructure_connection_established",
                    );
                    context
                        .public_discovery_backoff
                        .record_connection_established(peer_id);
                    advertise_relay_server_listener_address(
                        swarm,
                        context.relay_server_enabled,
                        &endpoint,
                    );
                    log_runtime_event(
                        LogLevel::Info,
                        "relay_infrastructure_connection_established",
                        &[
                            ("peer", &peer_id.to_string()),
                            ("relayed", &endpoint.is_relayed().to_string()),
                        ],
                    );
                    return Ok(());
                }
                EstablishedConnectionAuthorization::RoutingPeer => {
                    classify_membership_probe_as_routing(
                        context.membership_probe_connections,
                        peer_id,
                    );
                    context
                        .public_discovery_backoff
                        .record_connection_established(peer_id);
                    log_runtime_event(
                        LogLevel::Info,
                        "public_routing_connection_established",
                        &[
                            ("peer", &peer_id.to_string()),
                            ("relayed", &endpoint.is_relayed().to_string()),
                            ("state", "identified"),
                        ],
                    );
                    return Ok(());
                }
                EstablishedConnectionAuthorization::MembershipProbe => {
                    let now = Instant::now();
                    match context.membership_probe_connections.admit(
                        peer_id,
                        connection_id,
                        endpoint.is_relayed(),
                        now,
                    ) {
                        MembershipProbeAdmission::Admitted => {}
                        MembershipProbeAdmission::Replaced(replaced_connection_id) => {
                            let close_requested = swarm.close_connection(replaced_connection_id);
                            log_runtime_event(
                                LogLevel::Info,
                                "membership_probe_connection_replaced",
                                &[
                                    ("peer", &peer_id.to_string()),
                                    ("connection_id", &connection_id.to_string()),
                                    (
                                        "replaced_connection_id",
                                        &replaced_connection_id.to_string(),
                                    ),
                                    ("close_requested", &close_requested.to_string()),
                                ],
                            );
                        }
                        MembershipProbeAdmission::Duplicate => {
                            let close_requested = swarm.close_connection(connection_id);
                            context.metrics.record_unauthorized_connection_dropped();
                            quarantine_membership_probe_peer(
                                swarm,
                                context.membership_probe_connections,
                                peer_id,
                                now,
                                "duplicate_connection",
                            );
                            log_runtime_event(
                                LogLevel::Warn,
                                "membership_probe_connection_deduplicated",
                                &[
                                    ("peer", &peer_id.to_string()),
                                    ("connection_id", &connection_id.to_string()),
                                    ("relayed", &endpoint.is_relayed().to_string()),
                                    ("close_requested", &close_requested.to_string()),
                                ],
                            );
                            return Ok(());
                        }
                        MembershipProbeAdmission::Quarantined => {
                            context.metrics.record_unauthorized_connection_dropped();
                            swarm.behaviour_mut().blocked_peers.block_peer(peer_id);
                            let close_requested = swarm.close_connection(connection_id);
                            log_runtime_event(
                                LogLevel::Warn,
                                "membership_probe_connection_suppressed",
                                &[
                                    ("peer", &peer_id.to_string()),
                                    ("connection_id", &connection_id.to_string()),
                                    ("close_requested", &close_requested.to_string()),
                                ],
                            );
                            return Ok(());
                        }
                    }
                    log_runtime_event(
                        LogLevel::Info,
                        "membership_probe_connection_established",
                        &[
                            ("peer", &peer_id.to_string()),
                            ("relayed", &endpoint.is_relayed().to_string()),
                        ],
                    );
                    return Ok(());
                }
                EstablishedConnectionAuthorization::InfrastructureProbe => {
                    admit_connected_auto_relay_infrastructure_probe(
                        swarm,
                        context.forwarder,
                        context.infrastructure_peers,
                        context.auto_relay,
                        context.metrics,
                        peer_id,
                        &endpoint,
                        context.relay_server_enabled,
                    );
                    log_runtime_event(
                        LogLevel::Info,
                        "auto_relay_infrastructure_probe_connection_established",
                        &[
                            ("peer", &peer_id.to_string()),
                            ("relayed", &endpoint.is_relayed().to_string()),
                        ],
                    );
                    return Ok(());
                }
                EstablishedConnectionAuthorization::RoutingProbe => {
                    let admission = context.routing_infrastructure_peers.admit(peer_id);
                    if admission == RoutingInfrastructureAdmission::AtCapacity {
                        let close_requested = swarm.close_connection(connection_id);
                        log_runtime_event(
                            LogLevel::Warn,
                            "public_routing_connection_rejected",
                            &[
                                ("peer", &peer_id.to_string()),
                                ("reason", "capacity"),
                                ("close_requested", &close_requested.to_string()),
                            ],
                        );
                        return Ok(());
                    }
                    context
                        .public_discovery_backoff
                        .record_connection_established(peer_id);
                    let state = if admission == RoutingInfrastructureAdmission::Existing {
                        "existing"
                    } else {
                        "new"
                    };
                    log_runtime_event(
                        LogLevel::Info,
                        "public_routing_probe_connection_established",
                        &[
                            ("peer", &peer_id.to_string()),
                            ("relayed", &endpoint.is_relayed().to_string()),
                            ("state", state),
                        ],
                    );
                    return Ok(());
                }
                EstablishedConnectionAuthorization::Rejected => {
                    quarantine_membership_probe_peer(
                        swarm,
                        context.membership_probe_connections,
                        peer_id,
                        Instant::now(),
                        "outbound_connection_rejected",
                    );
                    log_runtime_event(
                        LogLevel::Warn,
                        "unauthorized_peer_disconnected",
                        &[("peer", &peer_id.to_string())],
                    );
                    if swarm.disconnect_peer_id(peer_id).is_err() {
                        log_runtime_event(
                            LogLevel::Warn,
                            "unauthorized_peer_already_disconnected",
                            &[("peer", &peer_id.to_string())],
                        );
                    }
                    return Ok(());
                }
            }
            invalidate_peer_capabilities_on_first_connection(
                context.forwarder,
                context.peer_capabilities,
                peer_id,
                num_established.get(),
            );
            advertise_direct_packet_plane_endpoint_from_path(
                context.local_capabilities,
                context.packet_plane.primary_listener(),
                &endpoint,
                &context
                    .forwarder
                    .local_advertised_route_prefixes()
                    .collect::<Vec<_>>(),
                context.metrics,
            );
            record_path_established_and_maybe_send_packet_plane_hello(
                swarm,
                context.paths,
                context.forwarder,
                context.peer_capabilities,
                context.metrics,
                context.local_capabilities,
                context.identity,
                context.packet_plane,
                context.packet_plane_quic.as_deref(),
                context.packet_plane_negotiator,
                peer_id,
                connection_id,
                &endpoint,
            );
            send_control_capabilities(
                swarm,
                context.forwarder,
                peer_id,
                context.local_capabilities,
                context.metrics,
            );
            send_service_status_request(
                swarm,
                context.forwarder,
                peer_id,
                context.local_capabilities,
                context.metrics,
            );
            context
                .metrics
                .record_connection_established(endpoint.is_relayed());
            log_runtime_event(
                LogLevel::Info,
                "connection_established",
                &[
                    ("peer", &peer_id.to_string()),
                    ("connection_id", &connection_id.to_string()),
                    ("relayed", &endpoint.is_relayed().to_string()),
                    ("endpoint", &format!("{endpoint:?}")),
                ],
            );
        }
        SwarmEvent::ConnectionClosed {
            peer_id,
            connection_id,
            endpoint,
            num_established,
            ..
        } => {
            context.active_connections.remove(&(peer_id, connection_id));
            let membership_probe_closed = context
                .membership_probe_connections
                .remove(peer_id, connection_id);
            let routing_peer_closed =
                num_established == 0 && context.routing_infrastructure_peers.remove(peer_id);
            if context.membership.allows(peer_id)
                || context.membership.allows_configured_infrastructure(peer_id)
                || context.infrastructure_peers.contains(peer_id)
                || routing_peer_closed
            {
                authorize_membership_probe_peer(
                    swarm,
                    context.membership_probe_connections,
                    peer_id,
                    "authorized_connection_closed",
                );
            } else if membership_probe_closed
                && !context.code_pairing_sessions.allows_pairing_probe(peer_id)
            {
                context.metrics.record_unauthorized_connection_dropped();
                quarantine_membership_probe_peer(
                    swarm,
                    context.membership_probe_connections,
                    peer_id,
                    Instant::now(),
                    "probe_closed_before_authorization",
                );
            }
            if routing_peer_closed {
                log_runtime_event(
                    LogLevel::Info,
                    "public_routing_connection_closed",
                    &[("peer", &peer_id.to_string())],
                );
            }
            record_path_closed(
                context.paths,
                context.forwarder,
                context.metrics,
                peer_id,
                connection_id,
                &endpoint,
            );
            redial_configured_peer_after_supported_path_loss(swarm, &mut context, peer_id);
            invalidate_peer_capabilities_when_disconnected(
                context.forwarder,
                context.peer_capabilities,
                Some(context.packet_plane),
                context.packet_plane_quic.as_deref(),
                peer_id,
                num_established,
            );
            if num_established == 0 {
                context.inbound_packet_rate_limiters.remove(peer_id);
                context.pairing_request_rate_limiters.remove(peer_id);
                context.membership_page_rate_limiters.remove(peer_id);
                context.membership_record_syncs.remove_peer(peer_id);
                let overlay_peer = PeerId::from_libp2p(peer_id);
                if !has_active_packet_plane_session(
                    Some(context.packet_plane),
                    context.packet_plane_quic.as_deref(),
                    overlay_peer,
                ) {
                    context.packet_plane_negotiator.remove_peer(overlay_peer);
                }
                if context.forwarder.is_configured_transport_peer(peer_id)
                    && should_query_configured_peer_recovery_discovery(context.discovery)
                    && peer_lacks_supported_packet_path(
                        context.paths,
                        context.peer_capabilities,
                        Some(context.packet_plane),
                        context.packet_plane_quic.as_deref(),
                        peer_id,
                    )
                {
                    query_configured_peer_recovery_discovery_for_peer(
                        swarm,
                        &context.local_capabilities.network_name,
                        context.local_capabilities.membership_tag.as_deref(),
                        peer_id,
                        context.discovered_peer_addresses,
                        context.metrics,
                        "connection_closed",
                    );
                }
                if context
                    .relay_readiness
                    .record_relay_reservation_lost(peer_id)
                {
                    context
                        .auto_relay
                        .release_reservation_for_retry_after(peer_id, Instant::now());
                    context.metrics.record_relay_reservation_lost();
                    log_runtime_event(
                        LogLevel::Warn,
                        "relay_reservation_readiness_lost",
                        &[("relay", &peer_id.to_string())],
                    );
                }
            }
            log_runtime_event(
                LogLevel::Info,
                "connection_closed",
                &[
                    ("peer", &peer_id.to_string()),
                    ("connection_id", &connection_id.to_string()),
                    ("relayed", &endpoint.is_relayed().to_string()),
                    ("endpoint", &format!("{endpoint:?}")),
                ],
            );
        }
        SwarmEvent::OutgoingConnectionError { peer_id, error, .. } => {
            if let Some(delay) = context.public_discovery_backoff.record_outgoing_error(
                peer_id,
                &error,
                Instant::now(),
            ) {
                let delay_millis = delay.as_millis().to_string();
                log_runtime_event(
                    LogLevel::Warn,
                    "public_discovery_bootstrap_backoff",
                    &[("delay_millis", &delay_millis)],
                );
            }
            let peer_connected = peer_id.is_some_and(|peer_id| swarm.is_connected(&peer_id));
            if let Some(peer_id) = peer_id
                && context.forwarder.is_configured_transport_peer(peer_id)
            {
                if should_query_configured_peer_recovery_discovery(context.discovery)
                    && peer_lacks_supported_packet_path(
                        context.paths,
                        context.peer_capabilities,
                        Some(context.packet_plane),
                        context.packet_plane_quic.as_deref(),
                        peer_id,
                    )
                {
                    query_configured_peer_recovery_discovery_for_peer(
                        swarm,
                        &context.local_capabilities.network_name,
                        context.local_capabilities.membership_tag.as_deref(),
                        peer_id,
                        context.discovered_peer_addresses,
                        context.metrics,
                        "outgoing_connection_error",
                    );
                }
            }
            record_discovered_outgoing_connection_failure(
                context.discovered_peer_addresses,
                context.metrics,
                peer_id,
                &error,
            );
            handle_relay_infrastructure_outgoing_connection_error(
                context.infrastructure_peers,
                context.auto_relay,
                context.membership,
                context.metrics,
                peer_id,
                peer_connected,
                &error,
            );
        }
        SwarmEvent::NewExternalAddrCandidate { address } => {
            context.metrics.record_external_address_candidate();
            log_runtime_event(
                LogLevel::Info,
                "external_address_candidate",
                &[("address", &address.to_string())],
            );
        }
        SwarmEvent::ExternalAddrConfirmed { address } => {
            context.metrics.record_external_address_confirmed();
            let packet_plane_quic_snapshot = context
                .packet_plane_quic
                .as_deref()
                .map(PacketPlaneQuicRuntime::snapshot);
            let observed_endpoint_update = update_observed_packet_plane_endpoints(
                context.local_capabilities,
                &address,
                context.packet_plane.primary_listener(),
                packet_plane_quic_snapshot
                    .as_ref()
                    .and_then(|snapshot| snapshot.listener),
                packet_plane_quic_snapshot.and_then(|snapshot| snapshot.certificate_der),
                &context
                    .forwarder
                    .local_advertised_route_prefixes()
                    .collect::<Vec<_>>(),
            );
            if observed_endpoint_update.public_address_accepted {
                context
                    .metrics
                    .record_observed_packet_plane_external_address();
            } else {
                context
                    .metrics
                    .record_observed_packet_plane_external_address_rejected();
            }
            if observed_endpoint_update.udp_candidate_added {
                context
                    .metrics
                    .record_observed_packet_plane_udp_endpoint_candidate();
            }
            if observed_endpoint_update.quic_candidate_added {
                context
                    .metrics
                    .record_observed_packet_plane_quic_endpoint_candidate();
            }
            if observed_endpoint_update.changed() {
                log_runtime_event(
                    LogLevel::Info,
                    "observed_packet_plane_endpoints_advertised",
                    &[
                        ("address", &address.to_string()),
                        (
                            "udp_candidates",
                            &context
                                .local_capabilities
                                .packet_endpoint_candidates
                                .len()
                                .to_string(),
                        ),
                        (
                            "quic_candidates",
                            &context
                                .local_capabilities
                                .owned_quic_packet_endpoint_candidates
                                .len()
                                .to_string(),
                        ),
                    ],
                );
                send_control_capabilities_to_connected_peers(
                    swarm,
                    context.forwarder,
                    context.local_capabilities,
                    context.metrics,
                );
            }
            log_runtime_event(
                LogLevel::Info,
                "external_address_confirmed",
                &[("address", &address.to_string())],
            );
        }
        SwarmEvent::ExternalAddrExpired { address } => {
            context.metrics.record_external_address_expired();
            log_runtime_event(
                LogLevel::Info,
                "external_address_expired",
                &[("address", &address.to_string())],
            );
        }
        SwarmEvent::NewListenAddr { address, .. } => {
            let mut publish_peer_address_record = kademlia_peer_address_is_advertisable(&address);
            if let Some(relay) = relayed_address_relay_peer(&address) {
                if let Some(relay_base_address) =
                    relay_base_address_from_relayed_listen_address(&address)
                {
                    context
                        .relay_readiness
                        .record_relay_listen_address(relay, relay_base_address);
                }
                dial_relay_ready_configured_peers(
                    swarm,
                    context.forwarder,
                    context.relay_readiness,
                    context.relay_addresses,
                    context.configured_peer_addresses,
                    context.discovered_peer_addresses,
                    context.paths,
                    context.metrics,
                    relay,
                );
                log_runtime_event(
                    LogLevel::Info,
                    "relay_listen_address_ready",
                    &[
                        ("relay", &relay.to_string()),
                        ("address", &address.to_string()),
                    ],
                );
                publish_peer_address_record = true;
            }
            if publish_peer_address_record {
                publish_kademlia_peer_address_record_for_capabilities(
                    swarm,
                    context.discovery,
                    context.local_capabilities,
                    context.identity,
                );
            }
        }
        SwarmEvent::ExpiredListenAddr { address, .. } => {
            if let Some(relay) = relayed_address_relay_peer(&address)
                && let Some(relay_base_address) =
                    relay_base_address_from_relayed_listen_address(&address)
                && context
                    .relay_readiness
                    .record_relay_listen_address_lost(relay, &relay_base_address)
            {
                context
                    .auto_relay
                    .release_reservation_for_retry_after(relay, Instant::now());
                context.metrics.record_relay_reservation_lost();
                log_runtime_event(
                    LogLevel::Warn,
                    "relay_listen_address_lost",
                    &[
                        ("relay", &relay.to_string()),
                        ("address", &address.to_string()),
                    ],
                );
                publish_kademlia_peer_address_record_for_capabilities(
                    swarm,
                    context.discovery,
                    context.local_capabilities,
                    context.identity,
                );
            }
        }
        SwarmEvent::ListenerClosed {
            listener_id,
            addresses,
            ..
        } => {
            for address in addresses {
                if let Some(relay) = relayed_address_relay_peer(&address)
                    && let Some(relay_base_address) =
                        relay_base_address_from_relayed_listen_address(&address)
                    && context
                        .relay_readiness
                        .record_relay_listen_address_lost(relay, &relay_base_address)
                {
                    context
                        .auto_relay
                        .release_reservation_for_retry_after(relay, Instant::now());
                    context.metrics.record_relay_reservation_lost();
                    log_runtime_event(
                        LogLevel::Warn,
                        "relay_listen_address_lost",
                        &[
                            ("relay", &relay.to_string()),
                            ("address", &address.to_string()),
                        ],
                    );
                    publish_kademlia_peer_address_record_for_capabilities(
                        swarm,
                        context.discovery,
                        context.local_capabilities,
                        context.identity,
                    );
                }
            }
            if record_auto_relay_listener_termination(
                context.auto_relay,
                context.relay_readiness,
                context.metrics,
                listener_id,
                Instant::now(),
                "auto_relay_reservation_listener_closed",
            )
            .is_some_and(|released| released.was_accepted)
            {
                publish_kademlia_peer_address_record_for_capabilities(
                    swarm,
                    context.discovery,
                    context.local_capabilities,
                    context.identity,
                );
            }
        }
        SwarmEvent::ListenerError { listener_id, error } => {
            if record_auto_relay_listener_termination(
                context.auto_relay,
                context.relay_readiness,
                context.metrics,
                listener_id,
                Instant::now(),
                "auto_relay_reservation_listener_error",
            )
            .is_some_and(|released| released.was_accepted)
            {
                publish_kademlia_peer_address_record_for_capabilities(
                    swarm,
                    context.discovery,
                    context.local_capabilities,
                    context.identity,
                );
            }
            swarm.remove_listener(listener_id);
            log_runtime_event(
                LogLevel::Warn,
                "listener_error",
                &[
                    ("listener", &listener_id.to_string()),
                    ("error", &error.to_string()),
                ],
            );
        }
        _ => {}
    }

    Ok(())
}

fn advertise_relay_server_listener_address(
    swarm: &mut Swarm<Behaviour>,
    relay_server_enabled: bool,
    endpoint: &ConnectedPoint,
) {
    if !relay_server_enabled {
        return;
    }
    let ConnectedPoint::Listener { local_addr, .. } = endpoint else {
        return;
    };
    if !direct_address_is_specific(local_addr) {
        return;
    }
    swarm.add_external_address(local_addr.clone());
    log_runtime_event(
        LogLevel::Info,
        "relay_server_external_address_advertised",
        &[("address", &local_addr.to_string())],
    );
}

fn direct_address_is_specific(address: &Multiaddr) -> bool {
    address.iter().all(|protocol| match protocol {
        Protocol::Ip4(address) => !address.is_unspecified(),
        Protocol::Ip6(address) => !address.is_unspecified(),
        _ => true,
    })
}

fn redial_configured_peer_after_supported_path_loss(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    peer: Libp2pPeerId,
) {
    if !context.forwarder.is_configured_transport_peer(peer)
        || !peer_lacks_supported_packet_path(
            context.paths,
            context.peer_capabilities,
            Some(context.packet_plane),
            context.packet_plane_quic.as_deref(),
            peer,
        )
    {
        return;
    }

    let mut selected_peers = HashSet::new();
    selected_peers.insert(peer);
    let discovered_addresses = context
        .discovered_peer_addresses
        .redial_candidates_at(Instant::now());
    redial_selected_addresses(
        swarm,
        &selected_peers,
        &[],
        &[],
        context.configured_peer_addresses,
        &discovered_addresses,
        context.discovered_peer_addresses,
        context.paths,
        context.metrics,
    );
    dial_ready_relays_for_configured_peer(swarm, context, peer);
}

fn peer_lacks_supported_packet_path(
    paths: &PathSet,
    peer_capabilities: &PeerCapabilities,
    packet_plane: Option<&PacketPlaneRuntime>,
    packet_plane_quic: Option<&PacketPlaneQuicRuntime>,
    peer: Libp2pPeerId,
) -> bool {
    let overlay_peer = PeerId::from_libp2p(peer);
    let datagram_backend = local_packet_datagram_backend(
        peer_capabilities,
        packet_plane,
        packet_plane_quic,
        overlay_peer,
    );
    let support =
        packet_transport_support_for_backend(peer_capabilities, overlay_peer, datagram_backend);
    !paths.has_supported_path(overlay_peer, support)
}

fn dial_ready_relays_for_configured_peer(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    peer: Libp2pPeerId,
) {
    if !context.forwarder.is_configured_transport_peer(peer)
        || !peer_lacks_supported_packet_path(
            context.paths,
            context.peer_capabilities,
            Some(context.packet_plane),
            context.packet_plane_quic.as_deref(),
            peer,
        )
    {
        return;
    }

    for relay in context.relay_readiness.ready_relays() {
        dial_relay_ready_configured_peers(
            swarm,
            context.forwarder,
            context.relay_readiness,
            context.relay_addresses,
            context.configured_peer_addresses,
            context.discovered_peer_addresses,
            context.paths,
            context.metrics,
            relay,
        );
    }
}

fn handle_outgoing_connection_error(
    metrics: &RuntimeMetrics,
    peer_id: Option<Libp2pPeerId>,
    error: &impl std::fmt::Display,
) {
    metrics.record_outgoing_connection_error();
    match peer_id {
        Some(peer_id) => eprintln!("outgoing connection to {peer_id} failed: {error}"),
        None => eprintln!("outgoing connection failed: {error}"),
    }
}

fn handle_relay_infrastructure_outgoing_connection_error(
    infrastructure_peers: &mut InfrastructurePeers,
    auto_relay: &mut AutoRelayState,
    membership: &OverlayMembership,
    metrics: &RuntimeMetrics,
    peer_id: Option<Libp2pPeerId>,
    peer_connected: bool,
    error: &impl std::fmt::Display,
) {
    handle_outgoing_connection_error(metrics, peer_id, error);
    let Some(peer_id) = peer_id else {
        return;
    };
    if peer_connected || membership.allows(peer_id) || !infrastructure_peers.remove(peer_id) {
        return;
    }
    auto_relay.remove_candidate(peer_id);

    metrics.record_auto_relay_infrastructure_dial_failure();
    log_runtime_event(
        LogLevel::Warn,
        "auto_relay_infrastructure_dial_failed_async",
        &[
            ("peer", &peer_id.to_string()),
            ("error", &error.to_string()),
        ],
    );
}

async fn handle_control_event(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    event: request_response::Event<ControlRequest, ControlResponse>,
) -> Result<(), RunnerError> {
    match event {
        request_response::Event::Message {
            peer,
            connection_id,
            message: Message::Request {
                request, channel, ..
            },
            ..
        } => {
            handle_control_request(swarm, context, peer, connection_id, request, channel).await?;
        }
        request_response::Event::Message {
            peer,
            message:
                Message::Response {
                    request_id,
                    response,
                },
            ..
        } => {
            let validation_scope = MembershipValidationScope::from_capabilities(
                context.local_capabilities,
                context.previous_membership_tags,
            );
            let membership_changed = if context.membership_record_syncs.contains(request_id)
                || matches!(
                    &response,
                    ControlResponse::MembershipRecordsPage(_)
                        | ControlResponse::MembershipRecordsRejected(_)
                ) {
                context.metrics.record_control_response_received();
                handle_membership_record_sync_response(
                    swarm,
                    context.forwarder,
                    context.membership,
                    context.membership_record_syncs,
                    context.metrics,
                    peer,
                    request_id,
                    response,
                    validation_scope,
                )
            } else {
                handle_control_response_event(
                    swarm,
                    context.forwarder,
                    context.membership,
                    context.peer_capabilities,
                    context.discovered_peer_addresses,
                    context.metrics,
                    peer,
                    response,
                    validation_scope,
                    context.local_capabilities,
                    context.packet_plane,
                    context.packet_plane_quic.as_deref_mut(),
                    context.packet_plane_negotiator,
                    context.path_probe_tracker,
                    context.identity,
                    context.paths,
                    context.discovery,
                )
            };
            if membership_changed {
                *context.local_capabilities =
                    refreshed_local_capabilities(context.local_capabilities, context.forwarder);
                sync_live_tun_routes(context.forwarder, context.tun_runtime)?;
                send_control_capabilities_to_connected_peers(
                    swarm,
                    context.forwarder,
                    context.local_capabilities,
                    context.metrics,
                );
            }
            if let Some(remote_capabilities) = context
                .peer_capabilities
                .get(PeerId::from_libp2p(peer))
                .cloned()
            {
                maybe_start_membership_record_sync(
                    swarm,
                    context.forwarder,
                    context.local_capabilities,
                    context.membership_record_syncs,
                    context.metrics,
                    peer,
                    &remote_capabilities,
                );
            }
        }
        request_response::Event::OutboundFailure {
            peer,
            request_id,
            error,
            ..
        } => {
            let membership_sync_failed = context.membership_record_syncs.contains(request_id);
            if membership_sync_failed {
                context.membership_record_syncs.take(request_id);
                fail_membership_record_sync(
                    context.membership_record_syncs,
                    context.metrics,
                    peer,
                    "transport_failure",
                );
            }
            if !membership_sync_failed {
                context.metrics.record_control_failure();
            }
            eprintln!("control request to {peer} failed: {error}");
        }
        request_response::Event::InboundFailure { peer, error, .. } => {
            context.metrics.record_control_failure();
            eprintln!("control request from {peer} failed: {error}");
        }
        request_response::Event::ResponseSent { .. } => {}
    }

    Ok(())
}

fn handle_packet_event(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    event: request_response::Event<crate::wire::Frame, crate::runtime::packet::PacketResponse>,
) -> Result<(), RunnerError> {
    match event {
        request_response::Event::Message {
            peer,
            message: Message::Request {
                request, channel, ..
            },
            ..
        } => handle_packet_request(
            swarm,
            context,
            peer,
            &request,
            PacketResponseTarget::RequestResponse(channel),
        )?,
        request_response::Event::Message {
            peer,
            message:
                Message::Response {
                    request_id,
                    response,
                },
            ..
        } => {
            let in_flight = context
                .packet_in_flight
                .complete(PacketInFlightId::RequestResponse(request_id));
            handle_packet_response(context, in_flight, Some(peer), response);
        }
        request_response::Event::OutboundFailure {
            peer,
            request_id,
            error,
            ..
        } => {
            let in_flight = context
                .packet_in_flight
                .complete(PacketInFlightId::RequestResponse(request_id));
            context.metrics.record_outbound_failure();
            if let Some(request) = in_flight {
                let demoted = maybe_demote_stream_fallback_path(
                    context.paths,
                    context.metrics,
                    request.peer,
                    request.path,
                    &error,
                );
                if let Some(peer) = context.forwarder.transport_peer_for_overlay(request.peer) {
                    if demoted {
                        dial_ready_relays_for_configured_peer(swarm, context, peer);
                    }
                    redial_packet_plane_recovery_addresses(
                        swarm,
                        peer,
                        context.configured_peer_addresses,
                        context.relay_addresses,
                        context.discovered_peer_addresses,
                        context.metrics,
                    );
                }
            }
            eprintln!("packet request to {peer} failed: {error}");
        }
        request_response::Event::InboundFailure { peer, error, .. } => {
            context.metrics.record_inbound_failure();
            eprintln!("packet request from {peer} failed: {error}");
        }
        request_response::Event::ResponseSent { .. } => {}
    }

    Ok(())
}

fn handle_pinned_packet_stream_event(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    event: pinned_packet_stream::Event,
) -> Result<(), RunnerError> {
    match event {
        pinned_packet_stream::Event::InboundRequest {
            peer,
            connection_id,
            request_id,
            frame,
        } => handle_packet_request(
            swarm,
            context,
            peer,
            &frame,
            PacketResponseTarget::Pinned(pinned_packet_stream::Behaviour::response_channel(
                peer,
                connection_id,
                request_id,
            )),
        )?,
        pinned_packet_stream::Event::OutboundResponse {
            request_id,
            response,
            ..
        } => {
            let in_flight = context
                .packet_in_flight
                .complete(PacketInFlightId::PinnedPacketStream(request_id));
            handle_packet_response(context, in_flight, None, response);
        }
        pinned_packet_stream::Event::OutboundFailure {
            peer,
            connection_id,
            request_id,
            error,
        } => {
            let in_flight = context
                .packet_in_flight
                .complete(PacketInFlightId::PinnedPacketStream(request_id));
            context.metrics.record_outbound_failure();
            if let Some(request) = in_flight {
                let demoted = maybe_demote_pinned_stream_fallback_path(
                    context.paths,
                    context.metrics,
                    request.peer,
                    request.path,
                    request.relay_peer,
                    connection_id,
                    &error,
                );
                if let Some(peer) = context.forwarder.transport_peer_for_overlay(request.peer) {
                    if demoted {
                        dial_ready_relays_for_configured_peer(swarm, context, peer);
                    }
                    redial_packet_plane_recovery_addresses(
                        swarm,
                        peer,
                        context.configured_peer_addresses,
                        context.relay_addresses,
                        context.discovered_peer_addresses,
                        context.metrics,
                    );
                }
            }
            eprintln!("pinned packet stream request to {peer} failed: {error:?}");
        }
        pinned_packet_stream::Event::InboundFailure { peer, error, .. } => {
            context.metrics.record_inbound_failure();
            eprintln!("pinned packet stream request from {peer} failed: {error:?}");
        }
        pinned_packet_stream::Event::ResponseSent { .. } => {}
    }

    Ok(())
}

fn handle_packet_response(
    context: &mut SwarmEventContext<'_>,
    in_flight: Option<PacketInFlightRequest>,
    transport_peer: Option<Libp2pPeerId>,
    response: PacketResponse,
) {
    match response {
        PacketResponse::Accepted => {
            if let Some(request) = in_flight {
                let rtt_ms = request
                    .sent_at
                    .elapsed()
                    .as_millis()
                    .min(u128::from(u16::MAX)) as u16;
                let change = context.paths.record_rtt_for_relay(
                    request.peer,
                    request.path,
                    request.relay_peer,
                    rtt_ms,
                );
                record_path_selection_change(context.metrics, change);
            }
        }
        PacketResponse::Rejected(reason) => {
            context.metrics.record_outbound_failure();
            context
                .metrics
                .record_outbound_drop(packet_rejection_drop_reason(reason));
            if let Some(peer) = transport_peer.or_else(|| {
                in_flight
                    .and_then(|request| context.forwarder.transport_peer_for_overlay(request.peer))
            }) {
                audit_packet_response_rejection(peer, reason);
            }
        }
    }
}

enum PacketResponseTarget {
    RequestResponse(request_response::ResponseChannel<PacketResponse>),
    Pinned(pinned_packet_stream::ResponseChannel),
}

fn handle_packet_request(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    peer: Libp2pPeerId,
    request: &crate::wire::Frame,
    channel: PacketResponseTarget,
) -> Result<(), RunnerError> {
    if !context
        .inbound_packet_rate_limiters
        .allow(peer, Instant::now())
    {
        context
            .metrics
            .record_inbound_drop(PacketDropReason::RateLimited);
        audit_packet_rate_limit_rejection(
            peer,
            request,
            context.inbound_packet_rate_limiters.limit_per_second(),
        );
        send_packet_response_nonfatal(
            swarm,
            context.metrics,
            peer,
            channel,
            PacketResponse::Rejected(PacketRejectionReason::RateLimited),
        );
        return Ok(());
    }

    let result = match request.header.payload_type {
        PayloadType::IpPacket => match context
            .forwarder
            .accept_inbound_stream_packet(peer, request)
        {
            Ok(packet) => {
                context.writer.write_packet(packet)?;
                context.metrics.record_tun_write(packet.len());
                context.metrics.record_inbound_accepted();
                Ok(())
            }
            Err(error) => Err(error),
        },
        PayloadType::Keepalive => context
            .forwarder
            .accept_inbound_control_frame(peer, request, PayloadType::Keepalive)
            .map(|()| context.metrics.record_inbound_keepalive_accepted()),
        PayloadType::PathProbe => context
            .forwarder
            .accept_inbound_control_frame(peer, request, PayloadType::PathProbe)
            .map(|()| context.metrics.record_inbound_path_probe_accepted()),
    };

    match result {
        Ok(()) => {
            send_packet_response_nonfatal(
                swarm,
                context.metrics,
                peer,
                channel,
                PacketResponse::Accepted,
            );
            Ok(())
        }
        Err(error) => {
            let drop_reason = inbound_drop_reason(&error);
            context.metrics.record_inbound_drop(drop_reason);
            audit_packet_request_rejection(peer, request, &error);
            send_packet_response_nonfatal(
                swarm,
                context.metrics,
                peer,
                channel,
                PacketResponse::Rejected(packet_rejection_reason(drop_reason)),
            );
            Ok(())
        }
    }
}

fn send_packet_response_nonfatal(
    swarm: &mut Swarm<Behaviour>,
    metrics: &RuntimeMetrics,
    peer: Libp2pPeerId,
    channel: PacketResponseTarget,
    response: PacketResponse,
) {
    match channel {
        PacketResponseTarget::RequestResponse(channel) => {
            if let Err(response) = Forwarder::send_packet_response(swarm, channel, response) {
                metrics.record_inbound_failure();
                log_runtime_event(
                    LogLevel::Warn,
                    "packet_response_dropped",
                    &[
                        ("peer", &peer.to_string()),
                        ("response", packet_response_name(&response)),
                    ],
                );
            }
        }
        PacketResponseTarget::Pinned(channel) => {
            swarm
                .behaviour_mut()
                .pinned_packet_stream
                .send_response(channel, response);
        }
    }
}

fn packet_response_name(response: &PacketResponse) -> &'static str {
    match response {
        PacketResponse::Accepted => "accepted",
        PacketResponse::Rejected(reason) => packet_rejection_reason_name(*reason),
    }
}

fn packet_rejection_reason_name(reason: PacketRejectionReason) -> &'static str {
    match reason {
        PacketRejectionReason::MalformedPacket => "malformed_packet",
        PacketRejectionReason::PacketTooLarge => "packet_too_large",
        PacketRejectionReason::Replay => "replay",
        PacketRejectionReason::UnauthorizedPeer => "unauthorized_peer",
        PacketRejectionReason::UnauthorizedSource => "unauthorized_source",
        PacketRejectionReason::UnauthorizedDestination => "unauthorized_destination",
        PacketRejectionReason::UnexpectedPayload => "unexpected_payload",
        PacketRejectionReason::RateLimited => "rate_limited",
    }
}

struct PacketPlaneInboundContext<'a> {
    forwarder: &'a mut Forwarder,
    writer: &'a mut TunWriter,
    paths: &'a mut PathSet,
    peer_capabilities: &'a PeerCapabilities,
    inbound_packet_rate_limiters: &'a mut PeerRateLimiters,
    packet_plane: Option<&'a PacketPlaneRuntime>,
    packet_plane_quic: Option<&'a PacketPlaneQuicRuntime>,
    backend: PacketDatagramBackend,
    path_probe_tracker: &'a mut PathProbeTracker,
    metrics: &'a RuntimeMetrics,
}

async fn handle_packet_plane_received(
    context: &mut PacketPlaneInboundContext<'_>,
    received: &PacketPlaneReceivedFrame,
) -> Result<(), RunnerError> {
    let Some(overlay_peer) = received.peer else {
        context
            .metrics
            .record_inbound_drop(PacketDropReason::UnauthorizedPeer);
        log_runtime_event(
            LogLevel::Warn,
            "packet_plane_rejected",
            &[("reason", "missing_peer")],
        );
        return Ok(());
    };
    let Some(transport_peer) = context.forwarder.transport_peer_for_overlay(overlay_peer) else {
        context
            .metrics
            .record_inbound_drop(PacketDropReason::UnauthorizedPeer);
        log_runtime_event(
            LogLevel::Warn,
            "packet_plane_rejected",
            &[
                ("peer", &overlay_peer.to_string()),
                ("reason", "unknown_overlay_peer"),
            ],
        );
        return Ok(());
    };
    if !context
        .inbound_packet_rate_limiters
        .allow(transport_peer, Instant::now())
    {
        context
            .metrics
            .record_inbound_drop(PacketDropReason::RateLimited);
        audit_packet_rate_limit_rejection(
            transport_peer,
            &received.frame,
            context.inbound_packet_rate_limiters.limit_per_second(),
        );
        return Ok(());
    }

    let result = match received.frame.header.payload_type {
        PayloadType::IpPacket => match context
            .forwarder
            .accept_inbound_stream_packet(transport_peer, &received.frame)
        {
            Ok(packet) => {
                context.writer.write_packet(packet)?;
                context.metrics.record_tun_write(packet.len());
                context.metrics.record_inbound_accepted();
                Ok(())
            }
            Err(error) => Err(error),
        },
        PayloadType::Keepalive => context
            .forwarder
            .accept_inbound_control_frame(transport_peer, &received.frame, PayloadType::Keepalive)
            .map(|()| context.metrics.record_inbound_keepalive_accepted()),
        PayloadType::PathProbe => context
            .forwarder
            .validate_inbound_packet_plane_control_frame(
                transport_peer,
                &received.frame,
                PayloadType::PathProbe,
            )
            .map(|()| context.metrics.record_inbound_path_probe_accepted()),
    };

    if let Err(error) = result {
        let drop_reason = inbound_drop_reason(&error);
        context.metrics.record_inbound_drop(drop_reason);
        audit_packet_request_rejection(transport_peer, &received.frame, &error);
    } else {
        if packet_plane_payload_refreshes_path(received.frame.header.payload_type) {
            refresh_packet_plane_path(
                context.paths,
                context.metrics,
                overlay_peer,
                context.backend,
                received.frame.header.payload_type,
            );
        }
        if received.frame.header.payload_type == PayloadType::PathProbe {
            handle_packet_plane_path_probe(
                context.forwarder,
                context.paths,
                context.peer_capabilities,
                context.packet_plane,
                context.packet_plane_quic,
                context.backend,
                context.path_probe_tracker,
                context.metrics,
                overlay_peer,
                received,
            )
            .await;
        }
    }
    Ok(())
}

const fn packet_plane_payload_refreshes_path(payload_type: PayloadType) -> bool {
    !matches!(payload_type, PayloadType::PathProbe)
}

fn refresh_packet_plane_path(
    paths: &mut PathSet,
    metrics: &RuntimeMetrics,
    peer: PeerId,
    backend: PacketDatagramBackend,
    payload_type: PayloadType,
) {
    let path = packet_datagram_backend_path_kind(backend);
    let previous = paths
        .candidates_for(peer)
        .find(|candidate| candidate.kind == path);
    if previous.is_some_and(|candidate| candidate.healthy && candidate.established_connections > 0)
    {
        return;
    }

    let change = paths.record_established(peer, path);
    record_path_selection_change(metrics, change);
    log_runtime_event(
        LogLevel::Info,
        "packet_plane_path_refreshed",
        &[
            ("peer", &peer.to_string()),
            ("path", path.wire_name()),
            ("payload", payload_type_name(payload_type)),
        ],
    );
}

#[allow(clippy::too_many_arguments)]
async fn handle_packet_plane_path_probe(
    forwarder: &mut Forwarder,
    paths: &mut PathSet,
    peer_capabilities: &PeerCapabilities,
    packet_plane: Option<&PacketPlaneRuntime>,
    packet_plane_quic: Option<&PacketPlaneQuicRuntime>,
    backend: PacketDatagramBackend,
    path_probe_tracker: &mut PathProbeTracker,
    metrics: &RuntimeMetrics,
    overlay_peer: PeerId,
    received: &PacketPlaneReceivedFrame,
) {
    if let Some(confirmed_mtu) = path_probe_ack_mtu(&received.frame.payload) {
        if let Some(token) = path_probe_ack_token(&received.frame.payload)
            && let Some((path, rtt_ms)) =
                path_probe_tracker.confirm(overlay_peer, token, Instant::now())
        {
            let change = paths.record_rtt(overlay_peer, path, rtt_ms);
            record_path_selection_change(metrics, change);
            log_runtime_event(
                LogLevel::Info,
                "path_probe_rtt_confirmed",
                &[
                    ("peer", &overlay_peer.to_string()),
                    ("path", path.wire_name()),
                    ("rtt_ms", &rtt_ms.to_string()),
                ],
            );
        }
        maybe_confirm_path_mtu_probe(
            paths,
            peer_capabilities,
            packet_plane,
            packet_plane_quic,
            backend,
            metrics,
            overlay_peer,
            confirmed_mtu,
            u16::try_from(forwarder.mtu()).unwrap_or(u16::MAX),
        );
        return;
    }

    let Some(probed_mtu) = path_probe_request_mtu(&received.frame.payload) else {
        return;
    };
    let ack_payload = path_probe_ack_payload(
        probed_mtu,
        path_probe_request_token(&received.frame.payload),
    );
    let peer_mtu = selected_path_mtu(
        paths,
        peer_capabilities,
        packet_plane,
        packet_plane_quic,
        overlay_peer,
        u16::try_from(forwarder.mtu()).unwrap_or(u16::MAX),
    );
    match forwarder.path_probe_frame_with_mtu(peer_mtu, &ack_payload) {
        Ok(frame) => {
            if let Err(error) = send_packet_plane_frame(
                packet_plane,
                packet_plane_quic,
                backend,
                overlay_peer,
                &frame,
            )
            .await
            {
                metrics.record_outbound_path_probe_failure();
                eprintln!("packet-plane path probe ack to {overlay_peer} failed: {error:?}");
            } else {
                metrics.record_outbound_path_probe_ack_sent();
            }
        }
        Err(error) => {
            metrics.record_outbound_path_probe_failure();
            eprintln!("packet-plane path probe ack to {overlay_peer} failed: {error:?}");
        }
    }
}

fn handle_packet_plane_receive_error(metrics: &RuntimeMetrics, error: &PacketPlaneIoError) {
    if let PacketPlaneIoError::Io(error) = error {
        metrics.record_inbound_failure();
        log_runtime_event(
            LogLevel::Warn,
            "packet_plane_receive_failed",
            &[("error", &format!("{error:?}"))],
        );
    } else {
        metrics.record_inbound_drop(packet_plane_inbound_drop_reason(error));
        metrics.record_packet_plane_inbound_drop(packet_plane_inbound_metric_reason(error));
        log_runtime_event(
            LogLevel::Warn,
            "packet_plane_rejected",
            &[("reason", packet_plane_io_error_name(error))],
        );
    }
}

fn handle_packet_plane_quic_receive_error(
    paths: &mut PathSet,
    metrics: &RuntimeMetrics,
    error: &PacketPlaneQuicError,
) {
    maybe_demote_packet_plane_quic_receive_path(paths, metrics, error);

    match error {
        PacketPlaneQuicError::Io(_)
        | PacketPlaneQuicError::Connection(_)
        | PacketPlaneQuicError::PeerConnection { .. }
        | PacketPlaneQuicError::EndpointClosed => {
            metrics.record_inbound_failure();
            log_runtime_event(
                LogLevel::Warn,
                "packet_plane_quic_receive_failed",
                &[("reason", packet_plane_quic_error_name(error))],
            );
        }
        PacketPlaneQuicError::Datagram(error) => {
            metrics.record_inbound_drop(packet_plane_datagram_inbound_drop_reason(error));
            metrics.record_packet_plane_inbound_drop(packet_plane_datagram_metric_reason(error));
            log_runtime_event(
                LogLevel::Warn,
                "packet_plane_quic_rejected",
                &[("reason", packet_plane_datagram_error_name(error))],
            );
        }
        PacketPlaneQuicError::NoConnection { .. } | PacketPlaneQuicError::NoSessions => {
            metrics.record_inbound_drop(PacketDropReason::UnauthorizedPeer);
            log_runtime_event(
                LogLevel::Warn,
                "packet_plane_quic_rejected",
                &[("reason", packet_plane_quic_error_name(error))],
            );
        }
        PacketPlaneQuicError::Connect(_)
        | PacketPlaneQuicError::Certificate(_)
        | PacketPlaneQuicError::Rustls(_)
        | PacketPlaneQuicError::ClientVerifier(_)
        | PacketPlaneQuicError::SendDatagram(_)
        | PacketPlaneQuicError::Session(_) => {
            metrics.record_inbound_drop(PacketDropReason::MalformedPacket);
            log_runtime_event(
                LogLevel::Warn,
                "packet_plane_quic_rejected",
                &[("reason", packet_plane_quic_error_name(error))],
            );
        }
    }
}

fn handle_service_event(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    event: request_response::Event<ServiceRequest, ServiceResponse>,
) -> Result<(), RunnerError> {
    match event {
        request_response::Event::Message {
            peer,
            message: Message::Request {
                request, channel, ..
            },
            ..
        } => {
            handle_service_request(swarm, context, peer, request, channel)?;
        }
        request_response::Event::Message {
            peer,
            message: Message::Response { response, .. },
            ..
        } => {
            handle_service_response(
                context.metrics,
                peer,
                response,
                &context.local_capabilities.network_name,
                context.local_capabilities.membership_tag.as_deref(),
                context.previous_membership_tags,
            );
        }
        request_response::Event::OutboundFailure { peer, error, .. } => {
            context.metrics.record_service_failure();
            eprintln!("service request to {peer} failed: {error}");
        }
        request_response::Event::InboundFailure { peer, error, .. } => {
            context.metrics.record_service_failure();
            eprintln!("service request from {peer} failed: {error}");
        }
        request_response::Event::ResponseSent { .. } => {}
    }

    Ok(())
}

async fn handle_control_request(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    peer: Libp2pPeerId,
    connection_id: ConnectionId,
    request: ControlRequest,
    channel: request_response::ResponseChannel<ControlResponse>,
) -> Result<(), RunnerError> {
    match request {
        ControlRequest::Capabilities(capabilities) => {
            context.metrics.record_control_request_received();
            eprintln!("control capabilities from {peer}: {capabilities:?}");
            let was_authorized = context.forwarder.is_configured_transport_peer(peer);
            let (response, membership_changed) =
                capability_response_for_peer_with_membership_records_result(
                    context.forwarder,
                    context.membership,
                    peer,
                    &capabilities,
                    context.local_capabilities,
                    context.previous_membership_tags,
                );
            if membership_changed {
                *context.local_capabilities =
                    refreshed_local_capabilities(context.local_capabilities, context.forwarder);
                sync_live_tun_routes(context.forwarder, context.tun_runtime)?;
                send_control_capabilities_to_connected_peers(
                    swarm,
                    context.forwarder,
                    context.local_capabilities,
                    context.metrics,
                );
            }
            match &response {
                ControlResponse::CapabilitiesAccepted(_) => {
                    if !was_authorized && context.forwarder.is_configured_transport_peer(peer) {
                        promote_authenticated_overlay_connection(
                            swarm,
                            context,
                            peer,
                            connection_id,
                            "membership_record_presented",
                        );
                    }
                    record_peer_capabilities(
                        context.forwarder,
                        context.peer_capabilities,
                        peer,
                        capabilities.clone(),
                    );
                    learn_peer_direct_address_candidates_from_capabilities(
                        swarm,
                        context.forwarder,
                        context.discovered_peer_addresses,
                        context.paths,
                        context.metrics,
                        peer,
                        &capabilities,
                        context.discovery,
                    );
                    context.metrics.record_control_capability_accept();
                    maybe_send_packet_plane_hello(
                        swarm,
                        context.forwarder,
                        context.paths,
                        context.packet_plane,
                        context.packet_plane_quic.as_deref(),
                        context.packet_plane_negotiator,
                        context.identity,
                        context.local_capabilities,
                        peer,
                        &capabilities,
                        context.metrics,
                    );
                    maybe_start_membership_record_sync(
                        swarm,
                        context.forwarder,
                        context.local_capabilities,
                        context.membership_record_syncs,
                        context.metrics,
                        peer,
                        &capabilities,
                    );
                }
                ControlResponse::CapabilitiesRejected(reason) => {
                    context.metrics.record_control_capability_rejection(*reason);
                    context.metrics.record_control_failure();
                    audit_control_capabilities_rejection(peer, *reason);
                }
                ControlResponse::PacketPlaneAccepted(_)
                | ControlResponse::PacketPlaneRejected(_)
                | ControlResponse::MembershipRecordsPage(_)
                | ControlResponse::MembershipRecordsRejected(_) => {}
            }
            let rejected_probe = rejected_control_probe_reason(&response, context.membership, peer);
            send_control_response_nonfatal(swarm, context.metrics, peer, channel, response);
            if let Some(reason) = rejected_probe {
                quarantine_rejected_control_probe(swarm, context, peer, connection_id, reason);
            }
        }
        ControlRequest::PacketPlaneHello(handshake) => {
            context.metrics.record_control_request_received();
            let response = packet_plane_accept_response_for_peer(
                PacketPlaneAcceptContext {
                    forwarder: context.forwarder,
                    peer_capabilities: context.peer_capabilities,
                    paths: context.paths,
                    metrics: context.metrics,
                    packet_plane: context.packet_plane,
                    packet_plane_quic: context.packet_plane_quic.as_deref_mut(),
                    identity: context.identity,
                    local_capabilities: context.local_capabilities,
                    path_probe_tracker: context.path_probe_tracker,
                },
                peer,
                &handshake,
            )
            .await;
            if matches!(response, ControlResponse::PacketPlaneRejected(_)) {
                context.metrics.record_control_failure();
            }
            send_control_response_nonfatal(swarm, context.metrics, peer, channel, response);
        }
        ControlRequest::MembershipRecords(request) => {
            context.metrics.record_control_request_received();
            context
                .metrics
                .record_membership_record_page_request_received();
            let response = if !context.forwarder.is_configured_transport_peer(peer) {
                Err(MembershipRecordsRejectionReason::UnauthorizedPeer)
            } else if !context
                .membership_page_rate_limiters
                .allow(peer, Instant::now())
            {
                Err(MembershipRecordsRejectionReason::RateLimited)
            } else {
                context
                    .local_capabilities
                    .membership_records_snapshot
                    .as_deref()
                    .ok_or(MembershipRecordsRejectionReason::InvalidSnapshot)
                    .and_then(|snapshot| {
                        build_membership_records_page_for_snapshot(
                            &request,
                            context.forwarder.member_records(),
                            snapshot,
                            &context.local_capabilities.network_name,
                            context.local_capabilities.membership_tag.as_deref(),
                            context.previous_membership_tags,
                        )
                    })
            };
            match response {
                Ok(page) => {
                    context.metrics.record_membership_record_page_served();
                    send_control_response_nonfatal(
                        swarm,
                        context.metrics,
                        peer,
                        channel,
                        ControlResponse::MembershipRecordsPage(page),
                    );
                }
                Err(reason) => {
                    log_runtime_event(
                        LogLevel::Warn,
                        "membership_record_page_rejected",
                        &[
                            ("peer", &peer.to_string()),
                            ("reason", membership_record_rejection_name(reason)),
                        ],
                    );
                    send_control_response_nonfatal(
                        swarm,
                        context.metrics,
                        peer,
                        channel,
                        ControlResponse::MembershipRecordsRejected(reason),
                    );
                }
            }
        }
    }

    Ok(())
}

fn send_control_response_nonfatal(
    swarm: &mut Swarm<Behaviour>,
    metrics: &RuntimeMetrics,
    peer: Libp2pPeerId,
    channel: request_response::ResponseChannel<ControlResponse>,
    response: ControlResponse,
) {
    if let Err(response) = swarm
        .behaviour_mut()
        .control
        .send_response(channel, response)
    {
        metrics.record_control_failure();
        log_runtime_event(
            LogLevel::Warn,
            "control_response_dropped",
            &[
                ("peer", &peer.to_string()),
                ("response", control_response_name(&response)),
            ],
        );
    }
}

const fn control_response_name(response: &ControlResponse) -> &'static str {
    match response {
        ControlResponse::CapabilitiesAccepted(_) => "capabilities_accepted",
        ControlResponse::CapabilitiesRejected(_) => "capabilities_rejected",
        ControlResponse::PacketPlaneAccepted(_) => "packet_plane_accepted",
        ControlResponse::PacketPlaneRejected(_) => "packet_plane_rejected",
        ControlResponse::MembershipRecordsPage(_) => "membership_records_page",
        ControlResponse::MembershipRecordsRejected(_) => "membership_records_rejected",
    }
}

fn handle_service_request(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    peer: Libp2pPeerId,
    request: ServiceRequest,
    channel: request_response::ResponseChannel<ServiceResponse>,
) -> Result<(), RunnerError> {
    match request {
        ServiceRequest::Status(request) => {
            context.metrics.record_service_request_received();
            eprintln!("service status request from {peer}: {request:?}");
            let response = service_status_response_for_peer(
                context.forwarder,
                context.paths,
                context.peer_capabilities,
                peer,
                &request,
                context.local_capabilities,
                context.previous_membership_tags,
                context.packet_plane_session_ttl,
                context.packet_plane_replay_windows_per_session,
            );
            match &response {
                ServiceResponse::Status(_) => context.metrics.record_service_status_accept(),
                ServiceResponse::Rejected(reason) => {
                    context.metrics.record_service_status_rejection(*reason);
                    context.metrics.record_service_failure();
                    audit_service_status_rejection(peer, *reason);
                }
            }
            swarm
                .behaviour_mut()
                .service
                .send_response(channel, response)
                .map_err(|_| RunnerError::ServiceResponseDropped)?;
        }
    }

    Ok(())
}

fn handle_pairing_event(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    event: request_response::Event<PairingRequest, PairingResponse>,
) -> Result<(), RunnerError> {
    match event {
        request_response::Event::Message {
            peer,
            connection_id,
            message: Message::Request {
                request, channel, ..
            },
            ..
        } => {
            handle_pairing_request_event(swarm, context, peer, connection_id, &request, channel)?;
        }
        request_response::Event::Message {
            peer,
            message:
                Message::Response {
                    request_id,
                    response,
                },
            ..
        } => {
            context.metrics.record_pairing_response_received();
            log_runtime_event(
                LogLevel::Info,
                "pairing_response_received",
                &[
                    ("peer", &peer.to_string()),
                    ("request_id", &format!("{request_id:?}")),
                    ("inviter", &response.payload.inviter_peer),
                ],
            );
        }
        request_response::Event::OutboundFailure { peer, error, .. } => {
            context.metrics.record_pairing_outbound_failure();
            log_runtime_event(
                LogLevel::Warn,
                "pairing_outbound_failure",
                &[
                    ("peer", &peer.to_string()),
                    ("error", &format!("{error:?}")),
                ],
            );
        }
        request_response::Event::InboundFailure { peer, error, .. } => {
            context.metrics.record_pairing_inbound_failure();
            log_runtime_event(
                LogLevel::Warn,
                "pairing_inbound_failure",
                &[
                    ("peer", &peer.to_string()),
                    ("error", &format!("{error:?}")),
                ],
            );
        }
        request_response::Event::ResponseSent { .. } => {}
    }

    Ok(())
}

fn handle_pairing_code_event(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    event: request_response::Event<PairingCodeRequest, PairingCodeResponse>,
) -> Result<(), RunnerError> {
    match event {
        request_response::Event::Message {
            peer,
            connection_id,
            message: Message::Request {
                request, channel, ..
            },
        } => {
            let transport =
                pairing_transport_for_connection(context.active_connections, peer, connection_id);
            record_pairing_code_message_path(context.metrics, transport);
            handle_pairing_code_request(swarm, context, peer, transport, request, channel)?;
        }
        request_response::Event::Message {
            peer,
            connection_id,
            message:
                Message::Response {
                    request_id,
                    response,
                },
        } => {
            let transport =
                pairing_transport_for_connection(context.active_connections, peer, connection_id);
            record_pairing_code_message_path(context.metrics, transport);
            handle_pairing_code_response(swarm, context, peer, transport, request_id, response)?;
        }
        request_response::Event::OutboundFailure {
            peer,
            connection_id,
            request_id,
            error,
        } => {
            let transport =
                pairing_transport_for_connection(context.active_connections, peer, connection_id);
            context.metrics.record_code_pairing_transport_failure();
            if let Some(request) = context
                .code_pairing_sessions
                .take_outbound_request(request_id)
            {
                match request {
                    OutboundCodeRequest::Hello(hello) => {
                        context.code_pairing_sessions.release_peer_attempt(
                            &hello.operation_id,
                            hello.peer,
                            Instant::now(),
                        );
                    }
                    OutboundCodeRequest::Submit(pairing) => {
                        context
                            .code_pairing_sessions
                            .record_pending_submission_transport_failure(
                                &pairing.operation_id,
                                pairing.peer,
                                Instant::now(),
                            );
                    }
                    OutboundCodeRequest::Poll(pairing) => {
                        context
                            .code_pairing_sessions
                            .record_remote_poll_transport_failure(
                                &pairing.operation_id,
                                pairing.peer,
                                Instant::now(),
                            );
                    }
                }
            }
            log_runtime_event(
                LogLevel::Warn,
                "pairing_code_outbound_failure",
                &[
                    ("peer", &peer.to_string()),
                    ("transport", pairing_transport_label(transport)),
                    ("error", pairing_code_outbound_failure_name(&error)),
                ],
            );
        }
        request_response::Event::InboundFailure {
            peer,
            connection_id,
            error,
            ..
        } => {
            let transport =
                pairing_transport_for_connection(context.active_connections, peer, connection_id);
            context.metrics.record_code_pairing_transport_failure();
            log_runtime_event(
                LogLevel::Warn,
                "pairing_code_inbound_failure",
                &[
                    ("peer", &peer.to_string()),
                    ("transport", pairing_transport_label(transport)),
                    ("error", pairing_code_inbound_failure_name(&error)),
                ],
            );
        }
        request_response::Event::ResponseSent { .. } => {}
    }
    Ok(())
}

fn pairing_transport_for_connection(
    active_connections: &HashMap<(Libp2pPeerId, ConnectionId), ConnectedPoint>,
    peer: Libp2pPeerId,
    connection_id: ConnectionId,
) -> Option<PairingTransport> {
    active_connections
        .get(&(peer, connection_id))
        .map(|endpoint| {
            if endpoint.is_relayed() {
                PairingTransport::Relay
            } else {
                PairingTransport::Direct
            }
        })
}

fn record_pairing_code_message_path(metrics: &RuntimeMetrics, transport: Option<PairingTransport>) {
    if let Some(transport) = transport {
        metrics.record_code_pairing_message(transport == PairingTransport::Relay);
    }
}

const fn pairing_transport_label(transport: Option<PairingTransport>) -> &'static str {
    match transport {
        Some(PairingTransport::Direct) => "direct",
        Some(PairingTransport::Relay) => "relay",
        None => "unknown",
    }
}

const fn pairing_code_outbound_failure_name(
    error: &request_response::OutboundFailure,
) -> &'static str {
    match error {
        request_response::OutboundFailure::DialFailure => "dial_failure",
        request_response::OutboundFailure::Timeout => "timeout",
        request_response::OutboundFailure::ConnectionClosed => "connection_closed",
        request_response::OutboundFailure::UnsupportedProtocols => "unsupported_protocols",
        request_response::OutboundFailure::Io(_) => "io",
    }
}

const fn pairing_code_inbound_failure_name(
    error: &request_response::InboundFailure,
) -> &'static str {
    match error {
        request_response::InboundFailure::Timeout => "timeout",
        request_response::InboundFailure::ConnectionClosed => "connection_closed",
        request_response::InboundFailure::UnsupportedProtocols => "unsupported_protocols",
        request_response::InboundFailure::ResponseOmission => "response_omission",
        request_response::InboundFailure::Io(_) => "io",
    }
}

fn handle_pairing_code_request(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    peer: Libp2pPeerId,
    transport: Option<PairingTransport>,
    request: PairingCodeRequest,
    channel: request_response::ResponseChannel<PairingCodeResponse>,
) -> Result<(), RunnerError> {
    let now = Instant::now();
    if !context.pairing_request_rate_limiters.allow(peer, now) {
        context.metrics.record_code_pairing_rate_limited();
        return send_pairing_code_response(
            swarm,
            channel,
            PairingCodeResponse::Rejected {
                reason: PairingCodeRejectionReason::RateLimited,
            },
        );
    }
    if matches!(
        &request,
        PairingCodeRequest::Hello { .. } | PairingCodeRequest::Submit { .. }
    ) && !context.pairing_handshake_rate_limiter.allow(now)
    {
        context.metrics.record_code_pairing_rate_limited();
        log_runtime_event(
            LogLevel::Warn,
            "pairing_code_global_rate_limited",
            &[(
                "limit_per_second",
                &context
                    .pairing_handshake_rate_limiter
                    .limit_per_second()
                    .to_string(),
            )],
        );
        return send_pairing_code_response(
            swarm,
            channel,
            PairingCodeResponse::Rejected {
                reason: PairingCodeRejectionReason::RateLimited,
            },
        );
    }

    match request {
        PairingCodeRequest::Hello { hello } => {
            let Some((operation_id, code, expires_at_unix_seconds)) = context
                .code_pairing_sessions
                .active_open_code_for_locator(&hello.payload.locator)
                .map(|(operation_id, code, expires)| {
                    (operation_id.to_owned(), code.clone(), expires)
                })
            else {
                return send_pairing_code_unavailable(swarm, channel);
            };
            let now = current_unix_seconds_lossy();
            let expires_in_seconds = expires_at_unix_seconds.saturating_sub(now);
            if expires_in_seconds == 0 {
                return send_pairing_code_unavailable(swarm, channel);
            }
            if !context.code_pairing_sessions.can_accept_inbound_hello() {
                context.metrics.record_code_pairing_busy();
                return send_pairing_code_response(
                    swarm,
                    channel,
                    PairingCodeResponse::Rejected {
                        reason: PairingCodeRejectionReason::Busy,
                    },
                );
            }
            match answer_pairing_code_hello_at(
                context.forwarder.config(),
                &code,
                &hello,
                peer,
                crate::pairing::PairingOfferOptions {
                    expires_in_seconds,
                    rendezvous_token: None,
                },
                now,
            ) {
                Ok((challenge, session)) => {
                    if context
                        .code_pairing_sessions
                        .insert_inbound_session(
                            peer,
                            InboundSession {
                                operation_id: operation_id.clone(),
                                session,
                            },
                        )
                        .is_err()
                    {
                        context.metrics.record_code_pairing_busy();
                        return send_pairing_code_response(
                            swarm,
                            channel,
                            PairingCodeResponse::Rejected {
                                reason: PairingCodeRejectionReason::Busy,
                            },
                        );
                    }
                    context
                        .code_pairing_sessions
                        .record_open_handshake(&operation_id);
                    send_pairing_code_response(
                        swarm,
                        channel,
                        PairingCodeResponse::Challenge {
                            challenge: Box::new(challenge),
                        },
                    )
                }
                Err(_) => send_pairing_code_unavailable(swarm, channel),
            }
        }
        PairingCodeRequest::Submit { request } => {
            let now = current_unix_seconds_lossy();
            if let Some(response) = context
                .code_pairing_sessions
                .response_for_existing_submission(peer, &request, now)?
            {
                return send_pairing_code_response(swarm, channel, response);
            }
            if !context.code_pairing_sessions.can_accept_pending_approval() {
                context.metrics.record_code_pairing_busy();
                return send_pairing_code_response(
                    swarm,
                    channel,
                    PairingCodeResponse::Rejected {
                        reason: PairingCodeRejectionReason::Busy,
                    },
                );
            }
            let Some(inbound) = context
                .code_pairing_sessions
                .take_inbound_session(peer, &request.payload.rendezvous_token)
            else {
                return send_pairing_code_unavailable(swarm, channel);
            };
            let valid = verify_pairing_request_code_authentication(&request, &inbound.session)
                .and_then(|()| {
                    pairing_response_for_request_with_mode_and_records(
                        context.forwarder.config(),
                        context.forwarder.member_records(),
                        context.identity,
                        &mut context.pairing_replay_tokens.code_approval,
                        peer,
                        &request,
                        now,
                        crate::pairing::PairingAcceptanceMode::CodeApproval,
                    )
                    .map(|_| ())
                    .map_err(crate::pairing_code::PairingCodeError::from)
                });
            if valid.is_err() {
                return send_pairing_code_unavailable(swarm, channel);
            }
            let approval = PendingApproval::new(
                inbound.operation_id,
                peer,
                inbound.session.expires_at_unix_seconds(),
                *request,
            )?;
            let operation_id = approval.operation_id.clone();
            let response = match context.code_pairing_sessions.set_pending_approval(approval) {
                Ok(response) => {
                    context
                        .code_pairing_sessions
                        .record_open_transport(&operation_id, transport);
                    response
                }
                Err(CodePairingSessionError::Capacity) => {
                    context.metrics.record_code_pairing_busy();
                    PairingCodeResponse::Rejected {
                        reason: PairingCodeRejectionReason::Busy,
                    }
                }
                Err(error) => return Err(error.into()),
            };
            if let Err(error) = persist_code_pairing_sessions(
                context.pairing_state_store,
                context.code_pairing_sessions,
                &context.local_capabilities.network_name,
            ) {
                log_pairing_persistence_failure("inbound_approval", &error);
                if let Ok(actions) = context.code_pairing_sessions.cancel(&operation_id) {
                    stop_code_pairing_provider(swarm, actions.stop_providing_locator.as_deref());
                }
                if let Err(error) = persist_code_pairing_sessions(
                    context.pairing_state_store,
                    context.code_pairing_sessions,
                    &context.local_capabilities.network_name,
                ) {
                    log_pairing_persistence_failure("inbound_approval_fail_closed", &error);
                }
                return send_pairing_code_unavailable(swarm, channel);
            }
            send_pairing_code_response(swarm, channel, response)
        }
        PairingCodeRequest::Poll { ticket } => send_pairing_code_response(
            swarm,
            channel,
            context.code_pairing_sessions.poll_response(
                peer,
                &ticket,
                current_unix_seconds_lossy(),
            ),
        ),
    }
}

fn handle_pairing_code_response(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    peer: Libp2pPeerId,
    transport: Option<PairingTransport>,
    request_id: request_response::OutboundRequestId,
    response: PairingCodeResponse,
) -> Result<(), RunnerError> {
    let Some(pending) = context
        .code_pairing_sessions
        .take_outbound_request(request_id)
    else {
        log_runtime_event(
            LogLevel::Warn,
            "pairing_code_unexpected_response",
            &[("peer", &peer.to_string()), ("reason", "unknown_request")],
        );
        return Ok(());
    };
    let expected_peer = match &pending {
        OutboundCodeRequest::Hello(outbound) => outbound.peer,
        OutboundCodeRequest::Submit(outbound) | OutboundCodeRequest::Poll(outbound) => {
            outbound.peer
        }
    };
    if expected_peer != peer {
        release_outbound_code_request(context.code_pairing_sessions, &pending);
        log_runtime_event(
            LogLevel::Warn,
            "pairing_code_unexpected_response",
            &[
                ("peer", &peer.to_string()),
                ("reason", "transport_peer_mismatch"),
            ],
        );
        return Ok(());
    }

    match (pending, response) {
        (OutboundCodeRequest::Hello(outbound), PairingCodeResponse::Challenge { challenge }) => {
            let result = open_pairing_code_challenge_at(
                outbound.pending,
                &challenge,
                peer,
                current_unix_seconds_lossy(),
            );
            let (offer, session) = match result {
                Ok(result) => result,
                Err(error) => {
                    context.code_pairing_sessions.release_peer_attempt(
                        &outbound.operation_id,
                        peer,
                        Instant::now(),
                    );
                    log_runtime_event(
                        LogLevel::Warn,
                        "pairing_code_challenge_rejected",
                        &[("reason", &format!("{error:?}"))],
                    );
                    return Ok(());
                }
            };
            if !context.code_pairing_sessions.select_inviter(
                &outbound.operation_id,
                peer,
                outbound.discovery,
                transport,
            ) {
                return Ok(());
            }
            let Some((requested_vpn_ip, requested_routes)) = context
                .code_pairing_sessions
                .join_request_options(&outbound.operation_id)
            else {
                return Ok(());
            };
            let configured_hostname = if context.forwarder.config().network.dns.enabled {
                context.forwarder.config().network.dns.hostname.as_deref()
            } else {
                None
            };
            let mut request = build_named_pairing_request_at(
                &offer,
                PairingRequestOptions {
                    identity: context.identity.clone(),
                    requested_vpn_ip,
                    requested_routes,
                },
                configured_hostname,
                current_unix_seconds_lossy(),
            )?;
            authenticate_pairing_request(&mut request, &session)
                .map_err(CodePairingSessionError::InvalidCode)?;
            let transcript_sha256 = pairing_request_transcript_sha256(&request)
                .map_err(CodePairingSessionError::InvalidCode)?;
            let operation_id = outbound.operation_id;
            if let Err(error) = context.code_pairing_sessions.set_pending_submission(
                &operation_id,
                peer,
                request,
                offer,
                transcript_sha256,
                Instant::now(),
            ) {
                context.code_pairing_sessions.release_peer_attempt(
                    &operation_id,
                    peer,
                    Instant::now(),
                );
                log_runtime_event(
                    LogLevel::Warn,
                    "pairing_code_submission_rejected",
                    &[("peer", &peer.to_string()), ("reason", &error.to_string())],
                );
                return Ok(());
            }
            if let Err(error) = persist_code_pairing_sessions(
                context.pairing_state_store,
                context.code_pairing_sessions,
                &context.local_capabilities.network_name,
            ) {
                log_pairing_persistence_failure("pending_submission", &error);
                fail_code_pairing_join(
                    context,
                    &operation_id,
                    "pairing request could not be recorded durably",
                )?;
            }
        }
        (
            OutboundCodeRequest::Submit(outbound) | OutboundCodeRequest::Poll(outbound),
            PairingCodeResponse::Pending {
                ticket,
                expires_at_unix_seconds: _,
            },
        ) => {
            context.code_pairing_sessions.record_join_transport(
                &outbound.operation_id,
                peer,
                transport,
            );
            if let Err(error) = context.code_pairing_sessions.set_remote_pending(
                &outbound.operation_id,
                peer,
                outbound.offer,
                outbound.transcript_sha256,
                ticket,
                Instant::now(),
            ) {
                fail_code_pairing_join(
                    context,
                    &outbound.operation_id,
                    "pairing peer returned an invalid approval ticket",
                )?;
                log_runtime_event(
                    LogLevel::Warn,
                    "pairing_code_pending_rejected",
                    &[("peer", &peer.to_string()), ("reason", &error.to_string())],
                );
            } else if let Err(error) = persist_code_pairing_sessions(
                context.pairing_state_store,
                context.code_pairing_sessions,
                &context.local_capabilities.network_name,
            ) {
                context.code_pairing_sessions.release_remote_poll(
                    &outbound.operation_id,
                    peer,
                    Instant::now(),
                );
                log_pairing_persistence_failure("remote_approval_ticket", &error);
            }
        }
        (
            OutboundCodeRequest::Submit(outbound) | OutboundCodeRequest::Poll(outbound),
            PairingCodeResponse::Accepted { response },
        ) => {
            if outbound.offer.payload.inviter_peer != peer.to_string() {
                fail_code_pairing_join(
                    context,
                    &outbound.operation_id,
                    "pairing response transport identity mismatch",
                )?;
                return Ok(());
            }
            let now = current_unix_seconds_lossy();
            if let Err(error) = response.verify_for_offer_at(&outbound.offer, context.identity, now)
            {
                fail_code_pairing_join(
                    context,
                    &outbound.operation_id,
                    "pairing peer returned an invalid acceptance",
                )?;
                log_runtime_event(
                    LogLevel::Warn,
                    "pairing_code_acceptance_rejected",
                    &[
                        ("peer", &peer.to_string()),
                        ("reason", &format!("{error:?}")),
                    ],
                );
                return Ok(());
            }
            context.code_pairing_sessions.record_join_transport(
                &outbound.operation_id,
                peer,
                transport,
            );
            let prepared = match prepare_pairing_runtime_enrollment(
                context.forwarder,
                &outbound.offer,
                &response,
                context.identity,
                now,
            ) {
                Ok(prepared) => prepared,
                Err(error) => {
                    fail_code_pairing_join(
                        context,
                        &outbound.operation_id,
                        "pairing acceptance conflicts with the running network configuration",
                    )?;
                    log_runtime_event(
                        LogLevel::Warn,
                        "pairing_code_enrollment_prepare_failed",
                        &[
                            ("peer", &peer.to_string()),
                            ("reason", &format!("{error:?}")),
                        ],
                    );
                    return Ok(());
                }
            };
            if let Err(error) = context.code_pairing_sessions.prepare_enrollment(
                &context.local_capabilities.network_name,
                PairingEnrollmentPreparation {
                    operation_id: outbound.operation_id.clone(),
                    role: PairingEnrollmentRole::Joiner,
                    approval_id: None,
                    offer: Some(outbound.offer.clone()),
                    response: (*response).clone(),
                    transcript_sha256: outbound.transcript_sha256.clone(),
                    membership_key_preconfigured: Some(
                        context.forwarder.config().network.membership_key.is_some(),
                    ),
                },
            ) {
                fail_code_pairing_join(
                    context,
                    &outbound.operation_id,
                    "pairing acceptance could not be recorded durably",
                )?;
                log_runtime_event(
                    LogLevel::Warn,
                    "pairing_code_enrollment_record_failed",
                    &[("peer", &peer.to_string()), ("reason", &error.to_string())],
                );
                return Ok(());
            }
            if let Err(error) = persist_code_pairing_sessions(
                context.pairing_state_store,
                context.code_pairing_sessions,
                &context.local_capabilities.network_name,
            ) {
                context.code_pairing_sessions.release_remote_poll(
                    &outbound.operation_id,
                    peer,
                    Instant::now(),
                );
                log_pairing_persistence_failure("joiner_prepare", &error);
                return Ok(());
            }
            let remote_peer = match commit_pairing_runtime_enrollment(
                context.forwarder,
                context.membership,
                context.tun_runtime,
                context.local_capabilities,
                prepared,
            ) {
                Ok(peer) => peer,
                Err(error) => {
                    context.code_pairing_sessions.release_remote_poll(
                        &outbound.operation_id,
                        peer,
                        Instant::now(),
                    );
                    log_runtime_event(
                        LogLevel::Error,
                        "pairing_code_enrollment_commit_failed",
                        &[
                            ("peer", &peer.to_string()),
                            ("reason", &format!("{error:?}")),
                        ],
                    );
                    return Ok(());
                }
            };
            promote_all_authenticated_overlay_connections(
                swarm,
                context,
                remote_peer,
                "pairing_acceptance_applied",
            );
            send_control_capabilities_to_connected_peers(
                swarm,
                context.forwarder,
                context.local_capabilities,
                context.metrics,
            );
            if let Err(error) = context.code_pairing_sessions.complete_join(
                &outbound.operation_id,
                outbound.offer,
                *response,
            ) {
                log_runtime_event(
                    LogLevel::Error,
                    "pairing_code_join_finalize_failed",
                    &[("peer", &peer.to_string()), ("reason", &error.to_string())],
                );
                return Ok(());
            }
            if let Err(error) = context
                .code_pairing_sessions
                .mark_enrollment_applied_at(&outbound.operation_id, now)
            {
                log_runtime_event(
                    LogLevel::Error,
                    "pairing_code_enrollment_mark_failed",
                    &[("peer", &peer.to_string()), ("reason", &error.to_string())],
                );
                return Ok(());
            }
            if let Err(error) = persist_code_pairing_sessions(
                context.pairing_state_store,
                context.code_pairing_sessions,
                &context.local_capabilities.network_name,
            ) {
                log_pairing_persistence_failure("joiner_finalization", &error);
            }
            context.metrics.record_code_pairing_completed();
        }
        (OutboundCodeRequest::Hello(outbound), PairingCodeResponse::Rejected { .. }) => {
            context.code_pairing_sessions.release_peer_attempt(
                &outbound.operation_id,
                outbound.peer,
                Instant::now(),
            );
        }
        (OutboundCodeRequest::Submit(outbound), PairingCodeResponse::Rejected { reason }) => {
            if matches!(
                reason,
                PairingCodeRejectionReason::RateLimited | PairingCodeRejectionReason::Busy
            ) {
                context.code_pairing_sessions.release_pending_submission(
                    &outbound.operation_id,
                    outbound.peer,
                    Instant::now(),
                );
            } else if reason == PairingCodeRejectionReason::Unavailable {
                context.code_pairing_sessions.abandon_pending_submission(
                    &outbound.operation_id,
                    outbound.peer,
                    Instant::now(),
                );
            } else {
                fail_code_pairing_join(
                    context,
                    &outbound.operation_id,
                    format!("pairing request rejected: {reason:?}"),
                )?;
            }
        }
        (OutboundCodeRequest::Poll(outbound), PairingCodeResponse::Rejected { reason }) => {
            context.code_pairing_sessions.release_remote_poll(
                &outbound.operation_id,
                outbound.peer,
                Instant::now(),
            );
            if !matches!(
                reason,
                PairingCodeRejectionReason::RateLimited | PairingCodeRejectionReason::Busy
            ) {
                fail_code_pairing_join(
                    context,
                    &outbound.operation_id,
                    format!("pairing approval poll rejected: {reason:?}"),
                )?;
            }
        }
        (pending, response) => {
            let operation_id = match &pending {
                OutboundCodeRequest::Hello(outbound) => outbound.operation_id.as_str(),
                OutboundCodeRequest::Submit(outbound) | OutboundCodeRequest::Poll(outbound) => {
                    outbound.operation_id.as_str()
                }
            }
            .to_owned();
            let expected = outbound_code_request_name(&pending);
            let actual = pairing_code_response_name(&response);
            release_outbound_code_request(context.code_pairing_sessions, &pending);
            if !matches!(&pending, OutboundCodeRequest::Hello(_)) {
                fail_code_pairing_join(
                    context,
                    &operation_id,
                    "pairing peer returned a response for the wrong protocol phase",
                )?;
            }
            log_runtime_event(
                LogLevel::Warn,
                "pairing_code_response_phase_mismatch",
                &[
                    ("peer", &peer.to_string()),
                    ("request_phase", expected),
                    ("response_kind", actual),
                ],
            );
        }
    }
    Ok(())
}

fn release_outbound_code_request(
    sessions: &mut CodePairingSessions,
    request: &OutboundCodeRequest,
) {
    match request {
        OutboundCodeRequest::Hello(outbound) => {
            sessions.release_peer_attempt(&outbound.operation_id, outbound.peer, Instant::now());
        }
        OutboundCodeRequest::Submit(outbound) => {
            sessions.release_pending_submission(
                &outbound.operation_id,
                outbound.peer,
                Instant::now(),
            );
        }
        OutboundCodeRequest::Poll(outbound) => {
            sessions.release_remote_poll(&outbound.operation_id, outbound.peer, Instant::now());
        }
    }
}

fn outbound_code_request_name(request: &OutboundCodeRequest) -> &'static str {
    match request {
        OutboundCodeRequest::Hello(_) => "hello",
        OutboundCodeRequest::Submit(_) => "submit",
        OutboundCodeRequest::Poll(_) => "poll",
    }
}

fn pairing_code_response_name(response: &PairingCodeResponse) -> &'static str {
    match response {
        PairingCodeResponse::Challenge { .. } => "challenge",
        PairingCodeResponse::Accepted { .. } => "accepted",
        PairingCodeResponse::Pending { .. } => "pending",
        PairingCodeResponse::Rejected { .. } => "rejected",
    }
}

fn fail_code_pairing_join(
    context: &mut SwarmEventContext<'_>,
    operation_id: &str,
    reason: impl Into<String>,
) -> Result<(), RunnerError> {
    context
        .code_pairing_sessions
        .fail_join(operation_id, reason);
    if let Err(error) = persist_code_pairing_sessions(
        context.pairing_state_store,
        context.code_pairing_sessions,
        &context.local_capabilities.network_name,
    ) {
        log_pairing_persistence_failure("join_failure", &error);
    }
    Ok(())
}

fn send_pairing_code_unavailable(
    swarm: &mut Swarm<Behaviour>,
    channel: request_response::ResponseChannel<PairingCodeResponse>,
) -> Result<(), RunnerError> {
    send_pairing_code_response(
        swarm,
        channel,
        PairingCodeResponse::Rejected {
            reason: PairingCodeRejectionReason::Unavailable,
        },
    )
}

fn send_pairing_code_response(
    swarm: &mut Swarm<Behaviour>,
    channel: request_response::ResponseChannel<PairingCodeResponse>,
    response: PairingCodeResponse,
) -> Result<(), RunnerError> {
    if swarm
        .behaviour_mut()
        .pairing_code
        .send_response(channel, response)
        .is_err()
    {
        log_runtime_event(
            LogLevel::Warn,
            "pairing_code_response_dropped",
            &[("reason", "response channel closed")],
        );
    }
    Ok(())
}

fn handle_pairing_request_event(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    peer: Libp2pPeerId,
    connection_id: ConnectionId,
    request: &PairingRequest,
    channel: request_response::ResponseChannel<PairingResponse>,
) -> Result<(), RunnerError> {
    context.metrics.record_pairing_request_received();
    let now = Instant::now();
    if !context.pairing_request_rate_limiters.allow(peer, now) {
        context
            .metrics
            .record_pairing_request_rejection(PairingRejectionReason::RateLimited);
        log_pairing_request_rejection(
            peer,
            request,
            &format!(
                "rate_limited limit_per_second={}",
                context.pairing_request_rate_limiters.limit_per_second()
            ),
        );
        drop(channel);
        return Ok(());
    }
    if !context.pairing_handshake_rate_limiter.allow(now) {
        context
            .metrics
            .record_pairing_request_rejection(PairingRejectionReason::RateLimited);
        log_pairing_request_rejection(
            peer,
            request,
            &format!(
                "global_rate_limited limit_per_second={}",
                context.pairing_handshake_rate_limiter.limit_per_second()
            ),
        );
        drop(channel);
        return Ok(());
    }

    match pairing_response_for_request_with_records(
        context.forwarder.config(),
        context.forwarder.member_records(),
        context.identity,
        &mut context.pairing_replay_tokens.file_bearer,
        peer,
        request,
        current_unix_seconds_lossy(),
    ) {
        Ok(response) => {
            let response_for_membership = response.clone();
            if swarm
                .behaviour_mut()
                .pairing
                .send_response(channel, response)
                .is_err()
            {
                log_runtime_event(
                    LogLevel::Warn,
                    "pairing_response_dropped",
                    &[
                        ("peer", &peer.to_string()),
                        ("joiner", &request.payload.joiner_peer),
                    ],
                );
                return Ok(());
            }

            install_pairing_response_membership(
                context.forwarder,
                context.membership,
                context.tun_runtime,
                context.local_capabilities,
                &response_for_membership,
            )?;
            bootstrap_accepted_pairing_peer(
                swarm,
                context,
                peer,
                connection_id,
                &response_for_membership,
            );
            send_control_capabilities_to_connected_peers(
                swarm,
                context.forwarder,
                context.local_capabilities,
                context.metrics,
            );
            context
                .pairing_replay_tokens
                .file_bearer
                .insert(request.payload.rendezvous_token.clone());
            context.metrics.record_pairing_request_accepted();
            log_runtime_event(
                LogLevel::Info,
                "pairing_request_accepted",
                &[
                    ("peer", &peer.to_string()),
                    ("joiner", &request.payload.joiner_peer),
                ],
            );
        }
        Err(error) => {
            context
                .metrics
                .record_pairing_request_rejection(pairing_rejection_reason(&error));
            log_pairing_request_rejection(peer, request, &format!("{error:?}"));
        }
    }

    Ok(())
}

fn install_pairing_response_membership(
    forwarder: &mut Forwarder,
    membership: &mut OverlayMembership,
    tun_runtime: &mut TunRuntimeConfig,
    local_capabilities: &mut ControlCapabilities,
    response: &PairingResponse,
) -> Result<(), RunnerError> {
    if response.payload.member_records.is_empty() {
        return Ok(());
    }

    let now_unix_seconds = current_unix_seconds_lossy();
    let stats =
        forwarder.merge_membership_records(&response.payload.member_records, now_unix_seconds)?;
    if stats.accepted == 0 && stats.removed_expired == 0 && stats.removed_untrusted == 0 {
        return Ok(());
    }

    membership.replace_record_members(
        forwarder.config(),
        forwarder.member_records(),
        now_unix_seconds,
    )?;
    *local_capabilities = refreshed_local_capabilities(local_capabilities, forwarder);
    sync_live_tun_routes_at(forwarder, tun_runtime, now_unix_seconds)?;
    let accepted = stats.accepted.to_string();
    let ignored = stats.ignored_stale_or_equal.to_string();
    let removed_expired = stats.removed_expired.to_string();
    let removed_untrusted = stats.removed_untrusted.to_string();
    log_runtime_event(
        LogLevel::Info,
        "pairing_membership_records_installed",
        &[
            ("accepted", &accepted),
            ("ignored_stale_or_equal", &ignored),
            ("removed_expired", &removed_expired),
            ("removed_untrusted", &removed_untrusted),
        ],
    );

    Ok(())
}

struct PreparedPairingRuntimeEnrollment {
    forwarder: ForwarderUpdate,
    membership: OverlayMembership,
    tun_update: TunRouteUpdate,
    tun_runtime: TunRuntimeConfig,
    membership_tag: Option<String>,
    remote_peer: Libp2pPeerId,
}

fn prepare_pairing_runtime_enrollment(
    forwarder: &Forwarder,
    offer: &PairingOffer,
    response: &PairingResponse,
    identity: &NodeIdentity,
    now_unix_seconds: u64,
) -> Result<PreparedPairingRuntimeEnrollment, RunnerError> {
    let mut current_config = forwarder.config().clone();
    current_config.network.member_records = forwarder.member_records().to_vec();
    let next_config = apply_pairing_response_to_config_at(
        &current_config,
        offer,
        response,
        identity,
        now_unix_seconds,
    )?;
    let remote_peer = if identity.peer_id == response.payload.inviter_peer {
        response
            .payload
            .joiner_peer
            .parse::<Libp2pPeerId>()
            .map_err(crate::pairing::PairingError::from)?
    } else {
        response
            .payload
            .inviter_peer
            .parse::<Libp2pPeerId>()
            .map_err(crate::pairing::PairingError::from)?
    };
    let membership = OverlayMembership::from_config(&next_config)?;
    let current_tun = TunRuntimeConfig::from_config(&current_config)?;
    let next_tun = TunRuntimeConfig::from_config(&next_config)?;
    let tun_update = next_tun.additive_update_from(&current_tun)?;
    let membership_tag = next_config.membership_tag()?;
    let update = forwarder.prepare_reconfigure(next_config, now_unix_seconds)?;

    Ok(PreparedPairingRuntimeEnrollment {
        forwarder: update,
        membership,
        tun_update,
        tun_runtime: next_tun,
        membership_tag,
        remote_peer,
    })
}

fn commit_pairing_runtime_enrollment(
    forwarder: &mut Forwarder,
    membership: &mut OverlayMembership,
    tun_runtime: &mut TunRuntimeConfig,
    local_capabilities: &mut ControlCapabilities,
    prepared: PreparedPairingRuntimeEnrollment,
) -> Result<Libp2pPeerId, RunnerError> {
    commit_pairing_runtime_enrollment_with(
        forwarder,
        membership,
        tun_runtime,
        local_capabilities,
        prepared,
        execute_ip_command,
    )
}

fn commit_pairing_runtime_enrollment_with(
    forwarder: &mut Forwarder,
    membership: &mut OverlayMembership,
    tun_runtime: &mut TunRuntimeConfig,
    local_capabilities: &mut ControlCapabilities,
    prepared: PreparedPairingRuntimeEnrollment,
    execute: impl FnMut(&IpCommand) -> Result<(), RunnerError>,
) -> Result<Libp2pPeerId, RunnerError> {
    execute_tun_route_update(&prepared.tun_update, execute)?;

    let remote_peer = prepared.remote_peer;
    forwarder.commit_reconfigure(prepared.forwarder);
    *membership = prepared.membership;
    *tun_runtime = prepared.tun_runtime;
    *local_capabilities = refreshed_local_capabilities(local_capabilities, forwarder);
    local_capabilities.membership_tag = prepared.membership_tag;
    log_runtime_event(
        LogLevel::Info,
        "pairing_runtime_enrollment_committed",
        &[("peer", &remote_peer.to_string())],
    );

    Ok(remote_peer)
}

fn execute_tun_route_update(
    update: &TunRouteUpdate,
    mut execute: impl FnMut(&IpCommand) -> Result<(), RunnerError>,
) -> Result<(), RunnerError> {
    for (applied, command) in update.apply_commands().iter().enumerate() {
        if let Err(error) = execute(command) {
            for rollback in update.rollback_commands()[..applied].iter().rev() {
                if let Err(rollback_error) = execute(rollback) {
                    log_runtime_event(
                        LogLevel::Error,
                        "pairing_tun_rollback_failed",
                        &[
                            ("command", &rollback.to_string()),
                            ("reason", &format!("{rollback_error:?}")),
                        ],
                    );
                }
            }
            return Err(error);
        }
    }
    Ok(())
}

fn execute_ip_command(command: &IpCommand) -> Result<(), RunnerError> {
    let status = command.execute().map_err(TunRuntimeError::Io)?;
    if status.success() {
        Ok(())
    } else {
        Err(RunnerError::TunRouteCommand {
            command: command.to_string(),
            status,
        })
    }
}

fn bootstrap_accepted_pairing_peer(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    peer: Libp2pPeerId,
    connection_id: ConnectionId,
    response: &PairingResponse,
) {
    let Ok(joiner_peer) = response.payload.joiner_peer.parse::<Libp2pPeerId>() else {
        return;
    };
    if joiner_peer != peer || !context.forwarder.is_configured_transport_peer(peer) {
        return;
    }

    promote_authenticated_overlay_connection(
        swarm,
        context,
        peer,
        connection_id,
        "pairing_membership_installed",
    );
    log_runtime_event(
        LogLevel::Info,
        "pairing_joiner_connection_bootstrapped",
        &[
            ("peer", &peer.to_string()),
            ("connection_id", &connection_id.to_string()),
        ],
    );
}

fn promote_authenticated_overlay_connection(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    peer: Libp2pPeerId,
    connection_id: ConnectionId,
    reason: &str,
) {
    if !context.forwarder.is_configured_transport_peer(peer) {
        return;
    }
    authorize_membership_probe_peer(swarm, context.membership_probe_connections, peer, reason);
    if context.routing_infrastructure_peers.remove(peer) {
        log_runtime_event(
            LogLevel::Info,
            "public_routing_peer_promoted",
            &[("peer", &peer.to_string()), ("reason", reason)],
        );
    }
    remove_overlay_peer_from_infrastructure(
        context.infrastructure_peers,
        context.auto_relay,
        peer,
        reason,
    );

    let endpoint = context
        .active_connections
        .get(&(peer, connection_id))
        .cloned();
    if let Some(endpoint) = endpoint.as_ref() {
        record_path_established_and_maybe_send_packet_plane_hello(
            swarm,
            context.paths,
            context.forwarder,
            context.peer_capabilities,
            context.metrics,
            context.local_capabilities,
            context.identity,
            context.packet_plane,
            context.packet_plane_quic.as_deref(),
            context.packet_plane_negotiator,
            peer,
            connection_id,
            endpoint,
        );
    }

    send_control_capabilities(
        swarm,
        context.forwarder,
        peer,
        context.local_capabilities,
        context.metrics,
    );
    send_service_status_request(
        swarm,
        context.forwarder,
        peer,
        context.local_capabilities,
        context.metrics,
    );
    log_runtime_event(
        LogLevel::Info,
        "authenticated_overlay_connection_promoted",
        &[
            ("peer", &peer.to_string()),
            ("connection_id", &connection_id.to_string()),
            ("had_endpoint", &endpoint.is_some().to_string()),
            ("reason", reason),
        ],
    );
}

fn promote_all_authenticated_overlay_connections(
    swarm: &mut Swarm<Behaviour>,
    context: &mut SwarmEventContext<'_>,
    peer: Libp2pPeerId,
    reason: &str,
) {
    let connection_ids = context
        .active_connections
        .keys()
        .filter_map(|(connected_peer, connection_id)| {
            (*connected_peer == peer).then_some(*connection_id)
        })
        .collect::<Vec<_>>();
    for connection_id in &connection_ids {
        promote_authenticated_overlay_connection(swarm, context, peer, *connection_id, reason);
    }
    if connection_ids.is_empty() && context.forwarder.is_configured_transport_peer(peer) {
        send_control_capabilities(
            swarm,
            context.forwarder,
            peer,
            context.local_capabilities,
            context.metrics,
        );
        send_service_status_request(
            swarm,
            context.forwarder,
            peer,
            context.local_capabilities,
            context.metrics,
        );
    }

    log_runtime_event(
        LogLevel::Info,
        "authenticated_overlay_connections_promoted",
        &[
            ("peer", &peer.to_string()),
            ("connections", &connection_ids.len().to_string()),
            ("reason", reason),
        ],
    );
}

fn sync_live_tun_routes(
    forwarder: &Forwarder,
    installed: &mut TunRuntimeConfig,
) -> Result<(), RunnerError> {
    sync_live_tun_routes_at(forwarder, installed, current_unix_seconds_lossy())
}

fn sync_live_tun_routes_at(
    forwarder: &Forwarder,
    installed: &mut TunRuntimeConfig,
    now_unix_seconds: u64,
) -> Result<(), RunnerError> {
    sync_live_tun_routes_with(forwarder, installed, now_unix_seconds, execute_ip_command)
}

fn sync_live_tun_routes_with(
    forwarder: &Forwarder,
    installed: &mut TunRuntimeConfig,
    now_unix_seconds: u64,
    execute: impl FnMut(&IpCommand) -> Result<(), RunnerError>,
) -> Result<(), RunnerError> {
    let next = TunRuntimeConfig::from_config_with_member_records_at(
        forwarder.config(),
        forwarder.member_records(),
        now_unix_seconds,
    )?;
    let update = next.route_reconciliation_from(installed)?;
    let changed = update.apply_commands().len();
    execute_tun_route_update(&update, execute)?;
    *installed = next;
    if changed > 0 {
        log_runtime_event(
            LogLevel::Info,
            "membership_tun_routes_reconciled",
            &[("commands", &changed.to_string())],
        );
    }

    Ok(())
}

fn log_pairing_request_rejection(peer: Libp2pPeerId, request: &PairingRequest, reason: &str) {
    log_runtime_event(
        LogLevel::Warn,
        "pairing_request_rejected",
        &[
            ("peer", &peer.to_string()),
            ("joiner", &request.payload.joiner_peer),
            ("reason", reason),
        ],
    );
}

fn pairing_rejection_reason(error: &crate::pairing::PairingError) -> PairingRejectionReason {
    match error {
        crate::pairing::PairingError::RendezvousTokenMismatch => {
            PairingRejectionReason::ReplayedToken
        }
        _ => PairingRejectionReason::InvalidOffer,
    }
}

