    #[test]
    fn tun_route_transaction_rolls_back_only_successful_steps() {
        let local = PeerId::from_bytes([1; 32]);
        let remote = PeerId::from_bytes([2; 32]);
        let current = TunRuntimeConfig {
            name: "pv0".to_owned(),
            mtu: 1280,
            addresses: crate::runtime::tun::TunAddresses::for_peer(local),
            additional_addresses: Vec::new(),
            routes: Vec::new(),
        };
        let next = TunRuntimeConfig {
            additional_addresses: vec![
                IpCidr::new(IpAddr::V4(Ipv4Addr::new(10, 42, 0, 1)), 32).expect("local address"),
            ],
            routes: vec![crate::route::Route {
                owner: remote,
                prefix: IpCidr::new(IpAddr::V4(Ipv4Addr::new(10, 42, 0, 2)), 32)
                    .expect("remote route"),
                metric: 0,
            }],
            ..current.clone()
        };
        let update = next
            .additive_update_from(&current)
            .expect("additive update");
        let mut commands = Vec::new();

        let result = execute_tun_route_update(&update, |command| {
            commands.push(command.to_string());
            if commands.len() == 2 {
                Err(RunnerError::ControlSocket(io::Error::other(
                    "injected route failure",
                )))
            } else {
                Ok(())
            }
        });

        assert!(result.is_err());
        assert_eq!(
            commands,
            vec![
                "ip addr replace 10.42.0.1/32 dev pv0",
                "ip route replace 10.42.0.2/32 dev pv0 src 10.42.0.1 metric 3000 mtu 1280 advmss 1240",
                "ip addr del 10.42.0.1/32 dev pv0",
            ]
        );
    }

    #[test]
    fn failed_runtime_commit_keeps_durable_prepared_enrollment() {
        let (config, inviter, joiner, offer, request, response) = code_pairing_runtime_fixture();
        let operation_id = crate::runtime::pairing_sessions::fresh_pairing_operation_id();
        let joiner_peer = joiner.peer_id.parse().expect("joiner peer");
        let approval = PendingApproval::new(operation_id.clone(), joiner_peer, 1_600, request)
            .expect("pending approval");
        let approval_id = approval.approval_id;
        let transcript_sha256 = approval.transcript_sha256;
        let mut sessions = CodePairingSessions::new();
        sessions
            .prepare_enrollment(
                "lab",
                PairingEnrollmentPreparation {
                    operation_id: operation_id.clone(),
                    role: PairingEnrollmentRole::Inviter,
                    approval_id: Some(approval_id),
                    offer: Some(offer.clone()),
                    response: response.clone(),
                    transcript_sha256,
                    membership_key_preconfigured: None,
                },
            )
            .expect("prepared enrollment");
        let state_path = test_pairing_state_path("failed-commit");
        let store = PairingStateStore::new(&state_path);
        persist_code_pairing_sessions(Some(&store), &sessions, "lab")
            .expect("persist write-ahead enrollment");

        let mut forwarder = Forwarder::from_config(&config).expect("forwarder");
        let mut membership = OverlayMembership::from_config(&config).expect("membership");
        let mut tun_runtime = TunRuntimeConfig::from_config(&config).expect("TUN runtime");
        let mut capabilities = ControlCapabilities::local("lab", None, 1280);
        let before_config = forwarder.config().clone();
        let before_membership = membership.clone();
        let before_tun_runtime = tun_runtime.clone();
        let before_capabilities = capabilities.clone();
        let prepared =
            prepare_pairing_runtime_enrollment(&forwarder, &offer, &response, &inviter, 1_011)
                .expect("runtime enrollment");

        let result = commit_pairing_runtime_enrollment_with(
            &mut forwarder,
            &mut membership,
            &mut tun_runtime,
            &mut capabilities,
            prepared,
            |_| {
                Err(RunnerError::ControlSocket(io::Error::other(
                    "injected TUN failure",
                )))
            },
        );

        assert!(result.is_err());
        assert_eq!(forwarder.config(), &before_config);
        assert!(!forwarder.is_configured_transport_peer(joiner_peer));
        assert_eq!(membership, before_membership);
        assert_eq!(tun_runtime, before_tun_runtime);
        assert_eq!(capabilities, before_capabilities);
        let restored = CodePairingSessions::restore_persisted(
            &store.load().expect("load state").expect("state bytes"),
            "lab",
            1_011,
            Instant::now(),
        )
        .expect("restore prepared enrollment");
        assert_eq!(
            restored
                .enrollment(&operation_id)
                .expect("durable enrollment")
                .state,
            PairingEnrollmentState::Prepared
        );
        fs::remove_dir_all(state_path.parent().expect("state directory"))
            .expect("remove test state");
    }

    #[test]
    fn runtime_pairing_commit_preserves_live_records_beyond_response_limit() {
        let inviter = NodeIdentity::generate_ed25519().expect("inviter identity");
        let joiner = NodeIdentity::generate_ed25519().expect("joiner identity");
        let joiner_peer = joiner.peer_id.parse().expect("joiner peer");
        let mut config = config_with_peer(&inviter, joiner_peer);
        config.peers.clear();
        config.network.member_records = vec![
            issue_membership_record_at(
                &inviter,
                MembershipRecordOptions {
                    network_name: "lab".to_owned(),
                    member: inviter.clone(),
                    membership_epoch: 1,
                    sequence: 900,
                    roles: vec![MembershipRole::OverlayMember],
                    route_grants: Vec::new(),
                    expires_at_unix_seconds: None,
                },
                900,
            )
            .expect("root record"),
        ];
        let offer = export_code_pairing_offer_at(&config, PairingOfferOptions::default(), 1_000)
            .expect("code pairing offer");
        let request = build_pairing_request_at(
            &offer,
            PairingRequestOptions {
                identity: joiner.clone(),
                requested_vpn_ip: None,
                requested_routes: Vec::new(),
            },
            1_001,
        )
        .expect("pairing request");
        let existing_count = MAX_PAIRING_MEMBERSHIP_RECORDS + 2;
        let existing_members = (0..existing_count)
            .map(|offset| {
                let member = NodeIdentity::generate_ed25519().expect("existing member");
                let record = issue_membership_record_at(
                    &inviter,
                    MembershipRecordOptions {
                        network_name: "lab".to_owned(),
                        member: member.clone(),
                        membership_epoch: 1,
                        sequence: 901 + u64::try_from(offset).expect("bounded offset"),
                        roles: vec![MembershipRole::OverlayMember],
                        route_grants: Vec::new(),
                        expires_at_unix_seconds: None,
                    },
                    901 + u64::try_from(offset).expect("bounded offset"),
                )
                .expect("existing member record");
                (member, record)
            })
            .collect::<Vec<_>>();
        let mut forwarder = Forwarder::from_config(&config).expect("forwarder");
        forwarder
            .merge_membership_records(
                &existing_members
                    .iter()
                    .map(|(_, record)| record.clone())
                    .collect::<Vec<_>>(),
                1_000,
            )
            .expect("merge converged records");
        let (_, response) = pairing_offer_and_response_for_request_with_grants(
            &config,
            forwarder.member_records(),
            &inviter,
            &mut HashSet::new(),
            joiner_peer,
            &request,
            1_010,
            PairingAcceptanceMode::CodeApproval,
            None,
            Some(Vec::new()),
        )
        .expect("pairing response");
        assert_eq!(response.payload.member_records.len(), 2);

        let mut live_config = config.clone();
        live_config.network.member_records = forwarder.member_records().to_vec();
        let mut membership = OverlayMembership::from_config(&live_config).expect("membership");
        let mut tun_runtime = TunRuntimeConfig::from_config_with_member_records_at(
            forwarder.config(),
            forwarder.member_records(),
            1_011,
        )
        .expect("TUN runtime");
        let mut capabilities = ControlCapabilities::local("lab", None, 1280);
        let prepared =
            prepare_pairing_runtime_enrollment(&forwarder, &offer, &response, &inviter, 1_011)
                .expect("runtime enrollment");
        commit_pairing_runtime_enrollment_with(
            &mut forwarder,
            &mut membership,
            &mut tun_runtime,
            &mut capabilities,
            prepared,
            |_| Ok(()),
        )
        .expect("runtime commit");

        assert_eq!(forwarder.member_records().len(), existing_count + 2);
        for (member, _) in existing_members {
            assert!(
                forwarder
                    .member_records()
                    .iter()
                    .any(|record| { record.payload.member_peer == member.peer_id })
            );
        }
        assert!(forwarder.member_records().iter().any(|record| {
            record.payload.member_peer == joiner.peer_id && !record.payload.revoked
        }));
    }

    #[tokio::test]
    async fn inconsistent_prepared_enrollment_fails_before_runtime_changes() {
        let (config, inviter, joiner, offer, request, response) = code_pairing_runtime_fixture();
        let operation_id = crate::runtime::pairing_sessions::fresh_pairing_operation_id();
        let joiner_peer = joiner.peer_id.parse().expect("joiner peer");
        let mut sessions = CodePairingSessions::new();
        sessions
            .open_with_id(operation_id.clone(), "lab", 600, 1_000, Instant::now())
            .expect("open pairing");
        let approval = PendingApproval::new(operation_id.clone(), joiner_peer, 1_600, request)
            .expect("pending approval");
        let approval_id = approval.approval_id.clone();
        let transcript_sha256 = approval.transcript_sha256.clone();
        sessions
            .set_pending_approval(approval)
            .expect("set pending approval");
        sessions
            .prepare_enrollment(
                "lab",
                PairingEnrollmentPreparation {
                    operation_id: operation_id.clone(),
                    role: PairingEnrollmentRole::Inviter,
                    approval_id: Some(approval_id),
                    offer: Some(offer),
                    response,
                    transcript_sha256,
                    membership_key_preconfigured: None,
                },
            )
            .expect("prepare enrollment");
        sessions
            .cancel(&operation_id)
            .expect("invalidate operation relationship");

        let mut node = pairing_test_node(&inviter);
        let mut forwarder = Forwarder::from_config(&config).expect("forwarder");
        let mut membership = OverlayMembership::from_config(&config).expect("membership");
        let mut tun_runtime = TunRuntimeConfig::from_config(&config).expect("TUN runtime");
        let before_config = forwarder.config().clone();
        let before_membership = membership.clone();
        let before_tun_runtime = tun_runtime.clone();
        let mut commands = Vec::new();

        let result = reconcile_persisted_pairing_enrollments_with(
            &mut node.swarm,
            &mut sessions,
            None,
            &mut forwarder,
            &mut membership,
            &mut tun_runtime,
            &inviter,
            |command| {
                commands.push(command.to_string());
                Ok(())
            },
        );

        assert!(matches!(
            result,
            Err(RunnerError::CodePairingSession(
                CodePairingSessionError::Conflict
            ))
        ));
        assert!(commands.is_empty());
        assert_eq!(forwarder.config(), &before_config);
        assert_eq!(membership, before_membership);
        assert_eq!(tun_runtime, before_tun_runtime);
        assert!(!forwarder.is_configured_transport_peer(joiner_peer));
    }

    #[tokio::test]
    async fn prepared_inviter_enrollment_reconciles_after_expired_restart() {
        let (config, inviter, joiner, offer, request, response) = code_pairing_runtime_fixture();
        let operation_id = crate::runtime::pairing_sessions::fresh_pairing_operation_id();
        let now = Instant::now();
        let mut sessions = CodePairingSessions::new();
        let started = sessions
            .open_with_id(operation_id.clone(), "lab", 15, 1_000, now)
            .expect("open pairing");
        let joiner_peer = joiner.peer_id.parse().expect("joiner peer");
        let approval = PendingApproval::new(
            operation_id.clone(),
            joiner_peer,
            started.expires_at_unix_seconds,
            request,
        )
        .expect("pending approval");
        let approval_id = approval.approval_id.clone();
        let transcript_sha256 = approval.transcript_sha256.clone();
        sessions
            .set_pending_approval(approval)
            .expect("set pending approval");
        sessions
            .prepare_enrollment(
                "lab",
                PairingEnrollmentPreparation {
                    operation_id: operation_id.clone(),
                    role: PairingEnrollmentRole::Inviter,
                    approval_id: Some(approval_id),
                    offer: Some(offer),
                    response,
                    transcript_sha256,
                    membership_key_preconfigured: None,
                },
            )
            .expect("prepare enrollment");

        let state_path = test_pairing_state_path("inviter-restart");
        let store = PairingStateStore::new(&state_path);
        persist_code_pairing_sessions(Some(&store), &sessions, "lab")
            .expect("persist prepared state");
        let mut restored = CodePairingSessions::restore_persisted(
            &store.load().expect("load state").expect("state bytes"),
            "lab",
            1_020,
            now + Duration::from_secs(20),
        )
        .expect("restore expired operation");
        assert!(matches!(
            restored.open_status(&operation_id),
            Ok(PairingOpenStatus::Expired)
        ));

        let mut node = pairing_test_node(&inviter);
        let mut forwarder = Forwarder::from_config(&config).expect("forwarder");
        let mut membership = OverlayMembership::from_config(&config).expect("membership");
        let mut tun_runtime = TunRuntimeConfig::from_config(&config).expect("TUN runtime");
        let mut commands = Vec::new();
        reconcile_persisted_pairing_enrollments_with(
            &mut node.swarm,
            &mut restored,
            Some(&store),
            &mut forwarder,
            &mut membership,
            &mut tun_runtime,
            &inviter,
            |command| {
                commands.push(command.to_string());
                Ok(())
            },
        )
        .expect("reconcile prepared enrollment");

        assert!(forwarder.is_configured_transport_peer(joiner_peer));
        assert!(membership.allows(joiner_peer));
        assert!(matches!(
            restored.open_status(&operation_id),
            Ok(PairingOpenStatus::Completed)
        ));
        assert_eq!(
            restored
                .enrollment(&operation_id)
                .expect("enrollment")
                .state,
            PairingEnrollmentState::Applied
        );
        assert!(!commands.is_empty());

        let command_count = commands.len();
        reconcile_persisted_pairing_enrollments_with(
            &mut node.swarm,
            &mut restored,
            Some(&store),
            &mut forwarder,
            &mut membership,
            &mut tun_runtime,
            &inviter,
            |command| {
                commands.push(command.to_string());
                Ok(())
            },
        )
        .expect("idempotent reconciliation");
        assert_eq!(commands.len(), command_count);

        let persisted = CodePairingSessions::restore_persisted(
            &store.load().expect("load applied").expect("applied bytes"),
            "lab",
            1_020,
            now + Duration::from_secs(20),
        )
        .expect("restore applied state");
        assert_eq!(
            persisted
                .enrollment(&operation_id)
                .expect("persisted enrollment")
                .state,
            PairingEnrollmentState::Applied
        );
        fs::remove_dir_all(state_path.parent().expect("state directory"))
            .expect("remove test state");
    }

    #[tokio::test]
    async fn prepared_joiner_enrollment_reconciles_after_expired_restart() {
        let (mut config, inviter, joiner, offer, request, response) =
            code_pairing_runtime_fixture();
        config.network.local_peer = joiner.peer_id.clone();
        config.network.private_key = Some(joiner.private_key.clone());
        config.network.membership_key = None;
        config.network.member_records.clear();
        config.network.vpn_ip = None;
        let operation_id = crate::runtime::pairing_sessions::fresh_pairing_operation_id();
        let now = Instant::now();
        let mut sessions = CodePairingSessions::new();
        sessions
            .join_with_id(
                operation_id.clone(),
                "lab",
                crate::pairing_code::PairingCode::generate(),
                Some("10.42.0.2".to_owned()),
                Vec::new(),
                15,
                1_000,
                now,
            )
            .expect("join pairing");
        let inviter_peer = inviter.peer_id.parse().expect("inviter peer");
        let joiner_peer = joiner.peer_id.parse().expect("joiner peer");
        let approval = PendingApproval::new(operation_id.clone(), joiner_peer, 1_015, request)
            .expect("ticket fixture");
        let ticket = approval.ticket;
        let transcript_sha256 = approval.transcript_sha256;
        sessions
            .set_remote_pending(
                &operation_id,
                inviter_peer,
                offer.clone(),
                transcript_sha256.clone(),
                ticket,
                now,
            )
            .expect("remote approval");
        sessions
            .prepare_enrollment(
                "lab",
                PairingEnrollmentPreparation {
                    operation_id: operation_id.clone(),
                    role: PairingEnrollmentRole::Joiner,
                    approval_id: None,
                    offer: Some(offer),
                    response,
                    transcript_sha256,
                    membership_key_preconfigured: None,
                },
            )
            .expect("prepare enrollment");

        let state_path = test_pairing_state_path("joiner-restart");
        let store = PairingStateStore::new(&state_path);
        persist_code_pairing_sessions(Some(&store), &sessions, "lab")
            .expect("persist prepared state");
        let mut restored = CodePairingSessions::restore_persisted(
            &store.load().expect("load state").expect("state bytes"),
            "lab",
            1_020,
            now + Duration::from_secs(20),
        )
        .expect("restore expired operation");
        assert!(matches!(
            restored.join_status(&operation_id),
            Ok(PairingJoinStatus::Expired)
        ));

        let mut node = pairing_test_node(&joiner);
        let mut forwarder = Forwarder::from_config(&config).expect("forwarder");
        let mut membership = OverlayMembership::from_config(&config).expect("membership");
        let mut tun_runtime = TunRuntimeConfig::from_config(&config).expect("TUN runtime");
        let mut commands = Vec::new();
        reconcile_persisted_pairing_enrollments_with(
            &mut node.swarm,
            &mut restored,
            Some(&store),
            &mut forwarder,
            &mut membership,
            &mut tun_runtime,
            &joiner,
            |command| {
                commands.push(command.to_string());
                Ok(())
            },
        )
        .expect("reconcile prepared enrollment");

        assert!(forwarder.is_configured_transport_peer(inviter_peer));
        assert!(membership.allows(inviter_peer));
        assert_eq!(
            tun_runtime,
            TunRuntimeConfig::from_config(forwarder.config()).expect("recovered TUN runtime")
        );
        assert!(matches!(
            restored.join_status(&operation_id),
            Ok(PairingJoinStatus::Completed)
        ));
        assert_eq!(
            restored
                .enrollment(&operation_id)
                .expect("enrollment")
                .state,
            PairingEnrollmentState::Applied
        );
        assert!(!commands.is_empty());

        let command_count = commands.len();
        reconcile_persisted_pairing_enrollments_with(
            &mut node.swarm,
            &mut restored,
            Some(&store),
            &mut forwarder,
            &mut membership,
            &mut tun_runtime,
            &joiner,
            |command| {
                commands.push(command.to_string());
                Ok(())
            },
        )
        .expect("idempotent reconciliation");
        assert_eq!(commands.len(), command_count);
        fs::remove_dir_all(state_path.parent().expect("state directory"))
            .expect("remove test state");
    }

    #[test]
    fn code_pairing_mutations_require_durable_daemon_state() {
        assert!(pair_rpc_requires_durable_state(&PairRpcRequest::PairOpen {
            operation_id: "operation".to_owned(),
            expires_in_seconds: 60,
        }));
        assert!(!pair_rpc_requires_durable_state(
            &PairRpcRequest::PairStatus {
                operation_id: "operation".to_owned(),
            }
        ));
        assert!(pair_rpc_requires_durable_state(
            &PairRpcRequest::PairArtifacts {
                operation_id: "operation".to_owned(),
            }
        ));
    }

    #[test]
    fn pairing_response_for_request_issues_authenticated_hostname_records() {
        let inviter = NodeIdentity::generate_ed25519().expect("inviter identity");
        let joiner = NodeIdentity::generate_ed25519().expect("joiner identity");
        let mut config = config_with_peer(&inviter, joiner.peer_id.parse().expect("joiner peer"));
        config.network.dns.enabled = true;
        config.network.dns.hostname = Some("inviter-host".to_owned());
        let offer =
            export_pairing_offer_at(&config, PairingOfferOptions::default(), 1_000).expect("offer");
        let joiner_overlay = PeerId::from_libp2p(joiner.peer_id.parse().expect("joiner peer"));
        let requested_vpn_ip = builtin_ipv4(joiner_overlay).to_string();
        let requested_routes = vec![RouteConfig {
            prefix: "10.42.0.2/32".to_owned(),
            metric: 100,
        }];
        let request = build_named_pairing_request_at(
            &offer,
            PairingRequestOptions {
                identity: joiner.clone(),
                requested_vpn_ip: Some(requested_vpn_ip.clone()),
                requested_routes: requested_routes.clone(),
            },
            Some("JOINER-HOST"),
            1_001,
        )
        .expect("request");
        let mut consumed_tokens = HashSet::new();
        let joiner_peer = joiner.peer_id.parse().expect("joiner peer");

        let response = pairing_response_for_request(
            &config,
            &inviter,
            &mut consumed_tokens,
            joiner_peer,
            &request,
            1_002,
        )
        .expect("response");

        assert_eq!(response.payload.joiner_peer, joiner.peer_id);
        assert_eq!(
            response.payload.assigned_vpn_ip.as_deref(),
            Some(requested_vpn_ip.as_str())
        );
        assert!(response.payload.membership_key.is_none());
        assert_eq!(response.payload.member_records.len(), 2);
        let inviter_record = response
            .payload
            .member_records
            .iter()
            .find(|record| record.payload.member_peer == inviter.peer_id)
            .expect("inviter membership record");
        assert_eq!(
            inviter_record.payload.hostname.as_deref(),
            Some("inviter-host")
        );
        let joiner_record = response
            .payload
            .member_records
            .iter()
            .find(|record| record.payload.member_peer == joiner.peer_id)
            .expect("joiner membership record");
        assert_eq!(joiner_record.payload.member_peer, joiner.peer_id);
        assert_eq!(
            joiner_record.payload.hostname.as_deref(),
            Some("joiner-host")
        );
        assert_eq!(joiner_record.payload.route_grants, requested_routes);
        assert_eq!(
            joiner_record.payload.roles,
            vec![
                MembershipRole::OverlayMember,
                MembershipRole::RouteAuthority
            ]
        );
        assert!(!consumed_tokens.contains(&offer.payload.rendezvous_token));

        let (_, overridden) = pairing_offer_and_response_for_request_with_grants_and_hostname(
            &config,
            &config.network.member_records,
            &inviter,
            &mut HashSet::new(),
            joiner_peer,
            &request,
            1_003,
            PairingAcceptanceMode::FileBearer,
            Some("approved-host".to_owned()),
            None,
            None,
        )
        .expect("response with approved hostname");
        assert_eq!(
            overridden
                .payload
                .member_records
                .iter()
                .find(|record| record.payload.member_peer == joiner.peer_id)
                .expect("overridden joiner record")
                .payload
                .hostname
                .as_deref(),
            Some("approved-host")
        );
    }

    #[test]
    fn code_pairing_response_preserves_delegated_inviter_trust_chain() {
        let root = NodeIdentity::generate_ed25519().expect("root identity");
        let inviter = NodeIdentity::generate_ed25519().expect("inviter identity");
        let joiner = NodeIdentity::generate_ed25519().expect("joiner identity");
        let joiner_peer = joiner.peer_id.parse().expect("joiner peer");
        let mut config = config_with_peer(&inviter, joiner_peer);
        let root_record = issue_membership_record_at(
            &root,
            MembershipRecordOptions {
                network_name: "lab".to_owned(),
                member: root.clone(),
                membership_epoch: 1,
                sequence: 900,
                roles: vec![MembershipRole::OverlayMember],
                route_grants: Vec::new(),
                expires_at_unix_seconds: None,
            },
            900,
        )
        .expect("root record");
        let inviter_record = issue_membership_record_at(
            &root,
            MembershipRecordOptions {
                network_name: "lab".to_owned(),
                member: inviter.clone(),
                membership_epoch: 1,
                sequence: 901,
                roles: vec![MembershipRole::OverlayMember],
                route_grants: Vec::new(),
                expires_at_unix_seconds: None,
            },
            901,
        )
        .expect("inviter grant");
        config.network.member_records = vec![root_record, inviter_record];
        for offset in 0..MAX_PAIRING_MEMBERSHIP_RECORDS {
            let member = NodeIdentity::generate_ed25519().expect("existing member");
            config.network.member_records.push(
                issue_membership_record_at(
                    &root,
                    MembershipRecordOptions {
                        network_name: "lab".to_owned(),
                        member,
                        membership_epoch: 1,
                        sequence: 902 + u64::try_from(offset).expect("bounded offset"),
                        roles: vec![MembershipRole::OverlayMember],
                        route_grants: Vec::new(),
                        expires_at_unix_seconds: None,
                    },
                    902 + u64::try_from(offset).expect("bounded offset"),
                )
                .expect("existing member record"),
            );
        }
        let offer = export_code_pairing_offer_at(&config, PairingOfferOptions::default(), 1_000)
            .expect("code pairing offer");
        let request = build_pairing_request_at(
            &offer,
            PairingRequestOptions {
                identity: joiner.clone(),
                requested_vpn_ip: None,
                requested_routes: Vec::new(),
            },
            1_001,
        )
        .expect("pairing request");

        let response = pairing_response_for_request_with_grants(
            &config,
            &inviter,
            &mut HashSet::new(),
            joiner_peer,
            &request,
            1_002,
            PairingAcceptanceMode::CodeApproval,
            None,
            Some(Vec::new()),
        )
        .expect("delegated pairing response");

        assert_eq!(response.payload.member_records.len(), 3);
        let roots = response
            .payload
            .member_records
            .iter()
            .filter(|record| record.payload.issuer_peer == record.payload.member_peer)
            .collect::<Vec<_>>();
        assert_eq!(roots.len(), 1);
        assert_eq!(roots[0].payload.member_peer, root.peer_id);
        assert!(response.payload.member_records.iter().any(|record| {
            record.payload.issuer_peer == root.peer_id
                && record.payload.member_peer == inviter.peer_id
        }));
        assert!(response.payload.member_records.iter().any(|record| {
            record.payload.issuer_peer == inviter.peer_id
                && record.payload.member_peer == joiner.peer_id
        }));
        assert!(!response.payload.member_records.iter().any(|record| {
            record.payload.issuer_peer == inviter.peer_id
                && record.payload.member_peer == inviter.peer_id
        }));
    }

    #[test]
    fn code_pairing_response_omits_unrelated_expired_membership_records() {
        let inviter = NodeIdentity::generate_ed25519().expect("inviter identity");
        let joiner = NodeIdentity::generate_ed25519().expect("joiner identity");
        let expired_member = NodeIdentity::generate_ed25519().expect("expired member");
        let joiner_peer = joiner.peer_id.parse().expect("joiner peer");
        let mut config = config_with_peer(&inviter, joiner_peer);
        let now = current_unix_seconds_lossy();
        config.network.member_records.push(
            issue_membership_record_at(
                &inviter,
                MembershipRecordOptions {
                    network_name: "lab".to_owned(),
                    member: expired_member.clone(),
                    membership_epoch: 1,
                    sequence: 900,
                    roles: vec![MembershipRole::OverlayMember],
                    route_grants: Vec::new(),
                    expires_at_unix_seconds: Some(now + 60),
                },
                now,
            )
            .expect("expired member record"),
        );
        let offer = export_code_pairing_offer_at(&config, PairingOfferOptions::default(), now)
            .expect("code pairing offer");
        let request = build_pairing_request_at(
            &offer,
            PairingRequestOptions {
                identity: joiner.clone(),
                requested_vpn_ip: None,
                requested_routes: Vec::new(),
            },
            now + 1,
        )
        .expect("pairing request");

        let response = pairing_response_for_request_with_grants(
            &config,
            &inviter,
            &mut HashSet::new(),
            joiner_peer,
            &request,
            now + 61,
            PairingAcceptanceMode::CodeApproval,
            None,
            Some(Vec::new()),
        )
        .expect("pairing response");

        assert_eq!(response.payload.member_records.len(), 2);
        assert!(
            !response
                .payload
                .member_records
                .iter()
                .any(|record| { record.payload.member_peer == expired_member.peer_id })
        );
    }

    #[test]
    fn code_pairing_response_supersedes_prior_joiner_revocation() {
        let inviter = NodeIdentity::generate_ed25519().expect("inviter identity");
        let joiner = NodeIdentity::generate_ed25519().expect("joiner identity");
        let joiner_peer = joiner.peer_id.parse().expect("joiner peer");
        let mut config = config_with_peer(&inviter, joiner_peer);
        let root_record = issue_membership_record_at(
            &inviter,
            MembershipRecordOptions {
                network_name: "lab".to_owned(),
                member: inviter.clone(),
                membership_epoch: 7,
                sequence: 5_000,
                roles: vec![MembershipRole::OverlayMember],
                route_grants: Vec::new(),
                expires_at_unix_seconds: None,
            },
            900,
        )
        .expect("root record");
        let joiner_revocation = issue_membership_record_for_subject_at(
            &inviter,
            MembershipRecordIssueOptions {
                network_name: "lab".to_owned(),
                member: MembershipRecordSubject::from_identity(&joiner).expect("joiner subject"),
                membership_epoch: 7,
                sequence: 5_000,
                revoked: true,
                roles: Vec::new(),
                route_grants: Vec::new(),
                expires_at_unix_seconds: None,
            },
            900,
        )
        .expect("joiner revocation");
        config.network.member_records = vec![root_record, joiner_revocation];
        let offer = export_code_pairing_offer_at(&config, PairingOfferOptions::default(), 1_000)
            .expect("code pairing offer");
        let request = build_pairing_request_at(
            &offer,
            PairingRequestOptions {
                identity: joiner.clone(),
                requested_vpn_ip: None,
                requested_routes: Vec::new(),
            },
            1_001,
        )
        .expect("pairing request");

        let response = pairing_response_for_request_with_grants(
            &config,
            &inviter,
            &mut HashSet::new(),
            joiner_peer,
            &request,
            1_002,
            PairingAcceptanceMode::CodeApproval,
            None,
            Some(Vec::new()),
        )
        .expect("pairing response");
        let joiner_record = response
            .payload
            .member_records
            .iter()
            .find(|record| {
                record.payload.issuer_peer == inviter.peer_id
                    && record.payload.member_peer == joiner.peer_id
            })
            .expect("replacement joiner grant");

        assert_eq!(joiner_record.payload.membership_epoch, 7);
        assert_eq!(joiner_record.payload.sequence, 5_001);
        assert!(!joiner_record.payload.revoked);
        assert!(
            joiner_record
                .payload
                .roles
                .contains(&MembershipRole::OverlayMember)
        );
    }

    #[test]
    fn pairing_membership_version_reports_epoch_and_sequence_exhaustion() {
        let issuer = NodeIdentity::generate_ed25519().expect("issuer");
        let member = NodeIdentity::generate_ed25519().expect("member");
        let record = issue_membership_record_at(
            &issuer,
            MembershipRecordOptions {
                network_name: "lab".to_owned(),
                member: member.clone(),
                membership_epoch: MAX_MEMBERSHIP_RECORD_INTEGER,
                sequence: MAX_MEMBERSHIP_RECORD_INTEGER,
                roles: vec![MembershipRole::OverlayMember],
                route_grants: Vec::new(),
                expires_at_unix_seconds: None,
            },
            900,
        )
        .expect("maximum-version record");

        assert!(matches!(
            next_pairing_membership_version(
                &[record],
                &issuer.peer_id,
                &member.peer_id,
                1_000,
            ),
            Err(crate::pairing::PairingError::MembershipVersionOverflow {
                issuer: exhausted_issuer,
                member: exhausted_member,
            }) if exhausted_issuer == issuer.peer_id && exhausted_member == member.peer_id
        ));
    }

    #[test]
    fn pairing_rejects_implicit_legacy_multi_issuer_migration() {
        let inviter = NodeIdentity::generate_ed25519().expect("inviter identity");
        let other_issuer = NodeIdentity::generate_ed25519().expect("other issuer");
        let existing_a = NodeIdentity::generate_ed25519().expect("existing member a");
        let existing_b = NodeIdentity::generate_ed25519().expect("existing member b");
        let joiner = NodeIdentity::generate_ed25519().expect("joiner identity");
        let joiner_peer = joiner.peer_id.parse().expect("joiner peer");
        let mut config = config_with_peer(&inviter, joiner_peer);
        config.network.member_records = vec![
            issue_membership_record_at(
                &inviter,
                MembershipRecordOptions {
                    network_name: "lab".to_owned(),
                    member: existing_a,
                    membership_epoch: 1,
                    sequence: 900,
                    roles: vec![MembershipRole::OverlayMember],
                    route_grants: Vec::new(),
                    expires_at_unix_seconds: None,
                },
                900,
            )
            .expect("inviter-issued legacy record"),
            issue_membership_record_at(
                &other_issuer,
                MembershipRecordOptions {
                    network_name: "lab".to_owned(),
                    member: existing_b,
                    membership_epoch: 1,
                    sequence: 900,
                    roles: vec![MembershipRole::OverlayMember],
                    route_grants: Vec::new(),
                    expires_at_unix_seconds: None,
                },
                900,
            )
            .expect("other legacy issuer record"),
        ];
        let offer = export_code_pairing_offer_at(&config, PairingOfferOptions::default(), 1_000)
            .expect("code pairing offer");
        let request = build_pairing_request_at(
            &offer,
            PairingRequestOptions {
                identity: joiner,
                requested_vpn_ip: None,
                requested_routes: Vec::new(),
            },
            1_001,
        )
        .expect("pairing request");

        assert!(matches!(
            pairing_response_for_request_with_grants(
                &config,
                &inviter,
                &mut HashSet::new(),
                joiner_peer,
                &request,
                1_002,
                PairingAcceptanceMode::CodeApproval,
                None,
                Some(Vec::new()),
            ),
            Err(crate::pairing::PairingError::LegacyMembershipMigrationRequired {
                inviter: legacy_inviter,
            }) if legacy_inviter == inviter.peer_id
        ));
    }

