    #[tokio::test]
    async fn targeted_recovery_discovery_records_query_attempt() {
        let local_identity = crate::identity::NodeIdentity::generate_ed25519().expect("identity");
        let remote = peer_id();
        let mut node = build_node(&HostConfig {
            identity: local_identity,
            network_name: "lab".to_owned(),
            membership_tag: None,
            mtu: 1280,
            max_concurrent_control_streams: 64,
            max_concurrent_packet_streams: 256,
            listen_addresses: Vec::new(),
            external_addresses: Vec::new(),
            bootstrap_peers: Vec::new(),
            known_peers: Vec::new(),
            relay_reservations: Vec::new(),
            relay_server: false,
            relay_resources: crate::config::RelayResourceConfig::default(),
            resources: crate::config::ResourceConfig::default(),
            discovery: DiscoveryConfig::default(),
        })
        .expect("node");
        let metrics = RuntimeMetrics::default();
        let mut recovery_state = DiscoveredPeerAddresses::default();

        assert!(query_configured_peer_recovery_discovery_for_peer(
            &mut node.swarm,
            "lab",
            None,
            remote,
            &mut recovery_state,
            &metrics,
            "test",
        ));
        assert!(!query_configured_peer_recovery_discovery_for_peer(
            &mut node.swarm,
            "lab",
            None,
            remote,
            &mut recovery_state,
            &metrics,
            "duplicate",
        ));
        let query_started_at = recovery_state
            .recovery_discovery_queries
            .get(&remote)
            .expect("recovery query state")
            .last_query;
        let query_ids = recovery_state
            .recovery_discovery_query_peers
            .keys()
            .copied()
            .collect::<Vec<_>>();
        assert_eq!(query_ids.len(), 2);
        assert!(
            !recovery_state
                .should_query_recovery_discovery_at(remote, query_started_at + REDIAL_INTERVAL)
        );
        for query in query_ids {
            recovery_state.finish_recovery_discovery_query(query);
        }
        assert_eq!(
            recovery_state
                .recovery_discovery_queries
                .get(&remote)
                .expect("completed query cooldown")
                .pending_queries,
            0
        );
        assert!(
            recovery_state
                .should_query_recovery_discovery_at(remote, query_started_at + REDIAL_INTERVAL)
        );

        let snapshot = metrics.snapshot(crate::queue::QueueStats::default());
        assert_eq!(snapshot.kademlia_provider_lookups, 1);
    }

