    fn discovered_address_target_uses_direct_or_relayed_target_peer() {
        let peer = peer_id();
        let relay = peer_id();
        let other = peer_id();
        let direct_without_target: Multiaddr = "/ip4/127.0.0.1/tcp/4001".parse().expect("address");
        let direct_target: Multiaddr = format!("/ip4/127.0.0.1/tcp/4001/p2p/{peer}")
            .parse()
            .expect("address");
        let relayed_without_target: Multiaddr =
            format!("/ip4/127.0.0.1/tcp/4001/p2p/{relay}/p2p-circuit")
                .parse()
                .expect("address");
        let relayed_target: Multiaddr =
            format!("/ip4/127.0.0.1/tcp/4001/p2p/{relay}/p2p-circuit/p2p/{peer}")
                .parse()
                .expect("address");
        let relayed_other_target: Multiaddr =
            format!("/ip4/127.0.0.1/tcp/4001/p2p/{relay}/p2p-circuit/p2p/{other}")
                .parse()
                .expect("address");

        assert!(address_targets_peer(peer, &direct_without_target));
        assert!(address_targets_peer(peer, &direct_target));
        assert!(address_targets_peer(peer, &relayed_without_target));
        assert!(address_targets_peer(peer, &relayed_target));
        assert!(!address_targets_peer(peer, &relayed_other_target));
    }

    #[test]
    fn membership_probe_connections_are_bounded_and_prefer_direct() {
        let peer = peer_id();
        let relay_connection = ConnectionId::new_unchecked(1);
        let duplicate_relay_connection = ConnectionId::new_unchecked(2);
        let direct_connection = ConnectionId::new_unchecked(3);
        let later_relay_connection = ConnectionId::new_unchecked(4);
        let now = Instant::now();
        let mut probes = MembershipProbeConnections::default();

        assert_eq!(
            probes.admit(peer, relay_connection, true, now),
            MembershipProbeAdmission::Admitted
        );
        assert_eq!(
            probes.admit(peer, duplicate_relay_connection, true, now),
            MembershipProbeAdmission::Duplicate
        );
        assert_eq!(
            probes.admit(peer, direct_connection, false, now),
            MembershipProbeAdmission::Replaced(relay_connection)
        );
        assert_eq!(
            probes.admit(peer, later_relay_connection, true, now),
            MembershipProbeAdmission::Duplicate
        );
        assert_eq!(probes.by_peer.len(), 1);

        assert!(!probes.remove(peer, relay_connection));
        assert_eq!(probes.by_peer.len(), 1);
        assert_eq!(
            probes.expired(now + MEMBERSHIP_PROBE_CONNECTION_TTL),
            vec![(peer, direct_connection)]
        );

        probes.defer(
            peer,
            direct_connection,
            now + MEMBERSHIP_PROBE_CONNECTION_TTL,
        );
        assert!(
            probes
                .expired(now + MEMBERSHIP_PROBE_CONNECTION_TTL)
                .is_empty()
        );
        assert_eq!(
            probes.expired(now + MEMBERSHIP_PROBE_CONNECTION_TTL * 2),
            vec![(peer, direct_connection)]
        );

        probes.authorize(peer);
        assert!(probes.by_peer.is_empty());
    }

    #[test]
    fn membership_probe_quarantine_backs_off_and_recovers_on_authorization() {
        let peer = peer_id();
        let first_connection = ConnectionId::new_unchecked(1);
        let second_connection = ConnectionId::new_unchecked(2);
        let now = Instant::now();
        let mut probes = MembershipProbeConnections::default();

        assert_eq!(
            probes.admit(peer, first_connection, false, now),
            MembershipProbeAdmission::Admitted
        );
        let first = probes.quarantine(peer, now);
        assert_eq!(first.active_connection_id, Some(first_connection));
        assert_eq!(first.consecutive_failures, 1);
        assert_eq!(first.delay, MEMBERSHIP_PROBE_QUARANTINE_BASE);
        assert_eq!(
            probes.admit(peer, second_connection, false, now),
            MembershipProbeAdmission::Quarantined
        );
        assert!(
            probes
                .release_ready_quarantines(now + MEMBERSHIP_PROBE_QUARANTINE_BASE / 2)
                .is_empty()
        );

        let retry_at = now + MEMBERSHIP_PROBE_QUARANTINE_BASE;
        assert_eq!(probes.release_ready_quarantines(retry_at), vec![peer]);
        assert_eq!(
            probes.admit(peer, second_connection, false, retry_at),
            MembershipProbeAdmission::Admitted
        );
        let second = probes.quarantine(peer, retry_at);
        assert_eq!(second.consecutive_failures, 2);
        assert_eq!(
            second.delay,
            MEMBERSHIP_PROBE_QUARANTINE_BASE.saturating_mul(2)
        );

        assert!(probes.authorize(peer));
        assert!(probes.by_peer.is_empty());
        assert!(probes.quarantines.is_empty());
    }

    #[test]
    fn membership_probe_quarantine_state_is_bounded() {
        let now = Instant::now();
        let mut probes = MembershipProbeConnections::default();
        let mut last_update = None;

        for _ in 0..=MEMBERSHIP_PROBE_QUARANTINE_CAPACITY {
            last_update = Some(probes.quarantine(peer_id(), now));
        }

        assert_eq!(
            probes.quarantines.len(),
            MEMBERSHIP_PROBE_QUARANTINE_CAPACITY
        );
        assert!(
            last_update
                .expect("last quarantine update")
                .evicted_blocked_peer
                .is_some()
        );
    }

    #[test]
    fn routing_infrastructure_peer_state_is_bounded() {
        let mut routing = RoutingInfrastructurePeers::default();
        let first = peer_id();

        assert_eq!(
            routing.admit(first),
            RoutingInfrastructureAdmission::Admitted
        );
        assert_eq!(
            routing.admit(first),
            RoutingInfrastructureAdmission::Existing
        );
        for _ in 1..KADEMLIA_ROUTING_PEER_CAPACITY {
            assert_eq!(
                routing.admit(peer_id()),
                RoutingInfrastructureAdmission::Admitted
            );
        }

        assert_eq!(routing.len(), KADEMLIA_ROUTING_PEER_CAPACITY);
        assert_eq!(
            routing.admit(peer_id()),
            RoutingInfrastructureAdmission::AtCapacity
        );
        assert_eq!(routing.len(), KADEMLIA_ROUTING_PEER_CAPACITY);
    }

    #[test]
    fn routing_classification_preserves_membership_rejection_history() {
        let now = Instant::now();
        let peer = peer_id();
        let mut probes = MembershipProbeConnections::default();
        let first = probes.quarantine(peer, now);
        assert_eq!(first.consecutive_failures, 1);
        let retry_at = now + first.delay;
        assert_eq!(probes.release_ready_quarantines(retry_at), vec![peer]);
        assert_eq!(
            probes.admit(peer, ConnectionId::new_unchecked(1), false, retry_at),
            MembershipProbeAdmission::Admitted
        );

        classify_membership_probe_as_routing(&mut probes, peer);
        let second = probes.quarantine(peer, retry_at);

        assert_eq!(second.consecutive_failures, 2);
        assert_eq!(
            second.delay,
            MEMBERSHIP_PROBE_QUARANTINE_BASE.saturating_mul(2)
        );
    }

