    #[test]
    fn endpoint_path_kind_prefers_relay_then_quic_then_tcp() {
        let relay: Multiaddr =
            "/ip4/127.0.0.1/tcp/4001/p2p/12D3KooWLSJY9r3syVF7eh1b5CAJSmQkHdHu1QMUGNXk7Nzd4y6f/p2p-circuit/p2p/12D3KooWBCGXBm96czaYf6X41Hd2mD879WoF5Jyi8YUxi2Tiz3aT"
                .parse()
                .expect("relay address");
        let quic: Multiaddr = "/ip4/127.0.0.1/udp/4001/quic-v1"
            .parse()
            .expect("quic address");
        let tcp: Multiaddr = "/ip4/127.0.0.1/tcp/4001".parse().expect("tcp address");

        assert_eq!(
            path_kind_for_endpoint(&ConnectedPoint::Dialer {
                address: relay,
                role_override: Endpoint::Dialer,
                port_use: PortUse::Reuse,
            }),
            PathKind::CircuitRelay
        );
        assert_eq!(
            path_kind_for_endpoint(&ConnectedPoint::Dialer {
                address: quic,
                role_override: Endpoint::Dialer,
                port_use: PortUse::Reuse,
            }),
            PathKind::DirectQuicStream
        );
        assert_eq!(
            path_kind_for_endpoint(&ConnectedPoint::Listener {
                local_addr: tcp,
                send_back_addr: "/ip4/127.0.0.1/tcp/5000".parse().expect("send back"),
            }),
            PathKind::DirectTcpStream
        );
    }

    #[test]
    fn pairing_transport_uses_the_request_response_connection() {
        let peer = peer_id();
        let direct_id = ConnectionId::new_unchecked(1);
        let relay_id = ConnectionId::new_unchecked(2);
        let mut connections = HashMap::new();
        connections.insert(
            (peer, direct_id),
            ConnectedPoint::Dialer {
                address: "/ip4/127.0.0.1/tcp/4001".parse().expect("direct address"),
                role_override: Endpoint::Dialer,
                port_use: PortUse::Reuse,
            },
        );
        connections.insert(
            (peer, relay_id),
            ConnectedPoint::Dialer {
                address: "/ip4/127.0.0.1/tcp/4002/p2p-circuit"
                    .parse()
                    .expect("relay address"),
                role_override: Endpoint::Dialer,
                port_use: PortUse::Reuse,
            },
        );

        assert_eq!(
            pairing_transport_for_connection(&connections, peer, direct_id),
            Some(PairingTransport::Direct)
        );
        assert_eq!(
            pairing_transport_for_connection(&connections, peer, relay_id),
            Some(PairingTransport::Relay)
        );
        assert_eq!(
            pairing_transport_for_connection(&connections, peer, ConnectionId::new_unchecked(3)),
            None
        );
    }

