    #[test]
    fn forwarder_deactivates_and_retains_expired_member_records() {
        let local_identity = crate::identity::NodeIdentity::generate_ed25519().expect("identity");
        let issuer = NodeIdentity::generate_ed25519().expect("issuer");
        let member = NodeIdentity::generate_ed25519().expect("member");
        let member_peer = member.peer_id.parse::<Libp2pPeerId>().expect("member peer");
        let now = current_unix_seconds_lossy();
        let member_record = issue_membership_record_at(
            &issuer,
            MembershipRecordOptions {
                network_name: "lab".to_owned(),
                member,
                membership_epoch: 1,
                sequence: 1,
                roles: vec![
                    MembershipRole::OverlayMember,
                    MembershipRole::RouteAuthority,
                ],
                route_grants: vec![RouteConfig {
                    prefix: "10.88.0.0/24".to_owned(),
                    metric: 100,
                }],
                expires_at_unix_seconds: Some(now + 1),
            },
            now,
        )
        .expect("member record");
        let config = Config {
            network: NetworkConfig {
                dns: crate::dns::DnsConfig::default(),
                name: "lab".to_owned(),
                local_peer: local_identity.peer_id.clone(),
                private_key: Some(local_identity.private_key),
                membership_key: None,
                previous_membership_tags: Vec::new(),
                member_records: vec![member_record],
                vpn_ip: None,
                routes: Vec::new(),
                listen_addresses: Vec::new(),
                external_addresses: Vec::new(),
                bootstrap_peers: Vec::new(),
                discovery: DiscoveryConfig::default(),
                relay: crate::config::RelayConfig::default(),
                packet_plane: crate::config::PacketPlaneConfig::default(),
            },
            interface: InterfaceConfig {
                name: "hs0".to_owned(),
                mtu: 1280,
            },
            peers: Vec::new(),
            queue: QueueConfig {
                max_packets_per_peer: 4,
                max_bytes_per_peer: 4096,
                max_packet_age_millis: 1_000,
            },
            resources: ResourceConfig::default(),
        };
        let mut forwarder = Forwarder::from_config(&config).expect("forwarder");
        let mut membership = OverlayMembership::from_config(&config).expect("membership");
        let mut tun_runtime = TunRuntimeConfig::from_config_with_member_records_at(
            &config,
            &config.network.member_records,
            now,
        )
        .expect("installed TUN routes");

        assert!(membership.allows(member_peer));
        assert!(forwarder.is_configured_transport_peer(member_peer));
        assert!(
            forwarder
                .authorizes_advertised_routes(member_peer, &[ControlRoute::new("10.88.0.0/24", 1)])
        );

        let first_stats = forwarder
            .merge_membership_records(&[], now + 2)
            .expect("stale control merge observed expiry");
        assert_eq!(first_stats.removed_expired, 0);
        let (stats, effective_changed) = forwarder
            .refresh_membership_records(now + 2)
            .expect("refreshed member records");
        membership
            .replace_record_members(forwarder.config(), forwarder.member_records(), now + 2)
            .expect("membership rebuilt");
        let installed_before = tun_runtime.clone();
        let mut failed_runtime = tun_runtime.clone();
        assert!(
            sync_live_tun_routes_with(&forwarder, &mut failed_runtime, now + 2, |_| Err(
                RunnerError::ControlSocket(io::Error::other("injected failure"))
            ),)
            .is_err()
        );
        assert_eq!(failed_runtime, installed_before);
        let mut commands = Vec::new();
        sync_live_tun_routes_with(&forwarder, &mut tun_runtime, now + 2, |command| {
            commands.push(command.to_string());
            Ok(())
        })
        .expect("expired routes removed");

        assert!(effective_changed);
        assert_eq!(stats.removed_expired, 0);
        assert_eq!(forwarder.member_record_count(), 1);
        assert!(forwarder.member_records()[0].is_expired_at(now + 2));
        assert!(!membership.allows(member_peer));
        assert!(!forwarder.is_configured_transport_peer(member_peer));
        assert!(
            !forwarder
                .authorizes_advertised_routes(member_peer, &[ControlRoute::new("10.88.0.0/24", 1)])
        );
        assert!(tun_runtime.routes.is_empty());
        assert_eq!(commands.len(), installed_before.routes.len());
        assert!(
            commands
                .iter()
                .all(|command| command.contains(" route del "))
        );
        assert!(
            commands
                .iter()
                .any(|command| command.contains("10.88.0.0/24"))
        );
    }

    fn membership_record_sync_records(
        record_count: u64,
    ) -> (NodeIdentity, NodeIdentity, Vec<SignedMembershipRecord>) {
        assert!(record_count >= 3);
        let root = NodeIdentity::generate_ed25519().expect("root");
        let local = NodeIdentity::generate_ed25519().expect("local member");
        let remote = NodeIdentity::generate_ed25519().expect("remote member");
        let mut records = vec![
            issue_membership_record_at(
                &root,
                MembershipRecordOptions {
                    network_name: "lab".to_owned(),
                    member: root.clone(),
                    membership_epoch: 1,
                    sequence: 1,
                    roles: vec![MembershipRole::OverlayMember],
                    route_grants: Vec::new(),
                    expires_at_unix_seconds: None,
                },
                1_000,
            )
            .expect("root record"),
            issue_membership_record_at(
                &root,
                MembershipRecordOptions {
                    network_name: "lab".to_owned(),
                    member: local.clone(),
                    membership_epoch: 1,
                    sequence: 2,
                    roles: vec![MembershipRole::OverlayMember],
                    route_grants: Vec::new(),
                    expires_at_unix_seconds: None,
                },
                1_001,
            )
            .expect("local record"),
            issue_membership_record_at(
                &root,
                MembershipRecordOptions {
                    network_name: "lab".to_owned(),
                    member: remote.clone(),
                    membership_epoch: 1,
                    sequence: 3,
                    roles: vec![MembershipRole::OverlayMember],
                    route_grants: Vec::new(),
                    expires_at_unix_seconds: None,
                },
                1_002,
            )
            .expect("remote record"),
        ];
        for sequence in 4..=record_count {
            let member = NodeIdentity::generate_ed25519().expect("additional member");
            records.push(
                issue_membership_record_at(
                    &root,
                    MembershipRecordOptions {
                        network_name: "lab".to_owned(),
                        member,
                        membership_epoch: 1,
                        sequence,
                        roles: vec![MembershipRole::OverlayMember],
                        route_grants: Vec::new(),
                        expires_at_unix_seconds: None,
                    },
                    1_000 + sequence,
                )
                .expect("additional member record"),
            );
        }

        (local, remote, records)
    }

    #[test]
    fn persisted_membership_state_restores_a_learned_peer_after_restart() {
        let root = NodeIdentity::generate_ed25519().expect("root");
        let member = NodeIdentity::generate_ed25519().expect("member");
        let member_peer = member.peer_id.parse().expect("member peer");
        let root_record = issue_membership_record_at(
            &root,
            MembershipRecordOptions {
                network_name: "lab".to_owned(),
                member: root.clone(),
                membership_epoch: 1,
                sequence: 1,
                roles: vec![MembershipRole::OverlayMember],
                route_grants: Vec::new(),
                expires_at_unix_seconds: None,
            },
            1_000,
        )
        .expect("root record");
        let member_record = issue_membership_record_at(
            &root,
            MembershipRecordOptions {
                network_name: "lab".to_owned(),
                member,
                membership_epoch: 1,
                sequence: 2,
                roles: vec![
                    MembershipRole::OverlayMember,
                    MembershipRole::RouteAuthority,
                ],
                route_grants: vec![RouteConfig {
                    prefix: "10.88.0.2/32".to_owned(),
                    metric: 0,
                }],
                expires_at_unix_seconds: None,
            },
            1_001,
        )
        .expect("member record");
        let mut config = config_with_peer(&root, member_peer);
        config.peers.clear();
        config.network.member_records = vec![root_record];
        let mut forwarder = Forwarder::from_config(&config).expect("forwarder");
        forwarder
            .merge_membership_records(&[member_record], 1_001)
            .expect("learn member");

        let path =
            test_pairing_state_path("membership-restart").with_file_name("membership-state.json");
        let store = MembershipStateStore::new(&path);
        let metrics = RuntimeMetrics::default();
        let mut persisted_revision = 0;
        persist_membership_records_if_changed(
            Some(&store),
            &forwarder,
            &root.peer_id,
            &mut persisted_revision,
            &metrics,
        )
        .expect("persist learned state");
        assert_eq!(persisted_revision, forwarder.membership_revision());

        let mut restarted_forwarder = Forwarder::from_config(&config).expect("restart forwarder");
        let mut restarted_membership = OverlayMembership::from_config(&config).expect("membership");
        let mut restarted_tun = TunRuntimeConfig::from_config(&config).expect("startup TUN");
        load_persisted_membership_records(
            Some(&store),
            &mut restarted_forwarder,
            &mut restarted_membership,
            &root.peer_id,
            &metrics,
        )
        .expect("restore learned state");

        assert!(restarted_forwarder.is_configured_transport_peer(member_peer));
        assert!(restarted_membership.allows(member_peer));
        assert_eq!(restarted_forwarder.member_record_count(), 2);
        let snapshot = metrics.snapshot(crate::queue::QueueStats::default());
        assert_eq!(snapshot.membership_state_persists, 1);
        assert_eq!(snapshot.membership_state_records_persisted, 2);
        assert_eq!(snapshot.membership_state_loads, 1);
        assert_eq!(snapshot.membership_state_records_loaded, 2);
        assert_eq!(snapshot.membership_state_load_failures, 0);
        assert_eq!(snapshot.membership_state_persist_failures, 0);
        let mut commands = Vec::new();
        sync_live_tun_routes_with(&restarted_forwarder, &mut restarted_tun, 1_001, |command| {
            commands.push(command.to_string());
            Ok(())
        })
        .expect("restore learned routes");
        assert!(
            commands
                .iter()
                .any(|command| command.contains("route replace 10.88.0.2/32"))
        );
        assert!(
            restarted_tun
                .routes
                .iter()
                .any(|route| route.prefix.to_string() == "10.88.0.2/32")
        );

        fs::remove_dir_all(path.parent().expect("state parent")).expect("remove state directory");
    }

    #[test]
    fn membership_state_failures_are_counted() {
        let local = NodeIdentity::generate_ed25519().expect("local identity");
        let config = config_with_peer(&local, peer_id());
        let mut forwarder = Forwarder::from_config(&config).expect("forwarder");
        let mut membership = OverlayMembership::from_config(&config).expect("membership");
        let metrics = RuntimeMetrics::default();
        let path =
            test_pairing_state_path("membership-failures").with_file_name("membership-state.json");
        fs::write(&path, b"not valid membership state").expect("invalid state fixture");
        let store = MembershipStateStore::new(&path);

        load_persisted_membership_records(
            Some(&store),
            &mut forwarder,
            &mut membership,
            &local.peer_id,
            &metrics,
        )
        .expect_err("invalid persisted state must fail");

        fs::remove_dir_all(path.parent().expect("state parent")).expect("remove state directory");
        persist_membership_records(Some(&store), &forwarder, &local.peer_id, &metrics)
            .expect_err("missing state directory must fail");

        let snapshot = metrics.snapshot(crate::queue::QueueStats::default());
        assert_eq!(snapshot.membership_state_load_failures, 1);
        assert_eq!(snapshot.membership_state_persist_failures, 1);
        assert_eq!(snapshot.membership_state_loads, 0);
        assert_eq!(snapshot.membership_state_persists, 0);
    }

    #[tokio::test]
    async fn membership_record_sync_merges_a_verified_multi_page_snapshot() {
        let (local, remote, records) = membership_record_sync_records(12);
        let mut config = config_with_peer(
            &local,
            remote.peer_id.parse().expect("remote transport peer"),
        );
        config.peers.clear();
        config.network.member_records = records[..2].to_vec();
        let mut forwarder = Forwarder::from_config(&config).expect("forwarder");
        let mut membership = OverlayMembership::from_config(&config).expect("membership");
        let mut node = build_node(&HostConfig {
            identity: local,
            network_name: "lab".to_owned(),
            membership_tag: None,
            mtu: 1280,
            max_concurrent_control_streams: 64,
            max_concurrent_packet_streams: 256,
            listen_addresses: Vec::new(),
            external_addresses: Vec::new(),
            bootstrap_peers: Vec::new(),
            known_peers: Vec::new(),
            relay_reservations: Vec::new(),
            relay_server: false,
            relay_resources: crate::config::RelayResourceConfig::default(),
            resources: crate::config::ResourceConfig::default(),
            discovery: DiscoveryConfig::default(),
        })
        .expect("node");
        let remote_peer = remote.peer_id.parse().expect("remote peer");
        let local_capabilities = ControlCapabilities::local("lab", None, 1280)
            .with_membership_record_inventory(forwarder.member_records());
        let remote_capabilities = ControlCapabilities::local("lab", None, 1280)
            .with_membership_record_inventory(&records);
        let metrics = RuntimeMetrics::default();
        let mut syncs = MembershipRecordSyncs::default();
        send_membership_record_sync_request(
            &mut node.swarm,
            &mut syncs,
            &metrics,
            PendingMembershipRecordSync::first(
                remote_peer,
                &local_capabilities,
                &remote_capabilities,
            ),
        );
        let pending = syncs.pending.values().next().expect("pending request");
        assert_eq!(
            pending.request.snapshot,
            remote_capabilities.membership_records_snapshot
        );
        assert_eq!(
            pending.expected_total_records,
            Some(remote_capabilities.membership_record_count)
        );

        let mut pages = 0;
        while let Some((request_id, request)) = syncs
            .pending
            .iter()
            .next()
            .map(|(request_id, pending)| (*request_id, pending.request.clone()))
        {
            let page = build_membership_records_page(&request, &records, "lab", None, &[])
                .expect("membership page");
            pages += 1;
            if page.next_cursor.is_some() {
                assert_eq!(forwarder.member_records().len(), 2);
            }
            handle_membership_record_sync_response(
                &mut node.swarm,
                &mut forwarder,
                &mut membership,
                &mut syncs,
                &metrics,
                remote_peer,
                request_id,
                ControlResponse::MembershipRecordsPage(page),
                MembershipValidationScope {
                    network: "lab",
                    current_tag: None,
                    previous_tags: &[],
                },
            );
        }

        assert_eq!(pages, 2);
        assert_eq!(forwarder.member_records().len(), records.len());
        assert_eq!(membership.len(), records.len());
        assert!(membership.allows(remote_peer));
        assert_eq!(
            syncs.completed_snapshots.get(&remote_peer),
            Some(&membership_records_snapshot(&records))
        );
        let snapshot = metrics.snapshot(crate::queue::QueueStats::default());
        assert_eq!(snapshot.membership_record_page_requests_sent, 2);
        assert_eq!(snapshot.membership_record_pages_received, 2);
        assert_eq!(snapshot.membership_record_syncs_completed, 1);
        assert_eq!(snapshot.membership_records_accepted, 10);
    }

    #[tokio::test]
    async fn membership_record_sync_rejects_a_tampered_snapshot_without_partial_merge() {
        let (local, remote, records) = membership_record_sync_records(12);
        let mut config = config_with_peer(
            &local,
            remote.peer_id.parse().expect("remote transport peer"),
        );
        config.peers.clear();
        config.network.member_records = records[..2].to_vec();
        let mut forwarder = Forwarder::from_config(&config).expect("forwarder");
        let mut membership = OverlayMembership::from_config(&config).expect("membership");
        let mut node = build_node(&HostConfig {
            identity: local,
            network_name: "lab".to_owned(),
            membership_tag: None,
            mtu: 1280,
            max_concurrent_control_streams: 64,
            max_concurrent_packet_streams: 256,
            listen_addresses: Vec::new(),
            external_addresses: Vec::new(),
            bootstrap_peers: Vec::new(),
            known_peers: Vec::new(),
            relay_reservations: Vec::new(),
            relay_server: false,
            relay_resources: crate::config::RelayResourceConfig::default(),
            resources: crate::config::ResourceConfig::default(),
            discovery: DiscoveryConfig::default(),
        })
        .expect("node");
        let remote_peer = remote.peer_id.parse().expect("remote peer");
        let local_capabilities = ControlCapabilities::local("lab", None, 1280)
            .with_membership_record_inventory(forwarder.member_records());
        let remote_capabilities = ControlCapabilities::local("lab", None, 1280)
            .with_membership_record_inventory(&records);
        let metrics = RuntimeMetrics::default();
        let mut syncs = MembershipRecordSyncs::default();
        send_membership_record_sync_request(
            &mut node.swarm,
            &mut syncs,
            &metrics,
            PendingMembershipRecordSync::first(
                remote_peer,
                &local_capabilities,
                &remote_capabilities,
            ),
        );

        let (first_request_id, first_request) = syncs
            .pending
            .iter()
            .next()
            .map(|(request_id, pending)| (*request_id, pending.request.clone()))
            .expect("first request");
        let first_page = build_membership_records_page(&first_request, &records, "lab", None, &[])
            .expect("first membership page");
        assert!(first_page.next_cursor.is_some());
        handle_membership_record_sync_response(
            &mut node.swarm,
            &mut forwarder,
            &mut membership,
            &mut syncs,
            &metrics,
            remote_peer,
            first_request_id,
            ControlResponse::MembershipRecordsPage(first_page),
            MembershipValidationScope {
                network: "lab",
                current_tag: None,
                previous_tags: &[],
            },
        );
        assert_eq!(forwarder.member_records(), &records[..2]);

        let (second_request_id, second_request) = syncs
            .pending
            .iter()
            .next()
            .map(|(request_id, pending)| (*request_id, pending.request.clone()))
            .expect("second request");
        let mut second_page =
            build_membership_records_page(&second_request, &records, "lab", None, &[])
                .expect("second membership page");
        assert!(second_page.next_cursor.is_none());
        second_page.records[0].payload.sequence =
            second_page.records[0].payload.sequence.saturating_add(1);
        handle_membership_record_sync_response(
            &mut node.swarm,
            &mut forwarder,
            &mut membership,
            &mut syncs,
            &metrics,
            remote_peer,
            second_request_id,
            ControlResponse::MembershipRecordsPage(second_page),
            MembershipValidationScope {
                network: "lab",
                current_tag: None,
                previous_tags: &[],
            },
        );

        assert_eq!(forwarder.member_records(), &records[..2]);
        assert_eq!(membership.len(), 2);
        assert!(syncs.pending.is_empty());
        assert!(syncs.retry_after.contains_key(&remote_peer));
        let snapshot = metrics.snapshot(crate::queue::QueueStats::default());
        assert_eq!(snapshot.membership_record_pages_received, 2);
        assert_eq!(snapshot.membership_record_syncs_completed, 0);
        assert_eq!(snapshot.membership_record_sync_failures, 1);
        assert_eq!(snapshot.membership_records_accepted, 0);
    }

